    Op(path='backend/app/schemas/erp.py', kind='new', final_sha='acd0351baf6cb2e0ff1d3ab386ba23eeaf1611e3bc600524c7d0c55cc8b354d1', encoding='utf-8', executable=False,
       variants=(), content='"""ARCH47-S1:schemas — request and response models of the ERP posting API (app/api/v1/erp.py).\n\nThe console\'s frontend/src/types/erp.ts mirrors every response model field for\nfield (verify_arch47 W3 compares them).\n"""\n\nfrom __future__ import annotations\n\nimport uuid\nfrom datetime import datetime\nfrom typing import Any, Optional\n\nfrom pydantic import BaseModel, ConfigDict, Field\n\n\nclass _In(BaseModel):\n    model_config = ConfigDict(extra="forbid", str_strip_whitespace=True)\n\n\n# -- catalog -----------------------------------------------------------------------------\n\n\nclass PresetInfo(BaseModel):\n    key: str\n    label: str\n    auth_modes: list[str]\n    config_keys: list[str]\n    objects: list[str]\n    idempotency: Optional[str] = None\n    probe_objects: list[str]\n\n\nclass FormatInfo(BaseModel):\n    key: str\n    label: str\n    transports: list[str]\n    objects: list[str]\n\n\nclass ErpCatalog(BaseModel):\n    formats: list[FormatInfo]\n    transports: list[str]\n    presets: list[PresetInfo]\n    ack_modes: dict[str, list[str]]\n    auth_modes: dict[str, list[str]]\n    object_kinds: list[str]\n    object_labels: dict[str, str]\n    source_kinds: list[str]\n    source_labels: dict[str, str]\n    states: list[str]\n    state_labels: dict[str, str]\n    transforms: list[str]\n    header_paths: dict[str, str]\n    line_paths: dict[str, str]\n    language: str\n\n\n# -- targets ------------------------------------------------------------------------------\n\n\nclass TargetCreate(_In):\n    name: str = Field(min_length=1, max_length=120)\n    format: str\n    transport: str\n    preset: str = "NONE"\n    ack_mode: Optional[str] = None\n    auth_mode: Optional[str] = None\n    config: dict[str, Any] = Field(default_factory=dict)\n    credential: Optional[dict[str, Any]] = None\n    lookup_prefix: Optional[str] = Field(default=None, max_length=25)\n    auto_post: bool = False\n    auto_sources: list[str] = Field(default_factory=list)\n    auto_objects: list[str] = Field(default_factory=list)\n    max_attempts: Optional[int] = Field(default=None, ge=1, le=10)\n    ack_timeout_hours: Optional[int] = Field(default=None, ge=1, le=720)\n\n\nclass TargetUpdate(_In):\n    name: Optional[str] = Field(default=None, min_length=1, max_length=120)\n    status: Optional[str] = None\n    ack_mode: Optional[str] = None\n    auth_mode: Optional[str] = None\n    config: Optional[dict[str, Any]] = None\n    auto_post: Optional[bool] = None\n    auto_sources: Optional[list[str]] = None\n    auto_objects: Optional[list[str]] = None\n    max_attempts: Optional[int] = Field(default=None, ge=1, le=10)\n    ack_timeout_hours: Optional[int] = Field(default=None, ge=1, le=720)\n\n\nclass CredentialSet(_In):\n    credential: dict[str, Any]\n\n\nclass TargetRow(BaseModel):\n    id: uuid.UUID\n    name: str\n    format: str\n    transport: str\n    preset: str\n    ack_mode: str\n    auth_mode: str\n    status: str\n    host: Optional[str] = None\n    credential_set: bool\n    credential_fingerprint: Optional[str] = None\n    credential_updated_at: Optional[datetime] = None\n    auto_post: bool\n    auto_post_since: Optional[datetime] = None\n    auto_sources: list[str]\n    auto_objects: list[str]\n    max_attempts: int\n    ack_timeout_hours: int\n    objects: list[str]\n    lookup_prefix: Optional[str] = None\n    postings: int\n    open_exceptions: int\n    created_at: datetime\n    updated_at: datetime\n\n\nclass TargetList(BaseModel):\n    items: list[TargetRow]\n\n\nclass MappingRow(BaseModel):\n    id: uuid.UUID\n    object_kind: str\n    version: int\n    status: str\n    spec: dict[str, Any]\n    spec_sha: str\n    note: Optional[str] = None\n    created_at: datetime\n    retired_at: Optional[datetime] = None\n\n\nclass TargetDetail(BaseModel):\n    target: TargetRow\n    config: dict[str, Any]\n    mappings: list[MappingRow]\n    lookup_tables: list[str]\n\n\nclass TestResult(BaseModel):\n    ok: bool\n    kind: str\n    message: str\n    detail: dict[str, Any] = Field(default_factory=dict)\n\n\n# -- mappings --------------------------------------------------------------------------------\n\n\nclass MappingSave(_In):\n    spec: dict[str, Any]\n    note: Optional[str] = Field(default=None, max_length=300)\n\n\nclass MappingVersions(BaseModel):\n    target_id: uuid.UUID\n    object_kind: str\n    active: Optional[MappingRow] = None\n    versions: list[MappingRow]\n    default_spec: dict[str, Any]\n\n\nclass MappingCheck(BaseModel):\n    valid: bool\n    problems: list[str]\n\n\n# -- lookup tables ------------------------------------------------------------------------------\n\n\nclass LookupCreate(_In):\n    name: str = Field(min_length=1, max_length=64)\n    description: Optional[str] = Field(default=None, max_length=300)\n    entries: dict[str, Any] = Field(default_factory=dict)\n\n\nclass LookupUpdate(_In):\n    description: Optional[str] = Field(default=None, max_length=300)\n    entries: Optional[dict[str, Any]] = None\n    merge: bool = False\n\n\nclass LookupRow(BaseModel):\n    id: uuid.UUID\n    name: str\n    description: Optional[str] = None\n    entries: dict[str, str]\n    entry_count: int\n    revision: int\n    used_by: list[str]\n    updated_at: datetime\n\n\nclass LookupList(BaseModel):\n    items: list[LookupRow]\n\n\n# -- postings ----------------------------------------------------------------------------------\n\n\nclass PostRequest(_In):\n    target_id: uuid.UUID\n    source_kind: str\n    source_id: uuid.UUID\n    object_kinds: list[str] = Field(min_length=1, max_length=5)\n\n\nclass PreviewRequest(_In):\n    target_id: uuid.UUID\n    source_kind: str\n    source_id: uuid.UUID\n    object_kind: str\n    spec: Optional[dict[str, Any]] = None\n\n\nclass ReviewAction(_In):\n    note: Optional[str] = Field(default=None, max_length=500)\n    reference: Optional[str] = Field(default=None, max_length=200)\n\n\nclass AcknowledgeRequest(_In):\n    accepted: Optional[bool] = None\n    reference: Optional[str] = Field(default=None, max_length=200)\n    reason: Optional[str] = Field(default=None, max_length=500)\n    response_text: Optional[str] = Field(default=None, max_length=1_000_000)\n\n\nclass PostingRow(BaseModel):\n    id: uuid.UUID\n    target_id: uuid.UUID\n    target_name: str\n    target_format: str\n    target_preset: str\n    object_kind: str\n    source_kind: str\n    source_id: uuid.UUID\n    work_item_id: Optional[uuid.UUID] = None\n    work_item_filename: Optional[str] = None\n    origin: str\n    state: str\n    document_number: Optional[str] = None\n    amount: Optional[str] = None\n    currency: Optional[str] = None\n    attempts: int\n    max_attempts: int\n    next_attempt_at: Optional[datetime] = None\n    external_id: Optional[str] = None\n    last_error: Optional[str] = None\n    mapping_version: Optional[int] = None\n    rendered_filename: Optional[str] = None\n    content_sha: Optional[str] = None\n    delivered_at: Optional[datetime] = None\n    acknowledged_at: Optional[datetime] = None\n    reviewed_at: Optional[datetime] = None\n    erased: bool\n    created_at: datetime\n    updated_at: datetime\n\n\nclass PostingList(BaseModel):\n    items: list[PostingRow]\n    total: int\n    counts_by_state: dict[str, int]\n\n\nclass AttemptRow(BaseModel):\n    seq: int\n    kind: str\n    outcome: str\n    http_status: Optional[int] = None\n    message: Optional[str] = None\n    detail: dict[str, Any]\n    actor_user_id: Optional[uuid.UUID] = None\n    started_at: datetime\n\n\nclass PostingDetail(BaseModel):\n    posting: PostingRow\n    canonical: Optional[dict[str, Any]] = None\n    mapped: Optional[dict[str, Any]] = None\n    rendered_preview: Optional[str] = None\n    rendered_media_type: Optional[str] = None\n    rendered_size: Optional[int] = None\n    ack: dict[str, Any]\n    control_numbers: dict[str, Any]\n    remote_path: Optional[str] = None\n    idempotency_key: str\n    source_label: Optional[str] = None\n    source_changed: Optional[bool] = None\n    attempts: list[AttemptRow]\n    review_note: Optional[str] = None\n\n\nclass PostResult(BaseModel):\n    object_kind: str\n    posting_id: Optional[uuid.UUID] = None\n    created: bool\n    state: Optional[str] = None\n    error: Optional[str] = None\n\n\nclass PostResponse(BaseModel):\n    results: list[PostResult]\n\n\nclass PreviewResponse(BaseModel):\n    ok: bool\n    canonical: Optional[dict[str, Any]] = None\n    mapped: Optional[dict[str, Any]] = None\n    rendered_preview: Optional[str] = None\n    rendered_media_type: Optional[str] = None\n    filename: Optional[str] = None\n    problems: list[str]\n    notes: list[str]\n\n\nclass OutcomePosting(BaseModel):\n    target_id: uuid.UUID\n    object_kind: str\n    posting_id: Optional[uuid.UUID] = None\n    state: Optional[str] = None\n\n\nclass OutcomeRow(BaseModel):\n    kind: str\n    id: uuid.UUID\n    label: str\n    approved_at: Optional[datetime] = None\n    work_item_id: Optional[uuid.UUID] = None\n    documents: dict[str, str]\n    objects: list[str]\n    postings: list[OutcomePosting]\n\n\nclass OutcomeList(BaseModel):\n    items: list[OutcomeRow]\n\n\n__all__ = [name for name in dir() if name[0].isupper()]\n'),
    Op(path='backend/app/schemas/review.py', kind='edit', final_sha='77d5f445023ae7f27a29026ce980553b44fdadff9fbb3ee49a363f11a86560a8', encoding='utf-8', executable=False,
       variants=(('ffc6a67812008ccf284370909d8edb7509d3f1e7775be9394fedab16e331c29d', (('    obligation_verdict: Optional[str] = None\n\n', '    obligation_verdict: Optional[str] = None\n    #: ARCH47-S1:posting-verdict. POSTING reviews: RETRY, ACCEPT (with the target\'s reference) or CANCEL.\n    posting_verdict: Optional[str] = None\n    posting_reference: Optional[str] = Field(default=None, max_length=200)\n\n    @field_validator("posting_verdict")\n    @classmethod\n    def _known_posting_verdict(cls, value: Optional[str]) -> Optional[str]:\n        if value is None:\n            return None\n        upper = value.strip().upper()\n        if upper not in ("RETRY", "ACCEPT", "CANCEL"):\n            raise ValueError("posting_verdict must be one of: RETRY, ACCEPT, CANCEL")\n        return upper\n\n'),)),) + (), content=''),
    Op(path='backend/app/services/automation/actions/__init__.py', kind='edit', final_sha='afeb42323bbaff83ae7be993abc30129e8319f8e5e429eb4a95e0bd43e63a586', encoding='utf-8', executable=False,
       variants=(('1f067d9b6dc4aa56efcb5486a7e96d07aed59518a0d7edd774d4ef67746889ca', (('    "COMMERCIAL_ACTION_TYPES",\n    "LLM_ACTION_TYPES",\n', '    "COMMERCIAL_ACTION_TYPES",\n    "ERP_ACTION_TYPES",\n    "LLM_ACTION_TYPES",\n'), ('    missing = [a for a in COMMERCIAL_ACTION_TYPES if a not in ACTIONS]\n', '    missing = [a for a in (*COMMERCIAL_ACTION_TYPES, *ERP_ACTION_TYPES) if a not in ACTIONS]\n'), ('    "email.send",\n)\n\nALIASES: Mapping[str, str] = {\n', '    "email.send",\n)\n\n#: ARCH47-S1:erp-action-types. Registered with the others; gated on capability.erp_posting.\nERP_ACTION_TYPES: tuple[str, ...] = ("erp.post",)\n\nALIASES: Mapping[str, str] = {\n'), ('#: predates it and is registered alongside.\n', "#: predates it and is registered alongside; ARCH-47's `erp.post` is sold with\n#: capability.erp_posting and registered alongside too (ERP_ACTION_TYPES).\n"), ('    email_send,\n    work_item_mutate,\n)\n\n', '    email_send,\n    work_item_mutate,\n    erp_post,  # ARCH47-S1:action-erp-post\n)\n\n'), ('    email_send,\n    notify_role,\n', '    email_send,\n    erp_post,\n    notify_role,\n'))),) + (), content=''),
    Op(path='backend/app/services/automation/actions/erp_post.py', kind='new', final_sha='848b90acea7814c9f7b3580fdbb6d44453aef53f37d40419cdfa7033b20521f3', encoding='utf-8', executable=False,
       variants=(), content='"""ARCH47-S1:action — `erp.post`: post the approved outcome a trigger names to an ERP target, exactly once.\n\nOn `procurement.approved` (a three-way match was approved: its case_id) and\n`case.completed` (an ARCH-43 case completed: its case_id), plan one posting per\nconfigured object kind on the configured target. Planning is the ledger\'s\nidempotent insert: a rule that fires twice, two rules posting the same object\nto the same target, or a person pressing "Post" as well all end with ONE\nposting. Delivery happens on the worker (erp.deliver_posting), never inside the\nautomation run.\n\nGUARDRAILS\n  * The target is chosen by the author (config), never by the document; it must\n    be an ACTIVE target of the rule\'s workspace when the rule is saved and runs.\n  * Only the two triggers above carry an approved outcome; the action is\n    refused on any other trigger when the rule is saved.\n  * Needs capability.erp_posting; authoring needs a workspace admin.\n"""\n\nfrom __future__ import annotations\n\nimport uuid\nfrom typing import Any\n\nfrom pydantic import Field, field_validator\n\nfrom app.core.entitlements import ERP_POSTING_CAPABILITY\nfrom app.services.automation.actions.base import (\n    ROLE_WORKSPACE_ADMIN,\n    ActionConfig,\n    ActionDefinition,\n    ActionFailure,\n    ActionOutcome,\n    SaveContext,\n    has_capability,\n)\n\nACTION_TYPE = "erp.post"\n\n\nclass ErpPostConfig(ActionConfig):\n    target_id: uuid.UUID\n    object_kinds: list[str] = Field(min_length=1, max_length=5)\n\n    @field_validator("object_kinds")\n    @classmethod\n    def _known(cls, value: list[str]) -> list[str]:\n        from app.services.erp import vocabulary as v\n\n        unknown = sorted(set(value) - set(v.OBJECT_KINDS))\n        if unknown:\n            raise ValueError(f"Unknown object kind(s): {unknown}.")\n        if len(set(value)) != len(value):\n            raise ValueError("object_kinds must not repeat.")\n        return value\n\n\ndef _target(db: Any, *, workspace_id: uuid.UUID, target_id: uuid.UUID) -> tuple[Any, str | None]:\n    from sqlalchemy import select\n\n    from app.models.erp import ErpTarget\n    from app.services.erp import vocabulary as v\n\n    row = db.execute(select(ErpTarget).where(ErpTarget.id == target_id, ErpTarget.workspace_id == workspace_id)\n                     ).scalar_one_or_none()\n    if row is None:\n        return None, "ERP target not found in this workspace."\n    if row.status != v.TARGET_ACTIVE:\n        return None, "This ERP target is disabled."\n    return row, None\n\n\ndef _validate(ctx: SaveContext, config: ActionConfig) -> dict[str, str]:\n    from app.services.erp import presets as PR\n    from app.services.erp import vocabulary as v\n\n    assert isinstance(config, ErpPostConfig)\n    problems: dict[str, str] = {}\n    unsupported = [k for k in ctx.trigger_keys if k not in v.ACTION_TRIGGER_SOURCES]\n    if unsupported:\n        problems["target_id"] = (f"erp.post runs on {\', \'.join(v.ACTION_TRIGGER_SOURCES)} (an approved outcome); "\n                                 f"not on {\', \'.join(unsupported)}.")\n    target, reason = _target(ctx.db, workspace_id=ctx.workspace_id, target_id=config.target_id)\n    if target is None:\n        problems["target_id"] = reason or "Target unavailable."\n    else:\n        missing = [k for k in config.object_kinds if k not in PR.supported_objects(target.format, target.preset)]\n        if missing:\n            problems["object_kinds"] = f"{target.name} does not take {\', \'.join(missing)}."\n    return problems\n\n\ndef perform(state: Any, spec: Any) -> ActionOutcome:\n    from app.services.automation.triggers import TRIGGER_BY_EVENT\n    from app.services.erp import service\n    from app.services.erp import vocabulary as v\n\n    config = DEFINITION.parse_spec(spec)\n    assert isinstance(config, ErpPostConfig)\n    if not has_capability(state, ERP_POSTING_CAPABILITY):\n        raise ActionFailure("ERP posting is not included in this plan.", recoverable=False)\n    event = getattr(state, "trigger_event", None)\n    trigger = TRIGGER_BY_EVENT.get(getattr(event, "event_type", "") or "")\n    source = v.ACTION_TRIGGER_SOURCES.get(trigger.key if trigger else "")\n    if source is None:\n        raise ActionFailure("erp.post needs a trigger that names an approved outcome.", recoverable=False)\n    key, source_kind = source\n    raw = (getattr(event, "payload", None) or {}).get(key)\n    try:\n        source_id = uuid.UUID(str(raw))\n    except (TypeError, ValueError) as exc:\n        raise ActionFailure(f"The trigger carries no {key}.", recoverable=False) from exc\n    workspace_id = state.execution.workspace_id\n    target, reason = _target(state.db, workspace_id=workspace_id, target_id=config.target_id)\n    if target is None:\n        raise ActionFailure(reason or "Target unavailable.", recoverable=False)\n    planned, existing, failed, ids = 0, 0, [], []\n    for kind in config.object_kinds:\n        try:\n            with state.db.begin_nested():\n                posting, created = service.plan(state.db, target=target, source_kind=source_kind, source_id=source_id,\n                                                object_kind=kind, origin=v.ORIGIN_FLOW, actor_user_id=None)\n            ids.append(str(posting.id))\n            planned += int(created)\n            existing += int(not created)\n        except service.ErpError as exc:\n            failed.append(f"{kind}: {exc}")\n    if failed and not ids:\n        raise ActionFailure("; ".join(failed)[:500], recoverable=False)\n    summary = f"{planned} posting(s) planned, {existing} already in the ledger" + (f", {len(failed)} refused" if failed else "")\n    return ActionOutcome(summary=summary, external_ref=ids[0] if ids else None,\n                         details={"target_id": str(target.id), "postings": ids, "refused": failed})\n\n\nDEFINITION = ActionDefinition(\n    action_type=ACTION_TYPE,\n    label="Post to ERP",\n    description="Post the approved outcome (a reconciled invoice, a completed case) to an ERP target, exactly once.",\n    category="Integrations",\n    config_model=ErpPostConfig,\n    selector="automation.flow.erp_post",\n    perform=perform,\n    capability=ERP_POSTING_CAPABILITY,\n    minimum_role=ROLE_WORKSPACE_ADMIN,\n    validate_resources=_validate,\n)\n'),
    Op(path='backend/app/services/automation/catalog_service.py', kind='edit', final_sha='f404d79118cf3104eed6d6e48bd54e4547b9791a419f25d4b5773ef680cf53a3', encoding='utf-8', executable=False,
       variants=(('821e129dd06d228095ac30bdd0be3865e7d02504086ebdc1456fb63ce131e87a', (('        "mutable_fields": list(MUTABLE_COLUMNS),\n    }\n', '        "mutable_fields": list(MUTABLE_COLUMNS),\n        # ARCH47-S1:catalog-erp-resources\n        "erp_targets": (\n            _erp_targets(db, workspace_id=authoring.workspace_id)\n            if ERP_POSTING_CAPABILITY in authoring.granted_capabilities\n            else []\n        ),\n        "erp_object_kinds": ["VENDOR_BILL", "PURCHASE_ORDER", "GOODS_RECEIPT", "JOURNAL_ENTRY", "PAYMENT_REFERENCE"],\n    }\n'), ('\ndef build(db: Session, *, context: Any) -> dict[str, Any]:\n', '\ndef _erp_targets(db: Session, *, workspace_id: uuid.UUID) -> list[dict[str, Any]]:\n    """ARCH47-S1:catalog-erp-targets. Active ERP targets the erp.post action can name."""\n    from app.models.erp import ErpTarget\n    from app.services.erp import presets as PR\n    from app.services.erp import vocabulary as ev\n\n    rows = db.execute(select(ErpTarget).where(ErpTarget.workspace_id == workspace_id,\n                                              ErpTarget.status == ev.TARGET_ACTIVE)\n                      .order_by(ErpTarget.name)).scalars().all()\n    return [{"id": str(t.id), "label": t.name, "format": t.format, "preset": t.preset,\n             "objects": list(PR.supported_objects(t.format, t.preset))} for t in rows]\n\n\ndef build(db: Session, *, context: Any) -> dict[str, Any]:\n'), ('from app.core.entitlements import WAREHOUSE_SYNC_ADDON\n', 'from app.core.entitlements import ERP_POSTING_CAPABILITY, WAREHOUSE_SYNC_ADDON  # ARCH47-S1:catalog-capability\n'))),) + (), content=''),
    Op(path='backend/app/services/automation/triggers.py', kind='edit', final_sha='9cb646c3d903829cf110f9644521ccffd7ce96a1459f4df8a383c9ebbfd9fb7d', encoding='utf-8', executable=False,
       variants=(('682ebf0face8b12b428ec99409cf4d7771a74cdfc56243d243931bec6a76091e', (('    ),\n)\n', '    ),\n    # ARCH47-S1:trigger-posting-failed. 22 triggers over 23 events after ARCH-47.\n    TriggerSpec(\n        key="posting.failed",\n        label="ERP posting failed",\n        category="ERP posting",\n        description=(\n            "A posting to an ERP or system of record could not be completed: it failed (retries exhausted, or it "\n            "could not be rendered), the target rejected it, the target acknowledged different figures than were "\n            "sent, or the outcome of a send is unknown. Fires once each time a posting enters one of these "\n            "states; the review hub holds it until a person retries, accepts or cancels it."\n        ),\n        event_types=("trigger.posting.failed",),\n        fields=(\n            TriggerField("target", "Target", "string", "QuickBooks Online (production)"),\n            TriggerField("object_kind", "Object", "string", "VENDOR_BILL"),\n            TriggerField("state", "State", "string", "REJECTED"),\n            TriggerField("document_number", "Document number", "string", "INV-2026-0042"),\n            TriggerField("amount", "Amount", "string", "118000.00"),\n            TriggerField("currency", "Currency", "string", "INR"),\n            TriggerField("reason", "Reason", "string", "the target answered 400: 6000 Business Validation Error"),\n            TriggerField("attempts", "Attempts", "number", "3"),\n        ),\n        capability=ERP_POSTING_CAPABILITY,\n        # A posting is not one document (a journal from a table, a payment): document actions are refused by\n        # flow_service, and posting from a posting failure would loop back into the ledger.\n        has_document=False,\n        excluded_actions=("erp.post",),\n    ),\n)\n'), ('    OBLIGATIONS_CAPABILITY,\n    REDACTION_CAPABILITY,\n', '    OBLIGATIONS_CAPABILITY,\n    ERP_POSTING_CAPABILITY,\n    REDACTION_CAPABILITY,\n'))),) + (), content=''),
    Op(path='backend/app/services/compliance/erasure_service.py', kind='edit', final_sha='285c3f9255962b45726c92e172e5370fa1ae835358d2220866795fc00a355f34', encoding='utf-8', executable=False,
       variants=(('716eef93ec9cde416b27cff7b4e100d2c02b949a766fff01c45d8b7fd87eb367', (('    counts["obligations"] = _obligation_service.erase_for_work_items(db, work_item_ids)\n\n', '    counts["obligations"] = _obligation_service.erase_for_work_items(db, work_item_ids)\n    # ARCH47-S1:erasure-erp-postings. A posting quotes its document (figures,\n    # names, lines, the rendered file): what the ledger holds of it is erased;\n    # the ledger row stays (a posting that happened is a fact), and one not yet\n    # delivered is cancelled.\n    from app.services.erp import service as _erp_service\n\n    counts["erp_postings"] = _erp_service.erase_for_work_items(db, work_item_ids)\n\n'),)),) + (), content=''),
    Op(path='backend/app/services/erp/canonical.py', kind='new', final_sha='4c29e78b9fcc985b4627c7bd9eaa3e703ff809e9ad80884c98d4e88fecb2ff67', encoding='utf-8', executable=False,
       variants=(), content='"""ARCH47-S1:canonical — the posting objects every target is rendered from. Pure; no I/O.\n\nA posting object is built from an APPROVED outcome (sources.py loads it) and is\nthe one thing a mapping reads. Five kinds:\n\n  VENDOR_BILL        a supplier\'s invoice to be paid: header (number, dates,\n                     currency, totals, PO reference, terms), the vendor and the\n                     buyer (ARCH-42 ROOT entities: a merged record is posted as\n                     its survivor), and lines (ARCH-31 reconciled lines, an\n                     ARCH-44 confirmed table, or the extracted line items)\n  PURCHASE_ORDER     the order the bill was matched against\n  GOODS_RECEIPT      what was received (quantities), against a PO\n  JOURNAL_ENTRY      balanced debit / credit lines: a confirmed ledger table,\n                     or the accrual of a vendor bill (expenses and tax debited,\n                     the payable credited)\n  PAYMENT_REFERENCE  what to pay whom, when (the bill\'s due date on the\n                     workspace\'s holiday calendar) and against which bill\n\nMoney is Decimal, quantized to the currency\'s ISO 4217 minor units (HALF_UP);\ndates are calendar dates. `check()` refuses an object whose own figures do not\nreconcile: a line whose quantity x price is not its amount, lines that do not\nadd up to the subtotal, a subtotal plus tax that is not the total, a journal\nwhose debits are not its credits. Nothing is posted that does not add up; the\nrefusal names the figures.\n\nThe object\'s JSON (`as_json`) is what mapping paths address; `PATHS` lists\nevery path per kind, so a mapping naming anything else is refused before it\nis saved.\n"""\n\nfrom __future__ import annotations\n\nimport hashlib\nimport json\nfrom dataclasses import dataclass, field\nfrom datetime import date\nfrom decimal import ROUND_HALF_UP, Decimal\nfrom typing import Any, Optional\n\nfrom app.services.erp import vocabulary as v\n\n\nclass BuildError(ValueError):\n    """An outcome cannot become this posting object (missing or inconsistent figures)."""\n\n    def __init__(self, code: str, message: str) -> None:\n        super().__init__(message)\n        self.code = code\n\n\ndef quantum(currency: Optional[str]) -> Decimal:\n    return Decimal(1).scaleb(-v.currency_exponent(currency or ""))\n\n\ndef money(value: Optional[Decimal], currency: Optional[str]) -> Optional[Decimal]:\n    if value is None:\n        return None\n    return Decimal(value).quantize(quantum(currency), rounding=ROUND_HALF_UP)\n\n\ndef qty(value: Optional[Decimal]) -> Optional[Decimal]:\n    if value is None:\n        return None\n    return Decimal(value).quantize(Decimal("0.000001"), rounding=ROUND_HALF_UP).normalize()\n\n\n@dataclass\nclass Party:\n    name: Optional[str] = None\n    entity_id: Optional[str] = None      # the ARCH-42 ROOT entity (merged_into_id followed)\n    tax_id: Optional[str] = None\n    email: Optional[str] = None\n    address: Optional[str] = None\n\n    def as_json(self) -> dict:\n        return {"name": self.name, "entity_id": self.entity_id, "tax_id": self.tax_id, "email": self.email,\n                "address": self.address}\n\n\n@dataclass\nclass Line:\n    number: int\n    description: Optional[str] = None\n    code: Optional[str] = None\n    quantity: Optional[Decimal] = None\n    unit: Optional[str] = None\n    unit_price: Optional[Decimal] = None\n    amount: Optional[Decimal] = None\n    tax_amount: Optional[Decimal] = None\n    account: Optional[str] = None\n    debit: Optional[Decimal] = None\n    credit: Optional[Decimal] = None\n    date: Optional[date] = None\n    reference: Optional[str] = None\n    po_line: Optional[int] = None\n    balancing: bool = False\n    #: A line whose account is fixed by its ROLE, never by a fallback: TAX (input tax), AP (the payable),\n    #: BANK (the paying account). A mapping must map these explicitly (the default mappings refuse to guess).\n    account_code: Optional[str] = None\n\n    def as_json(self) -> dict:\n        return {"number": self.number, "description": self.description, "code": self.code,\n                "quantity": _dec(self.quantity), "unit": self.unit, "unit_price": _dec(self.unit_price),\n                "amount": _dec(self.amount), "tax_amount": _dec(self.tax_amount), "account": self.account,\n                "debit": _dec(self.debit), "credit": _dec(self.credit), "date": _iso(self.date),\n                "reference": self.reference, "po_line": self.po_line, "balancing": self.balancing,\n                "side": "DEBIT" if self.debit else "CREDIT" if self.credit else None,\n                "account_code": self.account_code}\n\n\n@dataclass\nclass PostingObject:\n    kind: str\n    currency: str\n    document_number: Optional[str] = None\n    document_date: Optional[date] = None\n    due_date: Optional[date] = None\n    posting_date: Optional[date] = None\n    po_reference: Optional[str] = None\n    memo: Optional[str] = None\n    payment_terms: Optional[str] = None\n    payment_terms_days: Optional[int] = None\n    subtotal: Optional[Decimal] = None\n    tax_total: Optional[Decimal] = None\n    total: Optional[Decimal] = None\n    vendor: Party = field(default_factory=Party)\n    buyer: Party = field(default_factory=Party)\n    lines: list[Line] = field(default_factory=list)\n    source: dict = field(default_factory=dict)       # kind, id, work_item_id, label, approved_at\n    notes: list[str] = field(default_factory=list)   # how figures were derived (shown with the posting)\n\n    @property\n    def total_debit(self) -> Decimal:\n        return sum((ln.debit or Decimal(0) for ln in self.lines), Decimal(0))\n\n    @property\n    def total_credit(self) -> Decimal:\n        return sum((ln.credit or Decimal(0) for ln in self.lines), Decimal(0))\n\n    def as_json(self) -> dict:\n        return {\n            "kind": self.kind, "currency": self.currency, "document_number": self.document_number,\n            "document_date": _iso(self.document_date), "due_date": _iso(self.due_date),\n            "posting_date": _iso(self.posting_date), "po_reference": self.po_reference, "memo": self.memo,\n            "payment_terms": self.payment_terms, "payment_terms_days": self.payment_terms_days,\n            "subtotal": _dec(self.subtotal), "tax_total": _dec(self.tax_total), "total": _dec(self.total),\n            "total_debit": _dec(money(self.total_debit, self.currency)) if self.kind == v.OBJECT_JOURNAL_ENTRY else None,\n            "total_credit": _dec(money(self.total_credit, self.currency)) if self.kind == v.OBJECT_JOURNAL_ENTRY else None,\n            "line_count": len(self.lines), "vendor": self.vendor.as_json(), "buyer": self.buyer.as_json(),\n            "lines": [ln.as_json() for ln in self.lines], "lines_with_tax": self._lines_with_tax(),\n            "source": dict(self.source), "notes": list(self.notes),\n        }\n\n    def _lines_with_tax(self) -> list[dict]:\n        """The lines, plus one line carrying the tax (code TAX) when there is tax: what an ERP whose bill total\n        is the sum of its lines needs, so the posted total is the invoice\'s total."""\n        out = [ln.as_json() for ln in self.lines]\n        if self.kind in (v.OBJECT_VENDOR_BILL, v.OBJECT_PURCHASE_ORDER) and self.tax_total:\n            number = max((ln.number for ln in self.lines), default=0) + 1\n            out.append(Line(number=number, description="Tax", code="TAX", quantity=Decimal(1),\n                            unit_price=self.tax_total, amount=self.tax_total, account_code="TAX").as_json())\n        return out\n\n    def digest(self) -> str:\n        """sha256 of the object (what was approved, as posted). The notes are explanation, not content."""\n        body = self.as_json()\n        body.pop("notes", None)\n        return hashlib.sha256(json.dumps(body, sort_keys=True, separators=(",", ":")).encode("utf-8")).hexdigest()\n\n\ndef _dec(value: Optional[Decimal]) -> Optional[str]:\n    if value is None:\n        return None\n    text = format(Decimal(value), "f")\n    return text\n\n\ndef _iso(value: Optional[date]) -> Optional[str]:\n    return value.isoformat() if value is not None else None\n\n\n# ---------------------------------------------------------------------------\n# what a mapping may address\n# ---------------------------------------------------------------------------\n\n#: path -> type (text, date, decimal, integer, boolean)\nHEADER_PATHS: dict[str, str] = {\n    "kind": "text", "currency": "text", "document_number": "text", "document_date": "date", "due_date": "date",\n    "posting_date": "date", "po_reference": "text", "memo": "text", "payment_terms": "text",\n    "payment_terms_days": "integer", "subtotal": "decimal", "tax_total": "decimal", "total": "decimal",\n    "total_debit": "decimal", "total_credit": "decimal", "line_count": "integer",\n    "vendor.name": "text", "vendor.entity_id": "text", "vendor.tax_id": "text", "vendor.email": "text",\n    "vendor.address": "text",\n    "buyer.name": "text", "buyer.entity_id": "text", "buyer.tax_id": "text", "buyer.email": "text",\n    "buyer.address": "text",\n    "source.kind": "text", "source.id": "text", "source.work_item_id": "text", "source.label": "text",\n    "source.approved_at": "text",\n    "posting.id": "text", "posting.idempotency_key": "text", "posting.date": "date",\n    #: a payment names the bill it pays: the external id the SAME target gave that bill\'s posting\n    "posting.bill_external_id": "text",\n}\nLINE_PATHS: dict[str, str] = {\n    "line.number": "integer", "line.description": "text", "line.code": "text", "line.quantity": "decimal",\n    "line.unit": "text", "line.unit_price": "decimal", "line.amount": "decimal", "line.tax_amount": "decimal",\n    "line.account": "text", "line.debit": "decimal", "line.credit": "decimal", "line.date": "date",\n    "line.reference": "text", "line.po_line": "integer", "line.balancing": "boolean", "line.side": "text",\n    "line.account_code": "text",\n}\n#: The header fields each kind fills (the others are None, and a mapping requiring one fails at render).\nKIND_HEADER: dict[str, tuple[str, ...]] = {\n    v.OBJECT_VENDOR_BILL: ("document_number", "document_date", "due_date", "po_reference", "subtotal", "tax_total",\n                           "total", "vendor", "buyer", "payment_terms"),\n    v.OBJECT_PURCHASE_ORDER: ("document_number", "document_date", "total", "vendor", "buyer"),\n    v.OBJECT_GOODS_RECEIPT: ("document_number", "document_date", "po_reference", "vendor", "buyer"),\n    v.OBJECT_JOURNAL_ENTRY: ("document_number", "document_date", "total_debit", "total_credit"),\n    v.OBJECT_PAYMENT_REFERENCE: ("document_number", "due_date", "total", "vendor"),\n}\n\n\ndef paths_for(kind: str) -> tuple[dict[str, str], dict[str, str]]:\n    return dict(HEADER_PATHS), dict(LINE_PATHS)\n\n\ndef lookup(obj_json: dict, path: str, line: Optional[dict] = None, extra: Optional[dict] = None) -> Any:\n    """A path\'s value in the object\'s JSON (or the current line\'s; or `extra`: posting.*)."""\n    if path.startswith("line."):\n        return (line or {}).get(path[5:])\n    if path.startswith("posting."):\n        return (extra or {}).get(path[8:])\n    head, _, rest = path.partition(".")\n    value = obj_json.get(head)\n    if rest:\n        return value.get(rest) if isinstance(value, dict) else None\n    return value\n\n\n# ---------------------------------------------------------------------------\n# reconciliation: nothing is posted that does not add up\n# ---------------------------------------------------------------------------\n\n\ndef _within(a: Decimal, b: Decimal, tolerance: Decimal) -> bool:\n    return abs(a - b) <= tolerance\n\n\ndef check(obj: PostingObject) -> PostingObject:\n    """Quantize, reconcile, refuse. Returns the object (quantized) or raises BuildError."""\n    if obj.kind not in v.OBJECT_KINDS:\n        raise BuildError("UNKNOWN_KIND", f"unknown posting object {obj.kind!r}")\n    code = (obj.currency or "").upper()\n    if len(code) != 3 or not code.isalpha():\n        raise BuildError("NO_CURRENCY", "the posting has no ISO 4217 currency (set the workspace currency or read "\n                                         "one from the document)")\n    obj.currency = code\n    q = quantum(code)\n    if len(obj.lines) > v.MAX_LINES:\n        raise BuildError("TOO_MANY_LINES", f"{len(obj.lines)} lines; at most {v.MAX_LINES} are posted at once")\n    for name in ("subtotal", "tax_total", "total"):\n        setattr(obj, name, money(getattr(obj, name), code))\n    for ln in obj.lines:\n        ln.amount = money(ln.amount, code)\n        ln.tax_amount = money(ln.tax_amount, code)\n        ln.debit = money(ln.debit, code)\n        ln.credit = money(ln.credit, code)\n        ln.quantity = qty(ln.quantity)\n        if ln.unit_price is not None:\n            ln.unit_price = Decimal(ln.unit_price).quantize(Decimal("0.000001"), rounding=ROUND_HALF_UP).normalize()\n    if obj.kind == v.OBJECT_JOURNAL_ENTRY:\n        return _check_journal(obj, q)\n    if obj.kind == v.OBJECT_GOODS_RECEIPT:\n        if not obj.lines:\n            raise BuildError("NO_LINES", "a goods receipt needs received lines (quantities)")\n        missing = [ln.number for ln in obj.lines if ln.quantity is None]\n        if missing:\n            raise BuildError("NO_QUANTITY", f"received quantity missing on line(s) {missing}")\n        return obj\n    if obj.kind == v.OBJECT_PAYMENT_REFERENCE:\n        if obj.total is None or obj.total <= 0:\n            raise BuildError("NO_AMOUNT", "a payment needs a positive amount")\n        if not obj.vendor.name:\n            raise BuildError("NO_PAYEE", "a payment needs a payee")\n        return obj\n    # VENDOR_BILL / PURCHASE_ORDER\n    if not obj.lines:\n        raise BuildError("NO_LINES", "no lines")\n    for ln in obj.lines:\n        if ln.amount is None:\n            if ln.quantity is not None and ln.unit_price is not None:\n                ln.amount = money(ln.quantity * ln.unit_price, code)\n            else:\n                raise BuildError("LINE_AMOUNT", f"line {ln.number} has no amount")\n        if ln.quantity is not None and ln.unit_price is not None:\n            tolerance = max(q, abs(ln.quantity) * q / 2)\n            if not _within(ln.quantity * ln.unit_price, ln.amount, tolerance):\n                raise BuildError("LINE_ARITHMETIC", f"line {ln.number}: {ln.quantity} x {ln.unit_price} is "\n                                                    f"{money(ln.quantity * ln.unit_price, code)}, not {ln.amount}")\n    lines_total = sum((ln.amount for ln in obj.lines), Decimal(0))\n    line_tax = sum((ln.tax_amount or Decimal(0) for ln in obj.lines), Decimal(0))\n    tolerance = q * max(1, len(obj.lines))\n    if obj.subtotal is None:\n        obj.subtotal = money(lines_total, code)\n        obj.notes.append("subtotal = the sum of the lines")\n    elif not _within(lines_total, obj.subtotal, tolerance):\n        raise BuildError("SUBTOTAL", f"the lines add up to {money(lines_total, code)}, the subtotal is {obj.subtotal}")\n    if obj.tax_total is None:\n        if obj.total is not None:\n            obj.tax_total = money(obj.total - obj.subtotal, code)\n            obj.notes.append("tax = total - subtotal")\n        else:\n            obj.tax_total = money(line_tax, code)\n    if obj.total is None:\n        obj.total = money(obj.subtotal + obj.tax_total, code)\n        obj.notes.append("total = subtotal + tax")\n    if not _within(obj.subtotal + obj.tax_total, obj.total, q):\n        raise BuildError("TOTAL", f"subtotal {obj.subtotal} + tax {obj.tax_total} is "\n                                  f"{money(obj.subtotal + obj.tax_total, code)}, the total is {obj.total}")\n    if obj.tax_total < 0 or obj.total < 0:\n        raise BuildError("NEGATIVE", "a negative bill is a credit note, which this milestone does not post")\n    return obj\n\n\ndef _check_journal(obj: PostingObject, q: Decimal) -> PostingObject:\n    if len(obj.lines) < 2:\n        raise BuildError("NO_LINES", "a journal entry needs at least two lines")\n    for ln in obj.lines:\n        d, c = ln.debit or Decimal(0), ln.credit or Decimal(0)\n        if d < 0 or c < 0:\n            raise BuildError("NEGATIVE", f"line {ln.number}: debits and credits are positive amounts")\n        if (d > 0) == (c > 0):\n            raise BuildError("ONE_SIDE", f"line {ln.number}: exactly one of debit and credit")\n    if obj.total_debit != obj.total_credit:\n        raise BuildError("UNBALANCED", f"debits {obj.total_debit} are not credits {obj.total_credit}")\n    obj.total = money(obj.total_debit, obj.currency)\n    return obj\n\n\ndef balance(obj: PostingObject, *, account: Optional[str], description: str) -> PostingObject:\n    """Add the balancing line a one-sided set of journal lines needs (its account comes from the mapping)."""\n    diff = obj.total_debit - obj.total_credit\n    if diff == 0:\n        return obj\n    number = max((ln.number for ln in obj.lines), default=0) + 1\n    obj.lines.append(Line(number=number, description=description, account=account,\n                          debit=-diff if diff < 0 else None, credit=diff if diff > 0 else None, balancing=True,\n                          date=obj.document_date))\n    obj.notes.append(f"balancing line {number}: {\'credit\' if diff > 0 else \'debit\'} {money(abs(diff), obj.currency)}")\n    return obj\n\n\ndef accrual(bill: PostingObject) -> PostingObject:\n    """The journal a vendor bill books: each line\'s amount (and its tax) debited, the payable credited."""\n    je = PostingObject(kind=v.OBJECT_JOURNAL_ENTRY, currency=bill.currency, document_number=bill.document_number,\n                       document_date=bill.document_date, posting_date=bill.posting_date, memo=bill.memo,\n                       vendor=bill.vendor, buyer=bill.buyer, source=dict(bill.source), po_reference=bill.po_reference)\n    n = 0\n    for ln in bill.lines:\n        n += 1\n        je.lines.append(Line(number=n, description=ln.description, code=ln.code, account=ln.account, debit=ln.amount,\n                             date=bill.document_date, reference=bill.document_number))\n    if bill.tax_total:\n        n += 1\n        je.lines.append(Line(number=n, description="Input tax", code="TAX", debit=bill.tax_total,\n                             date=bill.document_date, reference=bill.document_number, account_code="TAX"))\n    n += 1\n    je.lines.append(Line(number=n, description=f"Payable to {bill.vendor.name or \'vendor\'}", code="AP",\n                         credit=bill.total, date=bill.document_date, reference=bill.document_number, balancing=True,\n                         account_code="AP"))\n    je.notes.append("accrual of the vendor bill: lines and tax debited, the payable credited")\n    return je\n\n\ndef payment(bill: PostingObject) -> PostingObject:\n    pay = PostingObject(kind=v.OBJECT_PAYMENT_REFERENCE, currency=bill.currency,\n                        document_number=bill.document_number, document_date=bill.document_date,\n                        due_date=bill.due_date, posting_date=bill.posting_date, po_reference=bill.po_reference,\n                        total=bill.total, vendor=bill.vendor, buyer=bill.buyer, payment_terms=bill.payment_terms,\n                        payment_terms_days=bill.payment_terms_days, source=dict(bill.source),\n                        memo=f"Payment of {bill.document_number or \'bill\'}")\n    pay.lines = [Line(number=1, description=f"Bill {bill.document_number or \'\'}".strip(), amount=bill.total,\n                      reference=bill.document_number, date=bill.due_date)]\n    pay.notes = [n for n in bill.notes if "due" in n]\n    return pay\n\n\n__all__ = ["BuildError", "HEADER_PATHS", "KIND_HEADER", "LINE_PATHS", "Line", "Party", "PostingObject", "accrual",\n           "balance", "check", "lookup", "money", "paths_for", "payment", "quantum"]\n'),
    Op(path='backend/app/services/erp/formats/__init__.py', kind='new', final_sha='377275481548daeb6aed40edf6292a122d02b89f6da998384c32110b6c25f5f4', encoding='utf-8', executable=False,
       variants=(), content='"""ARCH47-S1:formats — renderers from a mapped record to bytes, and their validators."""\n'),
    Op(path='backend/app/services/erp/formats/jsonapi.py', kind='new', final_sha='da8dbff4957e8fae971a537b7fcee55c4a2506a01fab54bbb5e2e51f6c674826', encoding='utf-8', executable=False,
       variants=(), content='"""ARCH47-S1:jsonapi — REST / OData presets: request bodies, their contracts, acknowledgements and probes.\n\nPure (no I/O): the transport (transport/http.py) sends what this module builds\nand hands back what came back.\n\nFor every preset and object kind this module knows:\n\n  * the endpoint (method, path under the target\'s base URL) and the key the\n    lines go under;\n  * a JSON Schema of the request body, TRANSCRIBED from the vendor\'s published\n    API reference (QuickBooks Online Accounting API v3, Zoho Books API v3,\n    Business Central API v2.0, S/4HANA OData V2 API_SUPPLIERINVOICE_PROCESS_SRV /\n    API_PURCHASEORDER_PROCESS_SRV / API_MATERIAL_DOCUMENT_SRV, NetSuite REST\n    Record API v1) -- a body the schema refuses is never sent;\n  * the idempotency mechanism when the API has one (QuickBooks `requestid`,\n    NetSuite `X-NetSuite-Idempotency-Key`), else none;\n  * a PROBE: a read that finds an object by our document number, so an\n    uncertain send (a timeout after the request left) is resolved by asking the\n    target rather than by sending again;\n  * how the response ACKNOWLEDGES the posting: the target\'s id for it and the\n    figures it echoes (document number, amount), compared with what was sent --\n    a posting is DONE only when they agree; otherwise MISMATCH.\n\nVerified against these transcriptions and mock servers (verify_arch47), never\nagainst a live ERP: that needs each customer\'s sandbox.\n"""\n\nfrom __future__ import annotations\n\nimport json\nimport re\nfrom dataclasses import dataclass, field\nfrom datetime import date, datetime\nfrom decimal import Decimal, InvalidOperation\nfrom typing import Any, Callable, Mapping, Optional\nfrom urllib.parse import quote\n\nfrom app.services.erp import vocabulary as v\nfrom app.services.erp.mapping import Contract, Record\n\nMEDIA_TYPE = "application/json"\n\n\nclass ApiError(ValueError):\n    pass\n\n\n# ---------------------------------------------------------------------------\n# bodies: exact decimals, nested paths\n# ---------------------------------------------------------------------------\n\n\ndef _set(target: dict, path: str, value: Any) -> None:\n    """Set a dotted path; a numeric segment indexes a list ("LinkedTxn.0.TxnId" -> {"LinkedTxn": [{"TxnId": ..}]})."""\n    parts = path.split(".")\n    node: Any = target\n    for i, part in enumerate(parts):\n        last = i == len(parts) - 1\n        want_list = not last and parts[i + 1].isdigit()\n        if isinstance(node, list):\n            index = int(part)\n            if index > len(node):\n                raise ApiError(f"{path!r}: index {index} skips an element")\n            if index == len(node):\n                node.append(None)\n            key: Any = index\n        else:\n            if part.isdigit():\n                raise ApiError(f"{path!r}: {part} indexes something that is not a list")\n            key = part\n        if last:\n            if isinstance(node[key] if isinstance(node, list) else node.get(key), (dict, list)):\n                raise ApiError(f"{path!r} would replace an object")\n            node[key] = value\n            return\n        current = node[key] if isinstance(node, list) else node.get(key)\n        if current is None:\n            current = [] if want_list else {}\n            node[key] = current\n        elif want_list and not isinstance(current, list) or not want_list and not isinstance(current, dict):\n            raise ApiError(f"{path!r} nests under a value already set at {part!r}")\n        node = current\n\n\ndef body_of(record: Record) -> dict:\n    out: dict = {}\n    for path, value in record.header:\n        if value is not None:\n            _set(out, path, value)\n    if record.lines_to:\n        items = []\n        for line in record.lines:\n            item: dict = {}\n            for path, value in line:\n                if value is not None:\n                    _set(item, path, value)\n            items.append(item)\n        _set(out, record.lines_to, items)\n    return out\n\n\ndef dumps(value: Any) -> str:\n    """JSON with EXACT decimals (a Decimal is written as its digits, never through a float)."""\n    if isinstance(value, dict):\n        return "{" + ",".join(f"{json.dumps(str(k))}:{dumps(v_)}" for k, v_ in value.items()) + "}"\n    if isinstance(value, (list, tuple)):\n        return "[" + ",".join(dumps(x) for x in value) + "]"\n    if isinstance(value, bool) or value is None:\n        return json.dumps(value)\n    if isinstance(value, Decimal):\n        if not value.is_finite():\n            raise ApiError("a non-finite amount")\n        return format(value, "f")\n    if isinstance(value, int):\n        return str(value)\n    if isinstance(value, float):\n        return format(Decimal(str(value)), "f")\n    if isinstance(value, (date, datetime)):\n        return json.dumps(value.isoformat())\n    return json.dumps(str(value), ensure_ascii=False)\n\n\ndef loads(data: bytes | str) -> Any:\n    return json.loads(data, parse_float=Decimal, parse_int=Decimal)\n\n\ndef pointer(doc: Any, ptr: str) -> Any:\n    """RFC 6901 JSON pointer; None when absent."""\n    if ptr in ("", "/"):\n        return doc\n    node = doc\n    for raw in ptr.lstrip("/").split("/"):\n        part = raw.replace("~1", "/").replace("~0", "~")\n        if isinstance(node, list):\n            if not part.isdigit() or int(part) >= len(node):\n                return None\n            node = node[int(part)]\n        elif isinstance(node, dict):\n            if part not in node:\n                return None\n            node = node[part]\n        else:\n            return None\n    return node\n\n\ndef _num(value: Any) -> Optional[Decimal]:\n    if value is None or isinstance(value, bool):\n        return None\n    try:\n        return Decimal(str(value))\n    except (InvalidOperation, ValueError):\n        return None\n\n\n# ---------------------------------------------------------------------------\n# preset definitions\n# ---------------------------------------------------------------------------\n\n\n@dataclass(frozen=True)\nclass Echo:\n    """A figure the response echoes, compared with what was sent: (response pointer, body pointer or a function)."""\n\n    name: str\n    response: str\n    expected: Callable[[dict], Any]\n    numeric: bool = False\n\n\n@dataclass(frozen=True)\nclass Endpoint:\n    method: str\n    path: str                        # under the base URL; {placeholders} from the target config\n    lines_to: Optional[str]\n    schema: dict\n    id_pointer: Optional[str]        # where the response carries the target\'s id (None: Location header)\n    echoes: tuple[Echo, ...] = ()\n    doc_number: Optional[str] = None  # the body pointer of our document number (probe key, mismatch check)\n    probe: Optional[str] = None       # GET path; {doc} is the URL-encoded document number\n    probe_list: Optional[str] = None  # pointer to the result list in the probe response\n    probe_id: Optional[str] = None    # pointer (inside one result) to the id\n    wrap: Optional[str] = None        # the response wraps the object under this key (QBO: "Bill")\n    follow_location: bool = False     # read the created record back from Location to compare the echoes\n\n\n@dataclass(frozen=True)\nclass Preset:\n    key: str\n    label: str\n    auth: tuple[str, ...]\n    config_keys: tuple[str, ...]\n    endpoints: Mapping[str, Endpoint]\n    idempotency_query: Optional[str] = None\n    idempotency_header: Optional[str] = None\n    csrf: bool = False                # S/4HANA OData V2: fetch an x-csrf-token before a write\n    headers: Mapping[str, str] = field(default_factory=dict)\n    error_text: Callable[[Any], str] = lambda body: ""\n    duplicate: Callable[[int, Any], bool] = lambda status, body: False\n\n    def contract(self, object_kind: str) -> Contract:\n        ep = self.endpoints[object_kind]\n        return Contract(open=True, lines_to=ep.lines_to, needs_lines=ep.lines_to is not None)\n\n\ndef _ref(required: bool = True) -> dict:\n    return {"type": "object", "required": ["value"] if required else [],\n            "properties": {"value": {"type": "string", "minLength": 1}}}\n\n\n_DATE = {"type": "string", "pattern": r"^\\d{4}-\\d{2}-\\d{2}$"}\n_NUM = {"type": "number"}\n_STR = {"type": "string"}\n\n\ndef _sum(lines_key: str, amount: str) -> Callable[[dict], Decimal]:\n    def fn(body: dict) -> Decimal:\n        return sum((_num(pointer(x, amount)) or Decimal(0) for x in (pointer(body, lines_key) or [])), Decimal(0))\n    return fn\n\n\ndef _sum_product(lines_key: str, qty: str, price: str) -> Callable[[dict], Decimal]:\n    def fn(body: dict) -> Decimal:\n        total = Decimal(0)\n        for x in pointer(body, lines_key) or []:\n            total += (_num(pointer(x, qty)) or Decimal(0)) * (_num(pointer(x, price)) or Decimal(0))\n        return total\n    return fn\n\n\ndef _at(ptr: str) -> Callable[[dict], Any]:\n    return lambda body: pointer(body, ptr)\n\n\n# -- QuickBooks Online (Accounting API v3) ------------------------------------------\ndef _qbo_error(body: Any) -> str:\n    errors = pointer(body, "/Fault/Error") or []\n    return "; ".join(f"{e.get(\'code\', \'\')} {e.get(\'Message\', \'\')}: {e.get(\'Detail\', \'\')}".strip() for e in errors\n                     if isinstance(e, dict))[:500]\n\n\ndef _qbo_duplicate(status: int, body: Any) -> bool:\n    return status == 400 and any(str(e.get("code")) == "6140" for e in (pointer(body, "/Fault/Error") or [])\n                                 if isinstance(e, dict))\n\n\n_QBO_LINE = {"type": "object", "required": ["DetailType", "Amount", "AccountBasedExpenseLineDetail"],\n             "properties": {"DetailType": {"const": "AccountBasedExpenseLineDetail"}, "Amount": _NUM,\n                            "Description": {"type": "string", "maxLength": 4000},\n                            "AccountBasedExpenseLineDetail": {"type": "object", "required": ["AccountRef"],\n                                                              "properties": {"AccountRef": _ref()}}}}\n_QBO_BILL = {"type": "object", "required": ["VendorRef", "Line"],\n             "properties": {"VendorRef": _ref(), "Line": {"type": "array", "minItems": 1, "items": _QBO_LINE},\n                            "DocNumber": {"type": "string", "maxLength": 21}, "TxnDate": _DATE, "DueDate": _DATE,\n                            "CurrencyRef": _ref(False), "PrivateNote": {"type": "string", "maxLength": 4000}}}\n_QBO_PO = {"type": "object", "required": ["VendorRef", "APAccountRef", "Line"],\n           "properties": {"VendorRef": _ref(), "APAccountRef": _ref(), "Line": {"type": "array", "minItems": 1,\n                                                                                 "items": _QBO_LINE},\n                          "DocNumber": {"type": "string", "maxLength": 21}, "TxnDate": _DATE}}\n_QBO_JE = {"type": "object", "required": ["Line"],\n           "properties": {"DocNumber": {"type": "string", "maxLength": 21}, "TxnDate": _DATE,\n                          "Line": {"type": "array", "minItems": 2, "items": {\n                              "type": "object", "required": ["DetailType", "Amount", "JournalEntryLineDetail"],\n                              "properties": {"DetailType": {"const": "JournalEntryLineDetail"}, "Amount": _NUM,\n                                             "JournalEntryLineDetail": {\n                                                 "type": "object", "required": ["PostingType", "AccountRef"],\n                                                 "properties": {"PostingType": {"enum": ["Debit", "Credit"]},\n                                                                "AccountRef": _ref()}}}}}}}\n_QBO_PAY = {"type": "object", "required": ["VendorRef", "PayType", "TotalAmt", "Line"],\n            "properties": {"VendorRef": _ref(), "PayType": {"enum": ["Check", "CreditCard"]}, "TotalAmt": _NUM,\n                           "CheckPayment": {"type": "object", "properties": {"BankAccountRef": _ref()}},\n                           "Line": {"type": "array", "minItems": 1, "items": {\n                               "type": "object", "required": ["Amount", "LinkedTxn"],\n                               "properties": {"Amount": _NUM, "LinkedTxn": {"type": "array", "minItems": 1}}}}}}\n_QBO_BASE = "/v3/company/{realm_id}"\nQBO = Preset(\n    key=v.PRESET_QBO, label="QuickBooks Online", auth=(v.AUTH_OAUTH2_REFRESH, v.AUTH_BEARER), config_keys=("realm_id",),\n    idempotency_query="requestid", headers={"Accept": "application/json"}, error_text=_qbo_error,\n    duplicate=_qbo_duplicate,\n    endpoints={\n        v.OBJECT_VENDOR_BILL: Endpoint("POST", _QBO_BASE + "/bill?minorversion=75", "Line", _QBO_BILL, "/Bill/Id",\n                                       (Echo("document_number", "/Bill/DocNumber", _at("/DocNumber")),\n                                        Echo("total", "/Bill/TotalAmt", _sum("/Line", "/Amount"), True)),\n                                       doc_number="/DocNumber",\n                                       probe=_QBO_BASE + "/query?query=select%20Id%2C%20DocNumber%2C%20TotalAmt%20from%20Bill%20where%20DocNumber%20%3D%20%27{doc}%27",\n                                       probe_list="/QueryResponse/Bill", probe_id="/Id"),\n        v.OBJECT_PURCHASE_ORDER: Endpoint("POST", _QBO_BASE + "/purchaseorder?minorversion=75", "Line", _QBO_PO,\n                                          "/PurchaseOrder/Id",\n                                          (Echo("document_number", "/PurchaseOrder/DocNumber", _at("/DocNumber")),\n                                           Echo("total", "/PurchaseOrder/TotalAmt", _sum("/Line", "/Amount"), True)),\n                                          doc_number="/DocNumber",\n                                          probe=_QBO_BASE + "/query?query=select%20Id%20from%20PurchaseOrder%20where%20DocNumber%20%3D%20%27{doc}%27",\n                                          probe_list="/QueryResponse/PurchaseOrder", probe_id="/Id"),\n        v.OBJECT_JOURNAL_ENTRY: Endpoint("POST", _QBO_BASE + "/journalentry?minorversion=75", "Line", _QBO_JE,\n                                         "/JournalEntry/Id",\n                                         (Echo("document_number", "/JournalEntry/DocNumber", _at("/DocNumber")),),\n                                         doc_number="/DocNumber",\n                                         probe=_QBO_BASE + "/query?query=select%20Id%20from%20JournalEntry%20where%20DocNumber%20%3D%20%27{doc}%27",\n                                         probe_list="/QueryResponse/JournalEntry", probe_id="/Id"),\n        v.OBJECT_PAYMENT_REFERENCE: Endpoint("POST", _QBO_BASE + "/billpayment?minorversion=75", "Line", _QBO_PAY,\n                                             "/BillPayment/Id",\n                                             (Echo("total", "/BillPayment/TotalAmt", _at("/TotalAmt"), True),)),\n    })\n\n# -- Zoho Books (API v3) ------------------------------------------------------------\n_ZOHO_LINE = {"type": "object", "required": ["account_id", "rate", "quantity"],\n              "properties": {"account_id": {"type": "string", "minLength": 1}, "rate": _NUM, "quantity": _NUM,\n                             "description": _STR, "item_id": _STR}}\n_ZOHO_BILL = {"type": "object", "required": ["vendor_id", "bill_number", "date", "line_items"],\n              "properties": {"vendor_id": {"type": "string", "minLength": 1}, "bill_number": {"type": "string",\n                                                                                               "minLength": 1},\n                             "date": _DATE, "due_date": _DATE, "currency_id": _STR, "reference_number": _STR,\n                             "notes": _STR, "line_items": {"type": "array", "minItems": 1, "items": _ZOHO_LINE}}}\n_ZOHO_PO = {"type": "object", "required": ["vendor_id", "line_items"],\n            "properties": {"vendor_id": {"type": "string", "minLength": 1}, "purchaseorder_number": _STR,\n                           "date": _DATE, "line_items": {"type": "array", "minItems": 1, "items": {\n                               "type": "object", "required": ["rate", "quantity"],\n                               "properties": {"item_id": _STR, "account_id": _STR, "rate": _NUM, "quantity": _NUM,\n                                              "description": _STR}}}}}\n_ZOHO_JE = {"type": "object", "required": ["journal_date", "line_items"],\n            "properties": {"journal_date": _DATE, "reference_number": _STR, "notes": _STR,\n                           "line_items": {"type": "array", "minItems": 2, "items": {\n                               "type": "object", "required": ["account_id", "debit_or_credit", "amount"],\n                               "properties": {"account_id": {"type": "string", "minLength": 1},\n                                              "debit_or_credit": {"enum": ["debit", "credit"]}, "amount": _NUM}}}}}\n_ZOHO_PAY = {"type": "object", "required": ["vendor_id", "amount", "date", "bills"],\n             "properties": {"vendor_id": {"type": "string", "minLength": 1}, "amount": _NUM, "date": _DATE,\n                            "paid_through_account_id": _STR, "reference_number": _STR,\n                            "bills": {"type": "array", "minItems": 1, "items": {\n                                "type": "object", "required": ["bill_id", "amount_applied"],\n                                "properties": {"bill_id": {"type": "string", "minLength": 1},\n                                               "amount_applied": _NUM}}}}}\n\n\ndef _zoho_error(body: Any) -> str:\n    return f"{pointer(body, \'/code\')} {pointer(body, \'/message\') or \'\'}".strip()[:500]\n\n\ndef _zoho_duplicate(status: int, body: Any) -> bool:\n    return str(pointer(body, "/code")) in ("13011", "13017")  # bill / PO number already exists\n\n\n_ZOHO_Q = "?organization_id={organization_id}"\nZOHO = Preset(\n    key=v.PRESET_ZOHO, label="Zoho Books", auth=(v.AUTH_OAUTH2_REFRESH, v.AUTH_BEARER),\n    config_keys=("organization_id",), error_text=_zoho_error, duplicate=_zoho_duplicate,\n    headers={"Accept": "application/json"},\n    endpoints={\n        v.OBJECT_VENDOR_BILL: Endpoint("POST", "/books/v3/bills" + _ZOHO_Q, "line_items", _ZOHO_BILL, "/bill/bill_id",\n                                       (Echo("document_number", "/bill/bill_number", _at("/bill_number")),\n                                        Echo("subtotal", "/bill/sub_total",\n                                             _sum_product("/line_items", "/quantity", "/rate"), True)),\n                                       doc_number="/bill_number",\n                                       probe="/books/v3/bills" + _ZOHO_Q + "&bill_number={doc}",\n                                       probe_list="/bills", probe_id="/bill_id"),\n        v.OBJECT_PURCHASE_ORDER: Endpoint("POST", "/books/v3/purchaseorders" + _ZOHO_Q, "line_items", _ZOHO_PO,\n                                          "/purchaseorder/purchaseorder_id",\n                                          (Echo("document_number", "/purchaseorder/purchaseorder_number",\n                                                _at("/purchaseorder_number")),),\n                                          doc_number="/purchaseorder_number",\n                                          probe="/books/v3/purchaseorders" + _ZOHO_Q + "&purchaseorder_number={doc}",\n                                          probe_list="/purchaseorders", probe_id="/purchaseorder_id"),\n        v.OBJECT_JOURNAL_ENTRY: Endpoint("POST", "/books/v3/journals" + _ZOHO_Q, "line_items", _ZOHO_JE,\n                                         "/journal/journal_id",\n                                         (Echo("document_number", "/journal/reference_number",\n                                               _at("/reference_number")),),\n                                         doc_number="/reference_number",\n                                         probe="/books/v3/journals" + _ZOHO_Q + "&reference_number={doc}",\n                                         probe_list="/journals", probe_id="/journal_id"),\n        v.OBJECT_PAYMENT_REFERENCE: Endpoint("POST", "/books/v3/vendorpayments" + _ZOHO_Q, "bills", _ZOHO_PAY,\n                                             "/vendorpayment/payment_id",\n                                             (Echo("amount", "/vendorpayment/amount", _at("/amount"), True),)),\n    })\n\n# -- Dynamics 365 Business Central (API v2.0) ------------------------------------------\n_BC_ERR = lambda body: f"{pointer(body, \'/error/code\') or \'\'} {pointer(body, \'/error/message\') or \'\'}".strip()[:500]  # noqa: E731\n_BC_LINE = {"type": "object", "required": ["lineType", "quantity", "directUnitCost"],\n            "properties": {"lineType": {"enum": ["Comment", "Account", "Item", "Resource", "Fixed Asset", "Charge"]},\n                           "lineObjectNumber": _STR, "description": {"type": "string", "maxLength": 100},\n                           "quantity": _NUM, "directUnitCost": _NUM}}\n_BC_INVOICE = {"type": "object", "required": ["vendorNumber", "invoiceDate", "vendorInvoiceNumber",\n                                              "purchaseInvoiceLines"],\n               "properties": {"vendorNumber": {"type": "string", "minLength": 1, "maxLength": 20},\n                              "invoiceDate": _DATE, "dueDate": _DATE, "postingDate": _DATE,\n                              "vendorInvoiceNumber": {"type": "string", "minLength": 1, "maxLength": 35},\n                              "currencyCode": {"type": "string", "maxLength": 10},\n                              "purchaseInvoiceLines": {"type": "array", "minItems": 1, "items": _BC_LINE}}}\n_BC_ORDER = {"type": "object", "required": ["vendorNumber", "orderDate", "purchaseOrderLines"],\n             "properties": {"vendorNumber": {"type": "string", "minLength": 1, "maxLength": 20}, "orderDate": _DATE,\n                            "number": {"type": "string", "maxLength": 20},\n                            "purchaseOrderLines": {"type": "array", "minItems": 1, "items": _BC_LINE}}}\n_BC_BASE = "/companies({company_id})"\nBC = Preset(\n    key=v.PRESET_BC, label="Dynamics 365 Business Central", auth=(v.AUTH_OAUTH2_CLIENT, v.AUTH_BEARER),\n    config_keys=("company_id",), error_text=_BC_ERR, headers={"Accept": "application/json"},\n    endpoints={\n        v.OBJECT_VENDOR_BILL: Endpoint("POST", _BC_BASE + "/purchaseInvoices", "purchaseInvoiceLines", _BC_INVOICE,\n                                       "/id",\n                                       (Echo("document_number", "/vendorInvoiceNumber", _at("/vendorInvoiceNumber")),\n                                        Echo("subtotal", "/totalAmountExcludingTax",\n                                             _sum_product("/purchaseInvoiceLines", "/quantity", "/directUnitCost"),\n                                             True)),\n                                       doc_number="/vendorInvoiceNumber",\n                                       probe=_BC_BASE + "/purchaseInvoices?$filter=vendorInvoiceNumber%20eq%20%27{doc}%27",\n                                       probe_list="/value", probe_id="/id"),\n        v.OBJECT_PURCHASE_ORDER: Endpoint("POST", _BC_BASE + "/purchaseOrders", "purchaseOrderLines", _BC_ORDER, "/id",\n                                          (Echo("document_number", "/number", _at("/number")),),\n                                          doc_number="/number",\n                                          probe=_BC_BASE + "/purchaseOrders?$filter=number%20eq%20%27{doc}%27",\n                                          probe_list="/value", probe_id="/id"),\n    })\n\n# -- SAP S/4HANA (OData V2) ---------------------------------------------------------------\n_S4_ERR = lambda body: f"{pointer(body, \'/error/code\') or \'\'} {pointer(body, \'/error/message/value\') or \'\'}".strip()[:500]  # noqa: E731\n_S4_INVOICE = {"type": "object",\n               "required": ["CompanyCode", "DocumentDate", "PostingDate", "SupplierInvoiceIDByInvcgParty",\n                            "InvoicingParty", "DocumentCurrency", "InvoiceGrossAmount", "to_SupplierInvoiceItemGLAcct"],\n               "properties": {"CompanyCode": {"type": "string", "minLength": 1, "maxLength": 4},\n                              "DocumentDate": {"type": "string", "pattern": r"^/Date\\(\\d+\\)/$"},\n                              "PostingDate": {"type": "string", "pattern": r"^/Date\\(\\d+\\)/$"},\n                              "SupplierInvoiceIDByInvcgParty": {"type": "string", "minLength": 1, "maxLength": 16},\n                              "InvoicingParty": {"type": "string", "minLength": 1, "maxLength": 10},\n                              "DocumentCurrency": {"type": "string", "minLength": 3, "maxLength": 5},\n                              "InvoiceGrossAmount": {"type": "string", "pattern": r"^-?\\d+(\\.\\d+)?$"},\n                              "to_SupplierInvoiceItemGLAcct": {\n                                  "type": "object", "required": ["results"],\n                                  "properties": {"results": {"type": "array", "minItems": 1, "items": {\n                                      "type": "object",\n                                      "required": ["SupplierInvoiceItem", "CompanyCode", "GLAccount", "DocumentCurrency",\n                                                   "SupplierInvoiceItemAmount", "DebitCreditCode"],\n                                      "properties": {"GLAccount": {"type": "string", "minLength": 1, "maxLength": 10},\n                                                     "SupplierInvoiceItemAmount": {"type": "string",\n                                                                                   "pattern": r"^-?\\d+(\\.\\d+)?$"},\n                                                     "DebitCreditCode": {"enum": ["S", "H"]}}}}}}}}\n_S4_ORDER = {"type": "object", "required": ["PurchaseOrderType", "CompanyCode", "PurchasingOrganization",\n                                            "PurchasingGroup", "Supplier", "to_PurchaseOrderItem"],\n             "properties": {"PurchaseOrderType": {"type": "string", "maxLength": 4},\n                            "Supplier": {"type": "string", "minLength": 1, "maxLength": 10},\n                            "to_PurchaseOrderItem": {"type": "object", "required": ["results"],\n                                                     "properties": {"results": {"type": "array", "minItems": 1}}}}}\n_S4_RECEIPT = {"type": "object", "required": ["GoodsMovementCode", "DocumentDate", "PostingDate", "to_MaterialDocumentItem"],\n               "properties": {"GoodsMovementCode": {"const": "01"},\n                              "to_MaterialDocumentItem": {"type": "object", "required": ["results"],\n                                                          "properties": {"results": {"type": "array", "minItems": 1,\n                                                                                     "items": {\n                                  "type": "object",\n                                  "required": ["PurchaseOrder", "PurchaseOrderItem", "GoodsMovementType",\n                                               "QuantityInEntryUnit"],\n                                  "properties": {"GoodsMovementType": {"const": "101"}}}}}}}}\nS4 = Preset(\n    key=v.PRESET_S4, label="SAP S/4HANA (OData V2)", auth=(v.AUTH_BASIC, v.AUTH_OAUTH2_CLIENT, v.AUTH_BEARER),\n    config_keys=("sap_client",), csrf=True, error_text=_S4_ERR, headers={"Accept": "application/json"},\n    endpoints={\n        v.OBJECT_VENDOR_BILL: Endpoint("POST", "/API_SUPPLIERINVOICE_PROCESS_SRV/A_SupplierInvoice?sap-client={sap_client}",\n                                       "to_SupplierInvoiceItemGLAcct.results", _S4_INVOICE, "/d/SupplierInvoice",\n                                       (Echo("document_number", "/d/SupplierInvoiceIDByInvcgParty",\n                                             _at("/SupplierInvoiceIDByInvcgParty")),\n                                        Echo("total", "/d/InvoiceGrossAmount", _at("/InvoiceGrossAmount"), True)),\n                                       doc_number="/SupplierInvoiceIDByInvcgParty",\n                                       probe="/API_SUPPLIERINVOICE_PROCESS_SRV/A_SupplierInvoice?sap-client={sap_client}"\n                                             "&$format=json&$filter=SupplierInvoiceIDByInvcgParty%20eq%20%27{doc}%27",\n                                       probe_list="/d/results", probe_id="/SupplierInvoice"),\n        v.OBJECT_PURCHASE_ORDER: Endpoint("POST", "/API_PURCHASEORDER_PROCESS_SRV/A_PurchaseOrder?sap-client={sap_client}",\n                                          "to_PurchaseOrderItem.results", _S4_ORDER, "/d/PurchaseOrder"),\n        v.OBJECT_GOODS_RECEIPT: Endpoint("POST", "/API_MATERIAL_DOCUMENT_SRV/A_MaterialDocumentHeader?sap-client={sap_client}",\n                                         "to_MaterialDocumentItem.results", _S4_RECEIPT, "/d/MaterialDocument"),\n    })\n\n# -- Oracle NetSuite (REST Record API v1) -------------------------------------------------\n_NS_ERR = lambda body: "; ".join(str(d.get("detail", "")) for d in (pointer(body, "/o:errorDetails") or [])  # noqa: E731\n                                 if isinstance(d, dict))[:500] or str(pointer(body, "/title") or "")\n_NS_REF = {"type": "object", "required": ["id"], "properties": {"id": {"type": "string", "minLength": 1}}}\n_NS_BILL = {"type": "object", "required": ["entity", "tranDate", "expense"],\n            "properties": {"entity": _NS_REF, "tranDate": _DATE, "tranId": {"type": "string", "maxLength": 45},\n                           "dueDate": _DATE, "currency": _NS_REF, "memo": _STR,\n                           "expense": {"type": "object", "required": ["items"], "properties": {"items": {\n                               "type": "array", "minItems": 1, "items": {\n                                   "type": "object", "required": ["account", "amount"],\n                                   "properties": {"account": _NS_REF, "amount": _NUM, "memo": _STR}}}}}}}\n_NS_PO = {"type": "object", "required": ["entity", "tranDate", "item"],\n          "properties": {"entity": _NS_REF, "tranDate": _DATE, "tranId": _STR,\n                         "item": {"type": "object", "required": ["items"], "properties": {"items": {\n                             "type": "array", "minItems": 1, "items": {\n                                 "type": "object", "required": ["item", "quantity", "rate"],\n                                 "properties": {"item": _NS_REF, "quantity": _NUM, "rate": _NUM}}}}}}}\n_NS_JE = {"type": "object", "required": ["tranDate", "line"],\n          "properties": {"tranDate": _DATE, "tranId": _STR, "memo": _STR,\n                         "line": {"type": "object", "required": ["items"], "properties": {"items": {\n                             "type": "array", "minItems": 2, "items": {\n                                 "type": "object", "required": ["account"],\n                                 "properties": {"account": _NS_REF, "debit": _NUM, "credit": _NUM}}}}}}}\n_NS_PAY = {"type": "object", "required": ["entity", "tranDate", "account", "apply"],\n           "properties": {"entity": _NS_REF, "tranDate": _DATE, "account": _NS_REF,\n                          "apply": {"type": "object", "required": ["items"], "properties": {"items": {\n                              "type": "array", "minItems": 1, "items": {\n                                  "type": "object", "required": ["doc", "amount"],\n                                  "properties": {"doc": _NS_REF, "amount": _NUM, "apply": {"type": "boolean"}}}}}}}}\nNETSUITE = Preset(\n    key=v.PRESET_NETSUITE, label="Oracle NetSuite (REST)", auth=(v.AUTH_OAUTH2_CLIENT, v.AUTH_BEARER),\n    config_keys=(), idempotency_header="X-NetSuite-Idempotency-Key", error_text=_NS_ERR,\n    headers={"Accept": "application/json", "Prefer": "transient"},\n    endpoints={\n        v.OBJECT_VENDOR_BILL: Endpoint("POST", "/vendorBill", "expense.items", _NS_BILL, None,\n                                       (Echo("document_number", "/tranId", _at("/tranId")),\n                                        Echo("total", "/userTotal", _sum("/expense/items", "/amount"), True)),\n                                       doc_number="/tranId", follow_location=True,\n                                       probe="/vendorBill?q=tranId%20IS%20%22{doc}%22", probe_list="/items",\n                                       probe_id="/id"),\n        v.OBJECT_PURCHASE_ORDER: Endpoint("POST", "/purchaseOrder", "item.items", _NS_PO, None,\n                                          (Echo("document_number", "/tranId", _at("/tranId")),),\n                                          doc_number="/tranId", follow_location=True,\n                                          probe="/purchaseOrder?q=tranId%20IS%20%22{doc}%22", probe_list="/items",\n                                          probe_id="/id"),\n        v.OBJECT_JOURNAL_ENTRY: Endpoint("POST", "/journalEntry", "line.items", _NS_JE, None,\n                                         (Echo("document_number", "/tranId", _at("/tranId")),),\n                                         doc_number="/tranId", follow_location=True,\n                                         probe="/journalEntry?q=tranId%20IS%20%22{doc}%22", probe_list="/items",\n                                         probe_id="/id"),\n        v.OBJECT_PAYMENT_REFERENCE: Endpoint("POST", "/vendorPayment", "apply.items", _NS_PAY, None, (),\n                                             follow_location=False),\n    })\n\n\ndef _generic(key: str, label: str, odata: bool) -> Preset:\n    """Generic REST / OData V4: paths, id and echo pointers, probe and idempotency header come from the target\'s config\n    ("rest": {...}); every object kind is allowed; the body is whatever the mapping produces (no transcribed schema)."""\n    endpoints = {kind: Endpoint("POST", "{path}", None, {"type": "object", "minProperties": 1}, "/id")\n                 for kind in v.OBJECT_KINDS}\n    return Preset(key=key, label=label, auth=(v.AUTH_BEARER, v.AUTH_BASIC, v.AUTH_API_KEY, v.AUTH_OAUTH2_CLIENT,\n                                               v.AUTH_OAUTH2_REFRESH),\n                  config_keys=(), headers={"Accept": "application/json"}, endpoints=endpoints,\n                  error_text=lambda body: str(pointer(body, "/error/message") or pointer(body, "/message") or "")[:500])\n\n\nGENERIC_REST = _generic(v.PRESET_GENERIC_REST, "Generic REST", False)\nGENERIC_ODATA = _generic(v.PRESET_GENERIC_ODATA, "Generic OData V4", True)\nPRESETS: dict[str, Preset] = {p.key: p for p in (QBO, ZOHO, BC, S4, NETSUITE, GENERIC_REST, GENERIC_ODATA)}\n\n\ndef preset(key: str) -> Preset:\n    p = PRESETS.get(key)\n    if p is None:\n        raise ApiError(f"unknown preset {key!r}")\n    return p\n\n\ndef supported(key: str) -> tuple[str, ...]:\n    return tuple(PRESETS[key].endpoints) if key in PRESETS else ()\n\n\n# ---------------------------------------------------------------------------\n# requests and acknowledgements\n# ---------------------------------------------------------------------------\n\n_PLACEHOLDER = re.compile(r"\\{([a-z_]+)\\}")\n\n\n@dataclass(frozen=True)\nclass Request:\n    method: str\n    path: str\n    body: bytes\n    headers: dict[str, str]\n\n\ndef endpoint_for(key: str, object_kind: str, config: Mapping[str, Any]) -> Endpoint:\n    p = preset(key)\n    ep = p.endpoints.get(object_kind)\n    if ep is None:\n        raise ApiError(f"{p.label} does not take a {v.OBJECT_LABELS[object_kind].lower()} through this integration")\n    if key in (v.PRESET_GENERIC_REST, v.PRESET_GENERIC_ODATA):\n        rest = dict(config.get("rest") or {})\n        paths = rest.get("paths") or {}\n        if object_kind not in paths:\n            raise ApiError(f"rest.paths has no path for {object_kind}")\n        probe = rest.get("probe")\n        ep = Endpoint(str(rest.get("method", "POST")).upper(), str(paths[object_kind]), rest.get("lines_to"),\n                      ep.schema, rest.get("id_pointer", "/id"),\n                      tuple(Echo(name, ptr, _at(ptr), False) for name, ptr in (rest.get("echo") or {}).items()),\n                      doc_number=rest.get("doc_number_pointer"),\n                      probe=(probe or {}).get(object_kind) if isinstance(probe, dict) else None,\n                      probe_list=rest.get("probe_list_pointer", "/value" if key == v.PRESET_GENERIC_ODATA else "/items"),\n                      probe_id=rest.get("probe_id_pointer", "/id"))\n    return ep\n\n\ndef fill(path: str, config: Mapping[str, Any], preset_key: str, doc: Optional[str] = None) -> str:\n    section = dict(config.get({v.PRESET_QBO: "qbo", v.PRESET_ZOHO: "zoho", v.PRESET_BC: "bc", v.PRESET_S4: "s4"}\n                              .get(preset_key, "rest")) or {})\n\n    def sub(m: re.Match) -> str:\n        name = m.group(1)\n        if name == "doc":\n            return quote((doc or "").replace("\'", "\'\'").replace(\'"\', ""), safe="")\n        value = section.get(name)\n        if value in (None, ""):\n            raise ApiError(f"the target\'s configuration is missing {name}")\n        return quote(str(value), safe="-_.")\n\n    return _PLACEHOLDER.sub(sub, path)\n\n\ndef validate_body(key: str, object_kind: str, body: dict, config: Mapping[str, Any]) -> list[str]:\n    import jsonschema\n\n    ep = endpoint_for(key, object_kind, config)\n    validator = jsonschema.Draft202012Validator(ep.schema)\n    plain = json.loads(dumps(body))\n    return [f"{\'/\'.join(str(p) for p in e.absolute_path) or \'(body)\'}: {e.message}"\n            for e in sorted(validator.iter_errors(plain), key=lambda e: list(e.absolute_path))][:25]\n\n\ndef build(key: str, object_kind: str, record: Record, config: Mapping[str, Any]) -> tuple[dict, bytes]:\n    body = body_of(record)\n    problems = validate_body(key, object_kind, body, config)\n    if problems:\n        raise ApiError(f"the {preset(key).label} request body is invalid: " + "; ".join(problems[:6]))\n    return body, dumps(body).encode("utf-8")\n\n\n@dataclass\nclass Acknowledgement:\n    outcome: str                      # ACCEPTED, MISMATCH\n    external_id: Optional[str]\n    echoed: dict\n    message: str\n\n\ndef acknowledge(key: str, object_kind: str, body: dict, response: Any, *, location: Optional[str],\n                config: Mapping[str, Any], currency: Optional[str] = None) -> Acknowledgement:\n    """Does the target\'s answer acknowledge what was sent? Compares every echoed figure, amounts to within\n    ACK_AMOUNT_TOLERANCE_MINOR of the posting currency\'s minor unit (ARCH47-S1:ack-tolerance: 1 yen, 1 cent, 1 fils)."""\n    ep = endpoint_for(key, object_kind, config)\n    tolerance = Decimal(v.ACK_AMOUNT_TOLERANCE_MINOR).scaleb(-v.currency_exponent(currency or ""))\n    external = None\n    if ep.id_pointer:\n        external = pointer(response, ep.id_pointer)\n    if external is None and location:\n        external = location.rstrip("/").rsplit("/", 1)[-1].split("(")[-1].rstrip(")\'").lstrip("\'") or None\n    echoed: dict = {}\n    problems: list[str] = []\n    for echo in ep.echoes:\n        got = pointer(response, echo.response)\n        want = echo.expected(body)\n        echoed[echo.name] = {"sent": _jsonish(want), "target": _jsonish(got)}\n        if got is None:\n            continue  # the target did not echo it: nothing to contradict\n        if echo.numeric:\n            a, b = _num(got), _num(want)\n            if a is None or b is None or abs(a - b) > tolerance:\n                problems.append(f"{echo.name}: sent {want}, the target has {got}")\n        elif str(got).strip() != str(want if want is not None else "").strip():\n            problems.append(f"{echo.name}: sent {want!r}, the target has {got!r}")\n    if external in (None, ""):\n        return Acknowledgement(v.OUTCOME_MISMATCH, None, echoed, "the target answered success but named no record")\n    if problems:\n        return Acknowledgement(v.OUTCOME_MISMATCH, str(external), echoed, "; ".join(problems))\n    return Acknowledgement(v.OUTCOME_ACCEPTED, str(external), echoed, f"created as {external}")\n\n\ndef _jsonish(value: Any) -> Any:\n    if isinstance(value, Decimal):\n        return format(value, "f")\n    return value\n\n\ndef probe_request(key: str, object_kind: str, doc_number: Optional[str], config: Mapping[str, Any]) -> Optional[str]:\n    ep = endpoint_for(key, object_kind, config)\n    if not ep.probe or not doc_number:\n        return None\n    return fill(ep.probe, config, key, doc=doc_number)\n\n\ndef probe_result(key: str, object_kind: str, response: Any, config: Mapping[str, Any]) -> tuple[bool, Optional[str]]:\n    """(found, external id) from a probe response."""\n    ep = endpoint_for(key, object_kind, config)\n    items = pointer(response, ep.probe_list or "") if ep.probe_list else response\n    if isinstance(items, dict):\n        items = [items]\n    if not isinstance(items, list) or not items:\n        return False, None\n    ident = pointer(items[0], ep.probe_id or "/id")\n    return True, None if ident is None else str(ident)\n\n\ndef doc_number_of(key: str, object_kind: str, body: dict, config: Mapping[str, Any]) -> Optional[str]:\n    ep = endpoint_for(key, object_kind, config)\n    if not ep.doc_number:\n        return None\n    value = pointer(body, ep.doc_number)\n    return None if value in (None, "") else str(value)\n\n\ndef s4_date(value: date) -> str:\n    """OData V2 Edm.DateTime as S/4HANA takes it: /Date(<ms since the epoch, UTC midnight>)/."""\n    from datetime import timezone\n\n    ms = int(datetime(value.year, value.month, value.day, tzinfo=timezone.utc).timestamp() * 1000)\n    return f"/Date({ms})/"\n\n\n__all__ = ["Acknowledgement", "ApiError", "BC", "Echo", "Endpoint", "GENERIC_ODATA", "GENERIC_REST", "MEDIA_TYPE",\n           "NETSUITE", "PRESETS", "Preset", "QBO", "Request", "S4", "ZOHO", "acknowledge", "body_of", "build",\n           "doc_number_of", "dumps", "endpoint_for", "fill", "loads", "pointer", "preset", "probe_request",\n           "probe_result", "s4_date", "supported", "validate_body"]\n'),
    Op(path='backend/app/services/erp/formats/tabular.py', kind='new', final_sha='e93d42685643c1c106a871ca0ca738f8d352f14a31544942260e6f7e7f9829e7', encoding='utf-8', executable=False,
       variants=(('1c15081fdf2c19f067e62bf587d95052ea810c8145be0d4f8b16d7343058fdbc', (('            info.external_attr = 0o600 << 16\n            z.writestr(info, text.encode("utf-8"))\n', '            info.external_attr = 0o600 << 16\n            # ARCH47-S1:zip-platform. zipfile stamps the "made by" system from the running OS (0 on Windows,\n            # 3 elsewhere); pinning it makes the same posting the same bytes on every platform.\n            info.create_system = 3\n            z.writestr(info, text.encode("utf-8"))\n'),)),), content='"""ARCH47-S1:tabular — CSV (RFC 4180) and XLSX (ECMA-376) posting files. Pure; standard library only.\n\nOne row per line, the header fields repeated on every row (the shape every ERP\n"import vendor bills from a spreadsheet" screen expects); a posting without\nlines is one row. Columns are the mapping\'s fields in mapping order: header\nfields first, then line fields.\n\nCSV    RFC 4180: CRLF line ends, fields quoted only when they must be, a quote\n       doubled. UTF-8, no byte-order mark unless the target asks for one\n       (config csv.bom). Delimiter "," or ";" (config csv.delimiter). A text\n       value that begins with = + @ or a control character -- or with "-"\n       and is not a number -- is prefixed with an apostrophe so a spreadsheet\n       never evaluates it (config csv.neutralize_formulas, default on); typed\n       numbers are written as numbers.\nXLSX   One worksheet, inline strings (no shared-strings part), numbers as\n       numbers, dates as date serials with a yyyy-mm-dd format, the header row\n       bold and frozen. Written with zipfile with a fixed timestamp and member\n       order, so the same posting is the same bytes (its sha256 is stable).\n       The package validates against the ECMA-376 SpreadsheetML and OPC\n       schemas (verify_arch47 F2).\n"""\n\nfrom __future__ import annotations\n\nimport csv\nimport io\nimport re\nimport zipfile\nfrom datetime import date, datetime\nfrom decimal import Decimal\nfrom typing import Any, Mapping, Sequence\nfrom xml.sax.saxutils import escape\n\nfrom app.services.erp.mapping import Record, jsonable\n\n_XML_ILLEGAL = re.compile(r"[\\x00-\\x08\\x0b\\x0c\\x0e-\\x1f]")\n_NUMBER = re.compile(r"^-?\\d+(\\.\\d+)?$")\n_EPOCH = date(1899, 12, 30)\n_FIXED_TIME = (2026, 1, 1, 0, 0, 0)\n\n\ndef columns(record: Record) -> list[str]:\n    cols = [k for k, _ in record.header]\n    seen = set(cols)\n    for line in record.lines:\n        for k, _ in line:\n            if k not in seen:\n                seen.add(k)\n                cols.append(k)\n    return cols\n\n\ndef rows(record: Record) -> list[list[Any]]:\n    cols = columns(record)\n    head = dict(record.header)\n    out: list[list[Any]] = []\n    for line in record.lines or [[]]:\n        merged = {**head, **dict(line)}\n        out.append([merged.get(c) for c in cols])\n    return out\n\n\ndef _neutral(text: str) -> str:\n    if not text:\n        return text\n    if text[0] in ("=", "+", "@", "\\t", "\\r") or (text[0] == "-" and not _NUMBER.match(text)):\n        return "\'" + text\n    return text\n\n\ndef _cell_text(value: Any, neutralize: bool) -> str:\n    if value is None:\n        return ""\n    if isinstance(value, bool):\n        return "true" if value else "false"\n    if isinstance(value, (int, Decimal)):\n        return format(value, "f") if isinstance(value, Decimal) else str(value)\n    text = str(jsonable(value))\n    return _neutral(text) if neutralize and not isinstance(value, (date, datetime)) else text\n\n\ndef to_csv(record: Record, config: Mapping[str, Any] | None = None) -> bytes:\n    cfg = dict((config or {}).get("csv") or {})\n    delimiter = cfg.get("delimiter", ",")\n    if delimiter not in (",", ";"):\n        raise ValueError("csv.delimiter is \',\' or \';\'")\n    neutralize = bool(cfg.get("neutralize_formulas", True))\n    buf = io.StringIO(newline="")\n    writer = csv.writer(buf, delimiter=delimiter, quotechar=\'"\', quoting=csv.QUOTE_MINIMAL, lineterminator="\\r\\n",\n                        doublequote=True)\n    writer.writerow(columns(record))\n    for row in rows(record):\n        writer.writerow([_cell_text(v, neutralize) for v in row])\n    data = buf.getvalue().encode("utf-8")\n    return (b"\\xef\\xbb\\xbf" + data) if cfg.get("bom") else data\n\n\ndef validate_csv(data: bytes, *, delimiter: str = ",") -> list[str]:\n    """RFC 4180 conformance, by an independent reader that follows the ABNF:\n\n        file = record *(CRLF record) [CRLF];  record = field *(COMMA field)\n        field = escaped / non-escaped\n        escaped = DQUOTE *(TEXTDATA / COMMA / CR / LF / 2DQUOTE) DQUOTE\n        non-escaped = *TEXTDATA          (no DQUOTE, COMMA, CR or LF)\n\n    plus: every record has the header\'s field count, and the file ends with CRLF.\n    """\n    problems: list[str] = []\n    try:\n        text = data.decode("utf-8-sig")\n    except UnicodeDecodeError as exc:\n        return [f"not UTF-8: {exc}"]\n    records: list[list[str]] = []\n    field_chars: list[str] = []\n    record: list[str] = []\n    i, n = 0, len(text)\n    state = "start"  # start | plain | quoted | after_quote\n    while i < n:\n        ch = text[i]\n        if state == "quoted":\n            if ch == \'"\':\n                if i + 1 < n and text[i + 1] == \'"\':\n                    field_chars.append(\'"\')\n                    i += 2\n                    continue\n                state = "after_quote"\n            else:\n                field_chars.append(ch)\n            i += 1\n            continue\n        if ch == delimiter:\n            record.append("".join(field_chars))\n            field_chars, state = [], "start"\n        elif ch == "\\r":\n            if i + 1 >= n or text[i + 1] != "\\n":\n                problems.append(f"a bare CR at offset {i}")\n                break\n            record.append("".join(field_chars))\n            records.append(record)\n            record, field_chars, state = [], [], "start"\n            i += 2\n            continue\n        elif ch == "\\n":\n            problems.append(f"a bare LF at offset {i}")\n            break\n        elif ch == \'"\':\n            if state == "start":\n                state = "quoted"\n            else:\n                problems.append(f"a quote inside an unquoted field at offset {i}")\n                break\n        elif state == "after_quote":\n            problems.append(f"text after a closing quote at offset {i}")\n            break\n        else:\n            field_chars.append(ch)\n            state = "plain"\n        i += 1\n    if state == "quoted":\n        problems.append("an unterminated quoted field")\n    if record or field_chars:\n        problems.append("the last record does not end with CRLF")\n        record.append("".join(field_chars))\n        records.append(record)\n    if not records:\n        return problems + ["no header record"]\n    width = len(records[0])\n    for k, rec in enumerate(records[1:], start=2):\n        if len(rec) != width:\n            problems.append(f"record {k} has {len(rec)} fields, the header has {width}")\n    return problems\n\n\ndef read_csv(data: bytes, *, delimiter: str = ",") -> list[list[str]]:\n    return list(csv.reader(io.StringIO(data.decode("utf-8-sig"), newline=""), delimiter=delimiter))\n\n\n# ---------------------------------------------------------------------------\n# XLSX\n# ---------------------------------------------------------------------------\n\n\ndef column_letter(index: int) -> str:\n    letters = ""\n    index += 1\n    while index:\n        index, rem = divmod(index - 1, 26)\n        letters = chr(65 + rem) + letters\n    return letters\n\n\ndef _xml(text: str) -> str:\n    return escape(_XML_ILLEGAL.sub("", text), {\'"\': "&quot;"})\n\n\ndef _cell(ref: str, value: Any, style: int = 0) -> str:\n    if value is None:\n        return ""\n    s = f\' s="{style}"\' if style else ""\n    if isinstance(value, bool):\n        return f\'<c r="{ref}" t="b"{s}><v>{int(value)}</v></c>\'\n    if isinstance(value, (int, Decimal)):\n        num = format(value, "f") if isinstance(value, Decimal) else str(value)\n        return f\'<c r="{ref}" s="2"><v>{num}</v></c>\'\n    if isinstance(value, (date, datetime)):\n        d = value.date() if isinstance(value, datetime) else value\n        return f\'<c r="{ref}" s="3"><v>{(d - _EPOCH).days}</v></c>\'\n    # An inline string is never a formula (only an <f> element is): written exactly as mapped.\n    text = str(value)\n    space = \' xml:space="preserve"\' if text != text.strip() else ""\n    return f\'<c r="{ref}" t="inlineStr"{s}><is><t{space}>{_xml(text)}</t></is></c>\'\n\n\n_CONTENT_TYPES = (\n    \'<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\\n\'\n    \'<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">\'\n    \'<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>\'\n    \'<Default Extension="xml" ContentType="application/xml"/>\'\n    \'<Override PartName="/xl/workbook.xml" \'\n    \'ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>\'\n    \'<Override PartName="/xl/worksheets/sheet1.xml" \'\n    \'ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>\'\n    \'<Override PartName="/xl/styles.xml" \'\n    \'ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/>\'\n    \'</Types>\')\n_ROOT_RELS = (\n    \'<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\\n\'\n    \'<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">\'\n    \'<Relationship Id="rId1" \'\n    \'Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" \'\n    \'Target="xl/workbook.xml"/></Relationships>\')\n_WORKBOOK_RELS = (\n    \'<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\\n\'\n    \'<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">\'\n    \'<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" \'\n    \'Target="worksheets/sheet1.xml"/>\'\n    \'<Relationship Id="rId2" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" \'\n    \'Target="styles.xml"/></Relationships>\')\n_STYLES = (\n    \'<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\\n\'\n    \'<styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">\'\n    \'<numFmts count="1"><numFmt numFmtId="164" formatCode="yyyy-mm-dd"/></numFmts>\'\n    \'<fonts count="2"><font><sz val="11"/><name val="Calibri"/></font><font><b/><sz val="11"/><name val="Calibri"/>\'\n    \'</font></fonts>\'\n    \'<fills count="2"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill>\'\n    \'</fills>\'\n    \'<borders count="1"><border><left/><right/><top/><bottom/><diagonal/></border></borders>\'\n    \'<cellStyleXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0"/></cellStyleXfs>\'\n    \'<cellXfs count="4"><xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0"/>\'\n    \'<xf numFmtId="0" fontId="1" fillId="0" borderId="0" xfId="0" applyFont="1"/>\'\n    \'<xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0"/>\'\n    \'<xf numFmtId="164" fontId="0" fillId="0" borderId="0" xfId="0" applyNumberFormat="1"/></cellXfs>\'\n    \'<cellStyles count="1"><cellStyle name="Normal" xfId="0" builtinId="0"/></cellStyles>\'\n    \'</styleSheet>\')\n\n\ndef _workbook(sheet_name: str) -> str:\n    return (\'<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\\n\'\n            \'<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" \'\n            \'xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships">\'\n            f\'<sheets><sheet name="{_xml(sheet_name)}" sheetId="1" r:id="rId1"/></sheets></workbook>\')\n\n\ndef _sheet(header: Sequence[str], body: Sequence[Sequence[Any]]) -> str:\n    parts = [\'<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\\n\'\n             \'<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">\',\n             \'<sheetViews><sheetView workbookViewId="0"><pane ySplit="1" topLeftCell="A2" activePane="bottomLeft" \'\n             \'state="frozen"/></sheetView></sheetViews><sheetData>\']\n    parts.append(\'<row r="1">\' + "".join(_cell(f"{column_letter(c)}1", h, 1) for c, h in enumerate(header)) + "</row>")\n    for r, row in enumerate(body, start=2):\n        parts.append(f\'<row r="{r}">\' + "".join(_cell(f"{column_letter(c)}{r}", val) for c, val in enumerate(row))\n                     + "</row>")\n    parts.append("</sheetData></worksheet>")\n    return "".join(parts)\n\n\ndef to_xlsx(record: Record, config: Mapping[str, Any] | None = None) -> bytes:\n    sheet_name = str(((config or {}).get("xlsx") or {}).get("sheet", "Posting"))[:31] or "Posting"\n    sheet_name = re.sub(r"[\\[\\]:*?/\\\\]", " ", sheet_name)\n    members = (("[Content_Types].xml", _CONTENT_TYPES), ("_rels/.rels", _ROOT_RELS),\n               ("xl/workbook.xml", _workbook(sheet_name)), ("xl/_rels/workbook.xml.rels", _WORKBOOK_RELS),\n               ("xl/styles.xml", _STYLES), ("xl/worksheets/sheet1.xml", _sheet(columns(record), rows(record))))\n    buf = io.BytesIO()\n    with zipfile.ZipFile(buf, "w", zipfile.ZIP_DEFLATED) as z:\n        for name, text in members:\n            info = zipfile.ZipInfo(name, date_time=_FIXED_TIME)\n            info.compress_type = zipfile.ZIP_DEFLATED\n            info.external_attr = 0o600 << 16\n            # ARCH47-S1:zip-platform. zipfile stamps the "made by" system from the running OS (0 on Windows,\n            # 3 elsewhere); pinning it makes the same posting the same bytes on every platform.\n            info.create_system = 3\n            z.writestr(info, text.encode("utf-8"))\n    return buf.getvalue()\n\n\ndef read_xlsx_rows(data: bytes) -> list[list[str]]:\n    """An independent reader (for the gates): every row\'s cell texts / raw values."""\n    from app.services.erp.formats import xmlsafe  # ARCH47-S1:xmlsafe (ARCH-16 S1: lxml only in xmlsafe)\n\n    ns = {"m": "http://schemas.openxmlformats.org/spreadsheetml/2006/main"}\n    with zipfile.ZipFile(io.BytesIO(data)) as z:\n        root = xmlsafe.parse(z.read("xl/worksheets/sheet1.xml"))\n    out = []\n    for row in root.findall(".//m:sheetData/m:row", ns):\n        cells: list[str] = []\n        for c in row.findall("m:c", ns):\n            t = c.find("m:is/m:t", ns)\n            v = c.find("m:v", ns)\n            letters = "".join(ch for ch in (c.get("r") or "") if ch.isalpha())\n            index = 0\n            for ch in letters:\n                index = index * 26 + (ord(ch.upper()) - 64)\n            while letters and len(cells) < index - 1:\n                cells.append("")   # an empty cell is simply absent from the sheet\n            cells.append((t.text if t is not None else (v.text if v is not None else "")) or "")\n        out.append(cells)\n    return out\n\n\n__all__ = ["column_letter", "columns", "read_xlsx_rows", "rows", "to_csv", "to_xlsx", "validate_csv"]\n'),
    Op(path='backend/app/services/erp/formats/tally.py', kind='new', final_sha='e0f6a18a61d7aa1f052b85b48fc50dc0ed004d9041dcf61c0e1147dc4ca61340', encoding='utf-8', executable=False,
       variants=(), content='"""ARCH47-S1:tally — Tally Prime XML voucher import files, and Tally\'s import response.\n\n    ENVELOPE / HEADER / TALLYREQUEST "Import Data"\n             / BODY / IMPORTDATA / REQUESTDESC (REPORTNAME "Vouchers", SVCURRENTCOMPANY)\n                                 / REQUESTDATA / TALLYMESSAGE / VOUCHER\n\nOne voucher per posting:\n\n  VENDOR_BILL        "Purchase": the party ledger credited with the total, each\n                     line\'s ledger debited, the tax ledger debited with the tax\n  JOURNAL_ENTRY      "Journal": each line debited or credited on its ledger\n  PAYMENT_REFERENCE  "Payment": the party debited, the bank ledger credited\n  PURCHASE_ORDER     "Purchase Order": inventory lines (stock item, quantity,\n                     rate) with their accounting allocation, the party credited\n  GOODS_RECEIPT      "Receipt Note": inventory lines received against the order\n\nTally\'s sign convention: a DEBIT is written ISDEEMEDPOSITIVE "Yes" with a\nNEGATIVE amount, a credit "No" with a positive one, and a voucher\'s amounts sum\nto zero. `render` refuses a voucher that does not balance; `validate` checks the\nfile against schemas/tally/tally-voucher-import.xsd (FlowPilot\'s schema of the\ndocumented format -- Tally publishes none) and re-checks both rules.\n\nThe voucher\'s REMOTEID is "FP-" + the posting\'s idempotency key, so the voucher\nin Tally names the posting it came from (FlowPilot\'s exactly-once guarantee\ndoes not depend on it: a file is never re-delivered without a probe).\n"""\n\nfrom __future__ import annotations\n\nfrom datetime import date, datetime\nfrom decimal import Decimal\nfrom typing import Any, Mapping, Optional\n\nfrom app.services.erp import vocabulary as v\nfrom app.services.erp.formats import xsd\nfrom app.services.erp.mapping import Contract, Record\n\nMEDIA_TYPE = "application/xml"\nVOUCHER_TYPES = {v.OBJECT_VENDOR_BILL: "Purchase", v.OBJECT_JOURNAL_ENTRY: "Journal",\n                 v.OBJECT_PAYMENT_REFERENCE: "Payment", v.OBJECT_PURCHASE_ORDER: "Purchase Order",\n                 v.OBJECT_GOODS_RECEIPT: "Receipt Note"}\nSUPPORTED = tuple(VOUCHER_TYPES)\n_INVENTORY = (v.OBJECT_PURCHASE_ORDER, v.OBJECT_GOODS_RECEIPT)\n\nCONTRACTS = {\n    v.OBJECT_VENDOR_BILL: Contract(\n        header={"date": True, "voucher_number": False, "reference": False, "reference_date": False,\n                "party_ledger": True, "party_amount": True, "tax_ledger": False, "tax_amount": False,\n                "narration": False},\n        lines={"ledger": True, "amount": True}, open=False, needs_lines=True),\n    v.OBJECT_JOURNAL_ENTRY: Contract(\n        header={"date": True, "voucher_number": False, "narration": False},\n        lines={"ledger": True, "debit": False, "credit": False}, open=False, needs_lines=True),\n    v.OBJECT_PAYMENT_REFERENCE: Contract(\n        header={"date": True, "voucher_number": False, "reference": False, "party_ledger": True, "bank_ledger": True,\n                "amount": True, "narration": False},\n        lines={}, open=False),\n    v.OBJECT_PURCHASE_ORDER: Contract(\n        header={"date": True, "voucher_number": False, "reference": False, "party_ledger": True,\n                "purchase_ledger": True, "narration": False},\n        lines={"stock_item": True, "quantity": True, "unit": False, "rate": True, "amount": True},\n        open=False, needs_lines=True),\n    v.OBJECT_GOODS_RECEIPT: Contract(\n        header={"date": True, "voucher_number": False, "reference": False, "party_ledger": True,\n                "purchase_ledger": True, "narration": False},\n        lines={"stock_item": True, "quantity": True, "unit": False, "rate": False, "amount": False},\n        open=False, needs_lines=True),\n}\n\n\nclass TallyError(ValueError):\n    pass\n\n\ndef _d(value: Any) -> str:\n    if isinstance(value, datetime):\n        value = value.date()\n    if isinstance(value, date):\n        return value.strftime("%Y%m%d")\n    text = str(value).replace("-", "")\n    if len(text) != 8 or not text.isdigit():\n        raise TallyError(f"{value!r} is not a date")\n    return text\n\n\ndef _amt(value: Decimal) -> str:\n    """At least two decimals, and every decimal the amount has (ARCH47-S1:tally-exact: a KWD 0.125 stays 0.125;\n    rounding each entry to cents would unbalance the voucher)."""\n    d = Decimal(value)\n    return format(d.quantize(Decimal("0.01")) if d.as_tuple().exponent > -2 else d, "f")\n\n\ndef _dec(value: Any, name: str) -> Decimal:\n    if value is None:\n        raise TallyError(f"{name} is missing")\n    try:\n        return Decimal(str(value))\n    except Exception as exc:  # noqa: BLE001\n        raise TallyError(f"{name}: {value!r} is not a number") from exc\n\n\ndef render(record: Record, object_kind: str, *, remote_id: str, config: Mapping[str, Any] | None = None) -> bytes:\n    from app.services.erp.formats import xmlsafe  # ARCH47-S1:xmlsafe (ARCH-16 S1: lxml only in xmlsafe)\n\n    if object_kind not in VOUCHER_TYPES:\n        raise TallyError(f"no Tally voucher for {object_kind}")\n    company = str(((config or {}).get("tally") or {}).get("company") or "").strip()\n    if not company:\n        raise TallyError("the target needs tally.company (the Tally company to import into)")\n    h = record.header_dict()\n    lines = record.line_dicts()\n    vtype = VOUCHER_TYPES[object_kind]\n    entries: list[tuple[str, Decimal]] = []   # (ledger, signed amount: debit negative)\n    inventory: list[dict] = []\n    if object_kind == v.OBJECT_VENDOR_BILL:\n        entries.append((str(h["party_ledger"]), _dec(h["party_amount"], "party_amount")))\n        for i, ln in enumerate(lines, start=1):\n            entries.append((str(ln["ledger"]), -_dec(ln["amount"], f"line {i} amount")))\n        if h.get("tax_amount") not in (None, "") and _dec(h["tax_amount"], "tax_amount") != 0:\n            if not h.get("tax_ledger"):\n                raise TallyError("a tax amount needs tax_ledger")\n            entries.append((str(h["tax_ledger"]), -_dec(h["tax_amount"], "tax_amount")))\n    elif object_kind == v.OBJECT_JOURNAL_ENTRY:\n        for i, ln in enumerate(lines, start=1):\n            debit = Decimal(str(ln["debit"])) if ln.get("debit") not in (None, "") else Decimal(0)\n            credit = Decimal(str(ln["credit"])) if ln.get("credit") not in (None, "") else Decimal(0)\n            if (debit != 0) == (credit != 0):\n                raise TallyError(f"journal line {i}: exactly one of debit and credit")\n            entries.append((str(ln["ledger"]), -debit if debit else credit))\n    elif object_kind == v.OBJECT_PAYMENT_REFERENCE:\n        amount = _dec(h["amount"], "amount")\n        entries += [(str(h["party_ledger"]), -amount), (str(h["bank_ledger"]), amount)]\n    else:\n        total = Decimal(0)\n        for i, ln in enumerate(lines, start=1):\n            quantity = _dec(ln["quantity"], f"line {i} quantity")\n            amount = _dec(ln["amount"], f"line {i} amount") if ln.get("amount") not in (None, "") else Decimal(0)\n            rate = _dec(ln["rate"], f"line {i} rate") if ln.get("rate") not in (None, "") else None\n            inventory.append({"item": str(ln["stock_item"]), "quantity": quantity,\n                              "unit": str(ln.get("unit") or "Nos").replace(" ", "")[:20], "rate": rate,\n                              "amount": amount})\n            total += amount\n        entries.append((str(h["party_ledger"]), total))\n    signed = sum((a for _, a in entries), Decimal(0)) - sum((i["amount"] for i in inventory), Decimal(0))\n    if signed.quantize(Decimal("0.01")) != 0:\n        raise TallyError(f"the voucher does not balance: its entries sum to {signed} (a Tally voucher sums to zero)")\n\n    E = xmlsafe\n    env = E.Element("ENVELOPE")\n    E.SubElement(E.SubElement(env, "HEADER"), "TALLYREQUEST").text = "Import Data"\n    imp = E.SubElement(E.SubElement(env, "BODY"), "IMPORTDATA")\n    desc = E.SubElement(imp, "REQUESTDESC")\n    E.SubElement(desc, "REPORTNAME").text = "Vouchers"\n    E.SubElement(E.SubElement(desc, "STATICVARIABLES"), "SVCURRENTCOMPANY").text = company\n    msg = E.SubElement(E.SubElement(imp, "REQUESTDATA"), "TALLYMESSAGE", nsmap={"UDF": "TallyUDF"})\n    view = "Invoice Voucher View" if object_kind in _INVENTORY else "Accounting Voucher View"\n    vch = E.SubElement(msg, "VOUCHER", REMOTEID=remote_id, VCHTYPE=vtype, ACTION="Create", OBJVIEW=view)\n    E.SubElement(vch, "DATE").text = _d(h["date"])\n    E.SubElement(vch, "VOUCHERTYPENAME").text = vtype\n    for tag, key in (("VOUCHERNUMBER", "voucher_number"), ("REFERENCE", "reference")):\n        if h.get(key):\n            E.SubElement(vch, tag).text = str(h[key])[:200]\n    if h.get("reference_date"):\n        E.SubElement(vch, "REFERENCEDATE").text = _d(h["reference_date"])\n    if h.get("party_ledger"):\n        E.SubElement(vch, "PARTYLEDGERNAME").text = str(h["party_ledger"])\n    if h.get("narration"):\n        E.SubElement(vch, "NARRATION").text = str(h["narration"])[:2000]\n    E.SubElement(vch, "PERSISTEDVIEW").text = view\n    if object_kind in _INVENTORY:\n        E.SubElement(vch, "ISINVOICE").text = "No"\n        for item in inventory:\n            inv = E.SubElement(vch, "ALLINVENTORYENTRIES.LIST")\n            E.SubElement(inv, "STOCKITEMNAME").text = item["item"]\n            E.SubElement(inv, "ISDEEMEDPOSITIVE").text = "Yes"\n            if item["rate"] is not None:\n                E.SubElement(inv, "RATE").text = f"{format(item[\'rate\'].normalize(), \'f\')}/{item[\'unit\']}"\n            E.SubElement(inv, "AMOUNT").text = _amt(-item["amount"])\n            qty = f"{format(item[\'quantity\'].normalize(), \'f\')} {item[\'unit\']}"\n            E.SubElement(inv, "ACTUALQTY").text = qty\n            E.SubElement(inv, "BILLEDQTY").text = qty\n            alloc = E.SubElement(inv, "ACCOUNTINGALLOCATIONS.LIST")\n            E.SubElement(alloc, "LEDGERNAME").text = str(h["purchase_ledger"])\n            E.SubElement(alloc, "ISDEEMEDPOSITIVE").text = "Yes"\n            E.SubElement(alloc, "AMOUNT").text = _amt(-item["amount"])\n    for ledger, amount in entries:\n        le = E.SubElement(vch, "ALLLEDGERENTRIES.LIST")\n        E.SubElement(le, "LEDGERNAME").text = ledger\n        E.SubElement(le, "ISDEEMEDPOSITIVE").text = "Yes" if amount < 0 else "No"\n        if ledger == h.get("party_ledger"):\n            E.SubElement(le, "ISPARTYLEDGER").text = "Yes"\n        E.SubElement(le, "AMOUNT").text = _amt(amount)\n    data = E.tostring(env, xml_declaration=True, encoding="UTF-8", pretty_print=True)\n    problems = validate(data)\n    if problems:\n        raise TallyError("the Tally voucher is invalid: " + "; ".join(problems[:5]))\n    return data\n\n\ndef validate(data: bytes) -> list[str]:\n    """The FlowPilot Tally XSD, then Tally\'s rules: amounts sum to zero, ISDEEMEDPOSITIVE agrees with the sign."""\n    from app.services.erp.formats import xmlsafe\n\n    problems = xsd.validate(data, xsd.TALLY)\n    if problems:\n        return problems\n    root = xmlsafe.parse(data)\n    for vch in root.iter("VOUCHER"):\n        total = Decimal(0)\n        for le in vch.findall("ALLLEDGERENTRIES.LIST"):\n            amount = Decimal(le.findtext("AMOUNT"))\n            positive = le.findtext("ISDEEMEDPOSITIVE")\n            if amount != 0 and (positive == "Yes") != (amount < 0):\n                problems.append(f"{le.findtext(\'LEDGERNAME\')}: ISDEEMEDPOSITIVE {positive} with amount {amount}")\n            total += amount\n        for inv in vch.findall("ALLINVENTORYENTRIES.LIST"):\n            amount = Decimal(inv.findtext("AMOUNT"))\n            total += amount\n            alloc = inv.find("ACCOUNTINGALLOCATIONS.LIST")\n            if alloc is not None and Decimal(alloc.findtext("AMOUNT")) != amount:\n                problems.append(f"{inv.findtext(\'STOCKITEMNAME\')}: allocation differs from the item amount")\n        if total != 0:\n            problems.append(f"voucher {vch.get(\'REMOTEID\')}: entries sum to {total}, not zero")\n    return problems\n\n\ndef parse_response(data: bytes) -> dict:\n    """Tally\'s import response (<RESPONSE><CREATED>..<ERRORS>..<LINEERROR>..)."""\n    from app.services.erp.formats import xmlsafe\n\n    try:\n        root = xmlsafe.parse(data)  # untrusted: a DOCTYPE / ENTITY is refused, no entity is resolved\n    except xmlsafe.XMLRefused as exc:\n        raise TallyError(f"not a Tally response: {exc}") from exc\n    node = root if root.tag == "RESPONSE" else root.find(".//RESPONSE")\n    if node is None:\n        raise TallyError("not a Tally response (no RESPONSE)")\n\n    def count(tag: str) -> int:\n        text = (node.findtext(tag) or "0").strip()\n        return int(text) if text.lstrip("-").isdigit() else 0\n\n    return {"created": count("CREATED"), "altered": count("ALTERED"), "ignored": count("IGNORED"),\n            "errors": count("ERRORS"), "exceptions": count("EXCEPTIONS"), "cancelled": count("CANCELLED"),\n            "last_voucher_id": (node.findtext("LASTVCHID") or "").strip() or None,\n            "line_errors": [e.text.strip() for e in root.iter("LINEERROR") if e.text][:10]}\n\n\ndef correlate(response: Mapping[str, Any]) -> tuple[str, str, Optional[str]]:\n    """(outcome, message, external id) for one voucher\'s import response."""\n    made = int(response.get("created", 0)) + int(response.get("altered", 0))\n    if response.get("errors") or response.get("exceptions"):\n        return v.OUTCOME_REJECTED, "Tally refused the voucher: " + "; ".join(response.get("line_errors") or\n                                                                              ["(no message)"]), None\n    if made == 1:\n        return v.OUTCOME_ACCEPTED, "Tally created the voucher", response.get("last_voucher_id")\n    if made == 0 and response.get("ignored"):\n        return v.OUTCOME_MISMATCH, "Tally ignored the voucher (an existing voucher with the same REMOTEID?)", None\n    return v.OUTCOME_MISMATCH, f"Tally reported {made} vouchers for one posting", response.get("last_voucher_id")\n\n\n__all__ = ["CONTRACTS", "MEDIA_TYPE", "SUPPORTED", "TallyError", "VOUCHER_TYPES", "correlate", "parse_response",\n           "render", "validate"]\n'),
    Op(path='backend/app/services/erp/formats/ubl.py', kind='new', final_sha='beb4b2f3e2c380fb91e6f43411563514987da8f14fbf6b08b25f70a88bce2eb9', encoding='utf-8', executable=False,
       variants=(), content='"""ARCH47-S1:ubl — UBL 2.1 Invoice (vendor bill), Order (purchase order) and ReceiptAdvice (goods receipt).\n\nBuilt with lxml in the element order the OASIS schemas prescribe and validated\nagainst the vendored UBL 2.1 XSDs (schemas/ubl21) BEFORE a posting is accepted:\na document the schema refuses is never sent. Amounts carry currencyID and are\nwritten exactly (the canonical object\'s quantized decimals); dates are\nYYYY-MM-DD; quantities carry a UN/ECE Recommendation 20 unitCode.\n"""\n\nfrom __future__ import annotations\n\nfrom datetime import date\nfrom decimal import Decimal\nfrom typing import Any, Mapping, Optional\n\nfrom app.services.erp import vocabulary as v\nfrom app.services.erp.formats import xsd\nfrom app.services.erp.mapping import Contract, Record\n\nNS_CBC = "urn:oasis:names:specification:ubl:schema:xsd:CommonBasicComponents-2"\nNS_CAC = "urn:oasis:names:specification:ubl:schema:xsd:CommonAggregateComponents-2"\nROOTS = {v.OBJECT_VENDOR_BILL: ("Invoice", "urn:oasis:names:specification:ubl:schema:xsd:Invoice-2"),\n         v.OBJECT_PURCHASE_ORDER: ("Order", "urn:oasis:names:specification:ubl:schema:xsd:Order-2"),\n         v.OBJECT_GOODS_RECEIPT: ("ReceiptAdvice", "urn:oasis:names:specification:ubl:schema:xsd:ReceiptAdvice-2")}\nSUPPORTED = tuple(ROOTS)\nMEDIA_TYPE = "application/xml"\n\n_INVOICE_HEADER = {"id": True, "issue_date": True, "due_date": False, "invoice_type_code": False, "note": False,\n                   "currency": True, "buyer_reference": False, "order_reference": False, "supplier_name": True,\n                   "supplier_id": False, "supplier_tax_id": False, "customer_name": True, "customer_id": False,\n                   "customer_tax_id": False, "payment_terms_note": False, "tax_amount": True,\n                   "line_extension_amount": True, "tax_exclusive_amount": True, "tax_inclusive_amount": True,\n                   "payable_amount": True}\n_INVOICE_LINE = {"id": True, "quantity": True, "unit_code": False, "line_amount": True, "description": False,\n                 "name": True, "seller_item_id": False, "price": True}\n_ORDER_HEADER = {"id": True, "issue_date": True, "note": False, "currency": True, "customer_reference": False,\n                 "buyer_name": True, "buyer_id": False, "seller_name": True, "seller_id": False, "tax_amount": False,\n                 "line_extension_amount": False, "payable_amount": True}\n_ORDER_LINE = {"id": True, "quantity": True, "unit_code": False, "line_amount": True, "price": False, "name": True,\n               "description": False, "seller_item_id": False}\n_RECEIPT_HEADER = {"id": True, "issue_date": True, "note": False, "order_reference": False, "customer_name": True,\n                   "customer_id": False, "supplier_name": True, "supplier_id": False}\n_RECEIPT_LINE = {"id": True, "quantity": True, "unit_code": False, "name": True, "description": False,\n                 "seller_item_id": False, "order_line_id": False}\n\nCONTRACTS = {\n    v.OBJECT_VENDOR_BILL: Contract(header=_INVOICE_HEADER, lines=_INVOICE_LINE, open=False, needs_lines=True),\n    v.OBJECT_PURCHASE_ORDER: Contract(header=_ORDER_HEADER, lines=_ORDER_LINE, open=False, needs_lines=True),\n    v.OBJECT_GOODS_RECEIPT: Contract(header=_RECEIPT_HEADER, lines=_RECEIPT_LINE, open=False, needs_lines=True),\n}\n\n\nclass UblError(ValueError):\n    pass\n\n\ndef _text(value: Any) -> str:\n    if isinstance(value, Decimal):\n        return format(value, "f")\n    if isinstance(value, date):\n        return value.isoformat()\n    return str(value)\n\n\nclass _B:\n    def __init__(self, root_name: str, root_ns: str) -> None:\n        from app.services.erp.formats import xmlsafe  # ARCH47-S1:xmlsafe (ARCH-16 S1: lxml only in xmlsafe)\n\n        self.E = xmlsafe\n        self.root = xmlsafe.Element(f"{{{root_ns}}}{root_name}", nsmap={None: root_ns, "cac": NS_CAC, "cbc": NS_CBC})\n\n    def cbc(self, parent: Any, name: str, value: Any, **attrs: str) -> None:\n        if value is None or (isinstance(value, str) and not value.strip()):\n            return\n        el = self.E.SubElement(parent, f"{{{NS_CBC}}}{name}", {k: v_ for k, v_ in attrs.items() if v_})\n        el.text = _text(value)\n\n    def cac(self, parent: Any, name: str) -> Any:\n        return self.E.SubElement(parent, f"{{{NS_CAC}}}{name}")\n\n    def amount(self, parent: Any, name: str, value: Any, currency: str) -> None:\n        if value is None:\n            return\n        self.cbc(parent, name, Decimal(str(value)), currencyID=currency)\n\n    def party(self, parent: Any, wrapper: str, name: Optional[str], ident: Optional[str] = None,\n              tax_id: Optional[str] = None) -> None:\n        holder = self.cac(parent, wrapper)\n        party = self.cac(holder, "Party")\n        if ident:\n            self.cbc(self.cac(party, "PartyIdentification"), "ID", ident)\n        self.cbc(self.cac(party, "PartyName"), "Name", name or "")\n        if tax_id:\n            scheme = self.cac(party, "PartyTaxScheme")\n            self.cbc(scheme, "CompanyID", tax_id)\n            self.cbc(self.cac(scheme, "TaxScheme"), "ID", "VAT")\n\n    def item(self, parent: Any, line: Mapping[str, Any]) -> None:\n        item = self.cac(parent, "Item")\n        self.cbc(item, "Description", line.get("description"))\n        self.cbc(item, "Name", line.get("name"))\n        if line.get("seller_item_id"):\n            self.cbc(self.cac(item, "SellersItemIdentification"), "ID", line["seller_item_id"])\n\n    def bytes(self) -> bytes:\n        return self.E.tostring(self.root, xml_declaration=True, encoding="UTF-8", pretty_print=True)\n\n\ndef render(record: Record, object_kind: str, config: Mapping[str, Any] | None = None) -> bytes:\n    if object_kind not in ROOTS:\n        raise UblError(f"UBL 2.1 carries vendor bills, purchase orders and goods receipts, not {object_kind}")\n    h = record.header_dict()\n    lines = record.line_dicts()\n    root_name, root_ns = ROOTS[object_kind]\n    b = _B(root_name, root_ns)\n    r = b.root\n    cur = str(h.get("currency") or "").upper()\n    b.cbc(r, "UBLVersionID", "2.1")\n    customization = (config or {}).get("ubl", {}).get("customization_id") if config else None\n    b.cbc(r, "CustomizationID", customization)\n    b.cbc(r, "ID", h.get("id"))\n    b.cbc(r, "IssueDate", h.get("issue_date"))\n    if object_kind == v.OBJECT_VENDOR_BILL:\n        b.cbc(r, "DueDate", h.get("due_date"))\n        b.cbc(r, "InvoiceTypeCode", h.get("invoice_type_code") or "380")\n        b.cbc(r, "Note", h.get("note"))\n        b.cbc(r, "DocumentCurrencyCode", cur)\n        b.cbc(r, "LineCountNumeric", Decimal(len(lines)))\n        b.cbc(r, "BuyerReference", h.get("buyer_reference"))\n        if h.get("order_reference"):\n            b.cbc(b.cac(r, "OrderReference"), "ID", h["order_reference"])\n        b.party(r, "AccountingSupplierParty", h.get("supplier_name"), h.get("supplier_id"), h.get("supplier_tax_id"))\n        b.party(r, "AccountingCustomerParty", h.get("customer_name"), h.get("customer_id"), h.get("customer_tax_id"))\n        if h.get("payment_terms_note"):\n            b.cbc(b.cac(r, "PaymentTerms"), "Note", h["payment_terms_note"])\n        b.amount(b.cac(r, "TaxTotal"), "TaxAmount", h.get("tax_amount"), cur)\n        total = b.cac(r, "LegalMonetaryTotal")\n        for name, key in (("LineExtensionAmount", "line_extension_amount"), ("TaxExclusiveAmount", "tax_exclusive_amount"),\n                          ("TaxInclusiveAmount", "tax_inclusive_amount"), ("PayableAmount", "payable_amount")):\n            b.amount(total, name, h.get(key), cur)\n        for ln in lines:\n            el = b.cac(r, "InvoiceLine")\n            b.cbc(el, "ID", ln.get("id"))\n            b.cbc(el, "InvoicedQuantity", ln.get("quantity"), unitCode=str(ln.get("unit_code") or "C62"))\n            b.amount(el, "LineExtensionAmount", ln.get("line_amount"), cur)\n            b.item(el, ln)\n            if ln.get("price") is not None:\n                b.amount(b.cac(el, "Price"), "PriceAmount", ln["price"], cur)\n    elif object_kind == v.OBJECT_PURCHASE_ORDER:\n        b.cbc(r, "Note", h.get("note"))\n        b.cbc(r, "DocumentCurrencyCode", cur)\n        b.cbc(r, "CustomerReference", h.get("customer_reference"))\n        b.cbc(r, "LineCountNumeric", Decimal(len(lines)))\n        b.party(r, "BuyerCustomerParty", h.get("buyer_name"), h.get("buyer_id"))\n        b.party(r, "SellerSupplierParty", h.get("seller_name"), h.get("seller_id"))\n        if h.get("tax_amount") is not None:\n            b.amount(b.cac(r, "TaxTotal"), "TaxAmount", h.get("tax_amount"), cur)\n        total = b.cac(r, "AnticipatedMonetaryTotal")\n        b.amount(total, "LineExtensionAmount", h.get("line_extension_amount"), cur)\n        b.amount(total, "PayableAmount", h.get("payable_amount"), cur)\n        for ln in lines:\n            item = b.cac(b.cac(r, "OrderLine"), "LineItem")\n            b.cbc(item, "ID", ln.get("id"))\n            b.cbc(item, "Quantity", ln.get("quantity"), unitCode=str(ln.get("unit_code") or "C62"))\n            b.amount(item, "LineExtensionAmount", ln.get("line_amount"), cur)\n            if ln.get("price") is not None:\n                b.amount(b.cac(item, "Price"), "PriceAmount", ln["price"], cur)\n            b.item(item, ln)\n    else:\n        b.cbc(r, "Note", h.get("note"))\n        b.cbc(r, "LineCountNumeric", Decimal(len(lines)))\n        if h.get("order_reference"):\n            b.cbc(b.cac(r, "OrderReference"), "ID", h["order_reference"])\n        b.party(r, "DeliveryCustomerParty", h.get("customer_name"), h.get("customer_id"))\n        b.party(r, "DespatchSupplierParty", h.get("supplier_name"), h.get("supplier_id"))\n        for ln in lines:\n            el = b.cac(r, "ReceiptLine")\n            b.cbc(el, "ID", ln.get("id"))\n            b.cbc(el, "ReceivedQuantity", ln.get("quantity"), unitCode=str(ln.get("unit_code") or "C62"))\n            if ln.get("order_line_id"):\n                b.cbc(b.cac(el, "OrderLineReference"), "LineID", ln["order_line_id"])\n            b.item(el, ln)\n    data = b.bytes()\n    problems = validate(data, object_kind)\n    if problems:\n        raise UblError("the UBL 2.1 schema refuses this document: " + "; ".join(problems[:5]))\n    return data\n\n\ndef validate(data: bytes, object_kind: str) -> list[str]:\n    root_name, _ = ROOTS[object_kind]\n    return xsd.validate(data, xsd.UBL_SCHEMAS[root_name])\n\n\ndef root_name(object_kind: str) -> str:\n    return ROOTS[object_kind][0]\n\n\n__all__ = ["CONTRACTS", "MEDIA_TYPE", "SUPPORTED", "UblError", "render", "root_name", "validate"]\n'),
    Op(path='backend/app/services/erp/formats/x12.py', kind='new', final_sha='9900fedf9e1dbf30952010fa0648f48fd4e73d0e6b642224e19e9b3cf802db0f', encoding='utf-8', executable=False,
       variants=(), content='"""ARCH47-S1:x12 — ASC X12 004010: 810 (invoice), 850 (purchase order), 856 (ship notice) and the 997.\n\nThe X12 standards are licensed by ASC X12 and no schema is freely published.\nSPEC below encodes, element by element, the 004010 segments FlowPilot writes --\nreference, data type (AN ID N0 N2 R DT TM), minimum and maximum length,\nmandatory or optional, code values -- and GRAMMAR the order of the segments in\neach transaction set, transcribed from public 004010 implementation guides.\n`validate()` re-parses a file with an independent reader and checks all of it\nplus the envelope arithmetic: ISA exactly 106 characters with its fixed-width\nelements, GS06 = GE02, ST02 = SE02, SE01 = the segments from ST to SE, GE01 = the\ntransaction sets, IEA01 = the groups, IEA02 = ISA13, CTT01 = the line items (810,\n850) or HL segments (856).\n\nControl numbers come from the target\'s own sequence (erp_targets.control_sequence,\nallocated under a row lock when a posting is planned), so a retry re-sends the\nSAME interchange -- which is what lets a partner\'s 997 name the posting it\nacknowledges, and lets a partner discard a duplicate.\n"""\n\nfrom __future__ import annotations\n\nimport re\nfrom dataclasses import dataclass\nfrom datetime import date, datetime\nfrom decimal import ROUND_HALF_UP, Decimal\nfrom typing import Any, Mapping, Optional\n\nfrom app.services.erp import vocabulary as v\nfrom app.services.erp.mapping import Contract, Record\n\nMEDIA_TYPE = "application/edi-x12"\nVERSION = "00401"\nGS_VERSION = "004010"\nTRANSACTION = {v.OBJECT_VENDOR_BILL: "810", v.OBJECT_PURCHASE_ORDER: "850", v.OBJECT_GOODS_RECEIPT: "856"}\nFUNCTIONAL_ID = {"810": "IN", "850": "PO", "856": "SH", "997": "FA"}\nSUPPORTED = tuple(TRANSACTION)\n\nUNIT_CODES = frozenset({"EA", "CA", "BX", "PK", "PC", "KG", "LB", "GR", "LT", "GA", "FT", "MR", "M", "YD", "DZ",\n                        "HR", "DA", "MO", "ST", "RL", "SH", "TN", "PR", "UN", "LO"})\nQUALIFIERS_236 = frozenset({"VP", "BP", "VN", "UP", "IN", "SK", "EN", "MG", "CB"})\n\n# (id, type, min, max, mandatory, codes)\nE = tuple\nSPEC: dict[str, tuple[E, ...]] = {\n    "ISA": (("ISA01", "ID", 2, 2, True, ("00", "03")), ("ISA02", "AN", 10, 10, True, None),\n            ("ISA03", "ID", 2, 2, True, ("00", "01")), ("ISA04", "AN", 10, 10, True, None),\n            ("ISA05", "ID", 2, 2, True, ("01", "08", "12", "14", "16", "ZZ")), ("ISA06", "AN", 15, 15, True, None),\n            ("ISA07", "ID", 2, 2, True, ("01", "08", "12", "14", "16", "ZZ")), ("ISA08", "AN", 15, 15, True, None),\n            ("ISA09", "DT", 6, 6, True, None), ("ISA10", "TM", 4, 4, True, None), ("ISA11", "ID", 1, 1, True, ("U",)),\n            ("ISA12", "ID", 5, 5, True, (VERSION,)), ("ISA13", "N0", 9, 9, True, None),\n            ("ISA14", "ID", 1, 1, True, ("0", "1")), ("ISA15", "ID", 1, 1, True, ("P", "T")),\n            ("ISA16", "AN", 1, 1, True, None)),\n    "GS": (("GS01", "ID", 2, 2, True, ("IN", "PO", "SH", "FA")), ("GS02", "AN", 2, 15, True, None),\n           ("GS03", "AN", 2, 15, True, None), ("GS04", "DT", 8, 8, True, None), ("GS05", "TM", 4, 8, True, None),\n           ("GS06", "N0", 1, 9, True, None), ("GS07", "ID", 1, 2, True, ("X",)),\n           ("GS08", "AN", 1, 12, True, (GS_VERSION,))),\n    "ST": (("ST01", "ID", 3, 3, True, ("810", "850", "856", "997")), ("ST02", "AN", 4, 9, True, None)),\n    "SE": (("SE01", "N0", 1, 10, True, None), ("SE02", "AN", 4, 9, True, None)),\n    "GE": (("GE01", "N0", 1, 6, True, None), ("GE02", "N0", 1, 9, True, None)),\n    "IEA": (("IEA01", "N0", 1, 5, True, None), ("IEA02", "N0", 9, 9, True, None)),\n    "BIG": (("BIG01", "DT", 8, 8, True, None), ("BIG02", "AN", 1, 22, True, None), ("BIG03", "DT", 8, 8, False, None),\n            ("BIG04", "AN", 1, 22, False, None)),\n    "CUR": (("CUR01", "ID", 2, 3, True, ("SE", "BY", "BT")), ("CUR02", "ID", 3, 3, True, None)),\n    "N1": (("N101", "ID", 2, 3, True, ("SE", "BT", "BY", "ST", "SF", "SU", "VN")), ("N102", "AN", 1, 60, False, None),\n           ("N103", "ID", 1, 2, False, ("1", "9", "91", "92", "ZZ")), ("N104", "AN", 2, 80, False, None)),\n    "ITD": (("ITD01", "ID", 2, 2, False, ("01", "05", "14")), ("ITD02", "ID", 1, 2, False, ("1", "2", "3", "15")),\n            ("ITD03", "R", 1, 6, False, None), ("ITD04", "DT", 8, 8, False, None), ("ITD05", "N0", 1, 3, False, None),\n            ("ITD06", "DT", 8, 8, False, None), ("ITD07", "N0", 1, 3, False, None)),\n    "IT1": (("IT101", "AN", 1, 20, False, None), ("IT102", "R", 1, 10, True, None),\n            ("IT103", "ID", 2, 2, True, tuple(sorted(UNIT_CODES))), ("IT104", "R", 1, 17, True, None),\n            ("IT105", "ID", 2, 2, False, None), ("IT106", "ID", 2, 2, False, tuple(sorted(QUALIFIERS_236))),\n            ("IT107", "AN", 1, 48, False, None)),\n    "PID": (("PID01", "ID", 1, 1, True, ("F",)), ("PID02", "ID", 2, 3, False, None), ("PID03", "ID", 2, 2, False, None),\n            ("PID04", "AN", 1, 12, False, None), ("PID05", "AN", 1, 80, True, None)),\n    "TDS": (("TDS01", "N2", 1, 15, True, None),),\n    "TXI": (("TXI01", "ID", 2, 2, True, ("TX", "GS", "VA", "ST")), ("TXI02", "R", 1, 18, True, None)),\n    "CTT": (("CTT01", "N0", 1, 6, True, None),),\n    "BEG": (("BEG01", "ID", 2, 2, True, ("00", "05", "07")), ("BEG02", "ID", 2, 2, True, ("SA", "NE", "KN", "RL")),\n            ("BEG03", "AN", 1, 22, True, None), ("BEG04", "AN", 1, 30, False, None), ("BEG05", "DT", 8, 8, True, None)),\n    "PO1": (("PO101", "AN", 1, 20, False, None), ("PO102", "R", 1, 15, True, None),\n            ("PO103", "ID", 2, 2, True, tuple(sorted(UNIT_CODES))), ("PO104", "R", 1, 17, False, None),\n            ("PO105", "ID", 2, 2, False, None), ("PO106", "ID", 2, 2, False, tuple(sorted(QUALIFIERS_236))),\n            ("PO107", "AN", 1, 48, False, None)),\n    "AMT": (("AMT01", "ID", 1, 3, True, ("TT", "1", "GV")), ("AMT02", "R", 1, 18, True, None)),\n    "BSN": (("BSN01", "ID", 2, 2, True, ("00", "05")), ("BSN02", "AN", 2, 30, True, None),\n            ("BSN03", "DT", 8, 8, True, None), ("BSN04", "TM", 4, 8, True, None)),\n    "HL": (("HL01", "AN", 1, 12, True, None), ("HL02", "AN", 1, 12, False, None),\n           ("HL03", "ID", 1, 2, True, ("S", "O", "P", "I")), ("HL04", "ID", 1, 1, False, ("0", "1"))),\n    "DTM": (("DTM01", "ID", 3, 3, True, ("011", "017", "002")), ("DTM02", "DT", 8, 8, True, None)),\n    "PRF": (("PRF01", "AN", 1, 22, True, None),),\n    "LIN": (("LIN01", "AN", 1, 20, False, None), ("LIN02", "ID", 2, 2, True, tuple(sorted(QUALIFIERS_236))),\n            ("LIN03", "AN", 1, 48, True, None)),\n    "SN1": (("SN101", "AN", 1, 20, False, None), ("SN102", "R", 1, 10, True, None),\n            ("SN103", "ID", 2, 2, True, tuple(sorted(UNIT_CODES)))),\n    "AK1": (("AK101", "ID", 2, 2, True, ("IN", "PO", "SH")), ("AK102", "N0", 1, 9, True, None)),\n    "AK2": (("AK201", "ID", 3, 3, True, ("810", "850", "856")), ("AK202", "AN", 4, 9, True, None)),\n    "AK3": (("AK301", "ID", 2, 3, True, None), ("AK302", "N0", 1, 6, True, None), ("AK303", "AN", 1, 6, False, None),\n            ("AK304", "ID", 1, 3, False, None)),\n    "AK4": (("AK401", "AN", 1, 6, True, None), ("AK402", "N0", 1, 4, False, None), ("AK403", "ID", 1, 3, True, None),\n            ("AK404", "AN", 1, 99, False, None)),\n    "AK5": (("AK501", "ID", 1, 1, True, ("A", "E", "M", "R", "W", "X")), ("AK502", "ID", 1, 3, False, None)),\n    "AK9": (("AK901", "ID", 1, 1, True, ("A", "E", "M", "P", "R", "W", "X")), ("AK902", "N0", 1, 6, True, None),\n            ("AK903", "N0", 1, 6, True, None), ("AK904", "N0", 1, 6, True, None)),\n}\n#: Segment order inside each transaction set (ST .. SE), as a regular expression over segment ids.\nGRAMMAR = {\n    "810": r"ST BIG (CUR )?(N1 )+(ITD )?(DTM )?(IT1 (PID )?)+TDS (TXI )?(CTT )?SE ",\n    "850": r"ST BEG (CUR )?(N1 )+(PO1 (PID )?)+(CTT )?(AMT )?SE ",\n    "856": r"ST BSN HL (DTM )?(N1 )*HL PRF (HL LIN SN1 (PID )?)+CTT SE ",\n    "997": r"ST AK1 (AK2 (AK3 (AK4 )*)*AK5 )*AK9 SE ",\n}\n\n_CONTRACT_810 = Contract(\n    header={"invoice_number": True, "invoice_date": True, "po_number": False, "po_date": False, "currency": False,\n            "seller_name": True, "seller_id": False, "buyer_name": True, "buyer_id": False, "terms_net_days": False,\n            "terms_due_date": False, "total_amount": True, "tax_amount": False},\n    lines={"line_number": False, "quantity": True, "unit": True, "unit_price": True, "product_id": False,\n           "product_qualifier": False, "description": False},\n    open=False, needs_lines=True)\n_CONTRACT_850 = Contract(\n    header={"po_number": True, "po_date": True, "currency": False, "buyer_name": True, "buyer_id": False,\n            "seller_name": True, "seller_id": False, "total_amount": False},\n    lines={"line_number": False, "quantity": True, "unit": True, "unit_price": False, "product_id": False,\n           "product_qualifier": False, "description": False},\n    open=False, needs_lines=True)\n_CONTRACT_856 = Contract(\n    header={"shipment_id": True, "ship_date": True, "po_number": True, "ship_from_name": False, "ship_to_name": False},\n    lines={"line_number": False, "product_id": True, "product_qualifier": False, "quantity": True, "unit": True,\n           "description": False},\n    open=False, needs_lines=True)\nCONTRACTS = {v.OBJECT_VENDOR_BILL: _CONTRACT_810, v.OBJECT_PURCHASE_ORDER: _CONTRACT_850,\n             v.OBJECT_GOODS_RECEIPT: _CONTRACT_856}\n\n\nclass X12Error(ValueError):\n    pass\n\n\n@dataclass(frozen=True)\nclass Envelope:\n    sender_qualifier: str = "ZZ"\n    sender_id: str = "FLOWPILOT"\n    receiver_qualifier: str = "ZZ"\n    receiver_id: str = "PARTNER"\n    usage: str = "P"                 # P production, T test\n    ack_requested: str = "1"         # ask for a TA1 / 997\n    element: str = "*"\n    segment: str = "~"\n    component: str = ">"\n    newline: bool = True\n\n    @classmethod\n    def from_config(cls, config: Mapping[str, Any] | None) -> "Envelope":\n        raw = dict((config or {}).get("x12") or {})\n        env = cls(**{k: str(raw[k]) if k != "newline" else bool(raw[k]) for k in cls.__dataclass_fields__ if k in raw})\n        seps = {env.element, env.segment, env.component}\n        if len(seps) != 3 or any(len(s) != 1 or s.isalnum() or s == " " for s in seps):\n            raise X12Error("the X12 separators must be three different single non-alphanumeric characters")\n        for name, value, limit in (("sender_id", env.sender_id, 15), ("receiver_id", env.receiver_id, 15)):\n            if not 2 <= len(value) <= limit:\n                raise X12Error(f"x12.{name} is 2 to {limit} characters")\n        return env\n\n\n@dataclass(frozen=True)\nclass ControlNumbers:\n    interchange: int\n    group: int\n    transaction: str = "0001"\n\n    def as_json(self) -> dict:\n        return {"isa13": f"{self.interchange:09d}", "gs06": str(self.group), "st02": self.transaction}\n\n\n# ---------------------------------------------------------------------------\n# writing\n# ---------------------------------------------------------------------------\n\n\ndef _clean(value: Any, env: Envelope, limit: int) -> str:\n    text = "" if value is None else str(value)\n    for sep in (env.element, env.segment, env.component, "^", "\\r", "\\n"):\n        text = text.replace(sep, " ")\n    text = "".join(ch for ch in text if 32 <= ord(ch) < 127)\n    return " ".join(text.split())[:limit]\n\n\ndef _r(value: Any) -> str:\n    """X12 R: a decimal with an explicit point only when needed, no exponent, no trailing zeros."""\n    d = Decimal(str(value))\n    text = format(d.normalize(), "f")\n    return text[:-2] if text.endswith(".0") else text\n\n\ndef _n2(value: Any) -> str:\n    """X12 N2: implied two decimals (1250.50 -> 125050). ARCH47-S1:n2-exact. An amount N2 cannot carry exactly\n    (a third decimal, as KWD / BHD amounts can have) is refused, never rounded."""\n    scaled = Decimal(str(value)) * 100\n    d = scaled.quantize(Decimal(1), rounding=ROUND_HALF_UP)\n    if d != scaled:\n        raise X12Error(f"{value} has more than two decimals: an X12 N2 amount (TDS01) cannot carry it exactly")\n    return str(int(d))\n\n\ndef _d8(value: Any) -> str:\n    if isinstance(value, datetime):\n        value = value.date()\n    if isinstance(value, date):\n        return value.strftime("%Y%m%d")\n    return str(value).replace("-", "")[:8]\n\n\ndef render(record: Record, object_kind: str, *, control: ControlNumbers, at: datetime,\n           config: Mapping[str, Any] | None = None) -> bytes:\n    if object_kind not in TRANSACTION:\n        raise X12Error(f"X12 810/850/856 carries vendor bills, purchase orders and goods receipts, not {object_kind}")\n    env = Envelope.from_config(config)\n    ts = TRANSACTION[object_kind]\n    h = record.header_dict()\n    lines = record.line_dicts()\n    body: list[list[str]] = [["ST", ts, control.transaction]]\n    c = lambda value, n: _clean(value, env, n)  # noqa: E731\n    if ts == "810":\n        body.append(["BIG", _d8(h["invoice_date"]), c(h["invoice_number"], 22),\n                     _d8(h["po_date"]) if h.get("po_date") else "", c(h.get("po_number"), 22)])\n        if h.get("currency"):\n            body.append(["CUR", "SE", c(h["currency"], 3).upper()])\n        body.append(["N1", "SE", c(h["seller_name"], 60)] + (["92", c(h["seller_id"], 80)] if h.get("seller_id") else []))\n        body.append(["N1", "BT", c(h["buyer_name"], 60)] + (["92", c(h["buyer_id"], 80)] if h.get("buyer_id") else []))\n        if h.get("terms_net_days") is not None or h.get("terms_due_date"):\n            body.append(["ITD", "01", "3", "", "", "", _d8(h["terms_due_date"]) if h.get("terms_due_date") else "",\n                         str(int(h["terms_net_days"])) if h.get("terms_net_days") is not None else ""])\n        for n, ln in enumerate(lines, start=1):\n            body.append(["IT1", c(ln.get("line_number") or n, 20), _r(ln["quantity"]), c(ln["unit"], 2).upper(),\n                         _r(ln["unit_price"]), "",\n                         c(ln.get("product_qualifier") or "VP", 2).upper() if ln.get("product_id") else "",\n                         c(ln.get("product_id"), 48)])\n            if ln.get("description"):\n                body.append(["PID", "F", "", "", "", c(ln["description"], 80)])\n        body.append(["TDS", _n2(h["total_amount"])])\n        if h.get("tax_amount") is not None:\n            body.append(["TXI", "TX", _r(h["tax_amount"])])\n        body.append(["CTT", str(len(lines))])\n    elif ts == "850":\n        body.append(["BEG", "00", "SA", c(h["po_number"], 22), "", _d8(h["po_date"])])\n        if h.get("currency"):\n            body.append(["CUR", "BY", c(h["currency"], 3).upper()])\n        body.append(["N1", "BY", c(h["buyer_name"], 60)] + (["92", c(h["buyer_id"], 80)] if h.get("buyer_id") else []))\n        body.append(["N1", "SE", c(h["seller_name"], 60)] + (["92", c(h["seller_id"], 80)] if h.get("seller_id") else []))\n        for n, ln in enumerate(lines, start=1):\n            body.append(["PO1", c(ln.get("line_number") or n, 20), _r(ln["quantity"]), c(ln["unit"], 2).upper(),\n                         _r(ln["unit_price"]) if ln.get("unit_price") is not None else "", "",\n                         c(ln.get("product_qualifier") or "VP", 2).upper() if ln.get("product_id") else "",\n                         c(ln.get("product_id"), 48)])\n            if ln.get("description"):\n                body.append(["PID", "F", "", "", "", c(ln["description"], 80)])\n        body.append(["CTT", str(len(lines))])\n        if h.get("total_amount") is not None:\n            body.append(["AMT", "TT", _r(h["total_amount"])])\n    else:\n        ship = h["ship_date"]\n        body.append(["BSN", "00", c(h["shipment_id"], 30), _d8(ship), at.strftime("%H%M")])\n        body.append(["HL", "1", "", "S", "1"])\n        body.append(["DTM", "011", _d8(ship)])\n        if h.get("ship_from_name"):\n            body.append(["N1", "SF", c(h["ship_from_name"], 60)])\n        if h.get("ship_to_name"):\n            body.append(["N1", "ST", c(h["ship_to_name"], 60)])\n        body.append(["HL", "2", "1", "O", "1"])\n        body.append(["PRF", c(h["po_number"], 22)])\n        hl = 2\n        for n, ln in enumerate(lines, start=1):\n            hl += 1\n            body.append(["HL", str(hl), "2", "I", "0"])\n            body.append(["LIN", c(ln.get("line_number") or n, 20), c(ln.get("product_qualifier") or "VP", 2).upper(),\n                         c(ln["product_id"], 48)])\n            body.append(["SN1", c(ln.get("line_number") or n, 20), _r(ln["quantity"]), c(ln["unit"], 2).upper()])\n            if ln.get("description"):\n                body.append(["PID", "F", "", "", "", c(ln["description"], 80)])\n        body.append(["CTT", str(hl)])\n    body.append(["SE", str(len(body) + 1), control.transaction])\n    return _envelope(body, ts, env, control, at)\n\n\ndef _envelope(body: list[list[str]], ts: str, env: Envelope, control: ControlNumbers, at: datetime) -> bytes:\n    isa = ["ISA", "00", " " * 10, "00", " " * 10, env.sender_qualifier, env.sender_id.ljust(15)[:15],\n           env.receiver_qualifier, env.receiver_id.ljust(15)[:15], at.strftime("%y%m%d"), at.strftime("%H%M"), "U",\n           VERSION, f"{control.interchange:09d}", env.ack_requested, env.usage, env.component]\n    gs = ["GS", FUNCTIONAL_ID[ts], env.sender_id.strip()[:15], env.receiver_id.strip()[:15], at.strftime("%Y%m%d"),\n          at.strftime("%H%M"), str(control.group), "X", GS_VERSION]\n    tail = [["GE", "1", str(control.group)], ["IEA", "1", f"{control.interchange:09d}"]]\n    segments = [isa, gs, *body, *tail]\n    end = env.segment + ("\\n" if env.newline else "")\n    text = end.join(env.element.join(_trim(seg)) for seg in segments) + end\n    return text.encode("ascii")\n\n\ndef _trim(seg: list[str]) -> list[str]:\n    """Trailing empty elements are dropped (X12: no trailing element separators). ISA keeps all 16."""\n    if seg[0] == "ISA":\n        return seg\n    out = list(seg)\n    while len(out) > 1 and out[-1] == "":\n        out.pop()\n    return out\n\n\n# ---------------------------------------------------------------------------\n# reading and validation (independent of the writer)\n# ---------------------------------------------------------------------------\n\n\n@dataclass\nclass Interchange:\n    element: str\n    segment: str\n    component: str\n    segments: list[list[str]]\n\n\ndef parse(data: bytes | str) -> Interchange:\n    text = data.decode("ascii") if isinstance(data, (bytes, bytearray)) else data\n    text = text.lstrip("\ufeff")\n    if not text.startswith("ISA"):\n        raise X12Error("an interchange starts with ISA")\n    if len(text) < 106:\n        raise X12Error("shorter than an ISA segment")\n    element, component, segment = text[3], text[104], text[105]\n    rows = []\n    for raw in text.split(segment):\n        raw = raw.strip("\\r\\n")\n        if raw:\n            rows.append(raw.split(element))\n    return Interchange(element, segment, component, rows)\n\n\ndef _check_element(seg: str, spec: E, value: str, problems: list[str], where: str) -> None:\n    ref, kind, lo, hi, mandatory, codes = spec\n    if value == "":\n        if mandatory:\n            problems.append(f"{where} {ref} is mandatory")\n        return\n    if not lo <= len(value) <= hi:\n        problems.append(f"{where} {ref} length {len(value)} not in {lo}-{hi}: {value!r}")\n    if kind in ("AN", "ID") and any(ord(ch) < 32 or ord(ch) > 126 for ch in value):\n        problems.append(f"{where} {ref} has characters outside the X12 character set")\n    if kind == "ID" and codes and value not in codes:\n        problems.append(f"{where} {ref} {value!r} is not a valid code ({\', \'.join(codes[:12])})")\n    if kind == "N0" and not re.fullmatch(r"-?\\d+", value):\n        problems.append(f"{where} {ref} {value!r} is not N0")\n    if kind == "N2" and not re.fullmatch(r"-?\\d+", value):\n        problems.append(f"{where} {ref} {value!r} is not N2 (implied decimals)")\n    if kind == "R" and not re.fullmatch(r"-?(\\d+\\.?\\d*|\\.\\d+)", value):\n        problems.append(f"{where} {ref} {value!r} is not R")\n    if kind == "DT":\n        fmt = "%y%m%d" if len(value) == 6 else "%Y%m%d"\n        try:\n            datetime.strptime(value, fmt)\n        except ValueError:\n            problems.append(f"{where} {ref} {value!r} is not a date")\n    if kind == "TM" and not (re.fullmatch(r"\\d{4}(\\d{2})?", value) and int(value[:2]) < 24 and int(value[2:4]) < 60):\n        problems.append(f"{where} {ref} {value!r} is not a time")\n\n\ndef validate(data: bytes | str) -> list[str]:\n    """Every problem with an interchange (empty when it conforms)."""\n    problems: list[str] = []\n    try:\n        ix = parse(data)\n    except (X12Error, UnicodeDecodeError) as exc:\n        return [str(exc)]\n    text = data.decode("ascii") if isinstance(data, (bytes, bytearray)) else data\n    isa_raw = text[: text.index(ix.segment) + 1]\n    if len(isa_raw) != 106:\n        problems.append(f"ISA is {len(isa_raw)} characters, not 106")\n    segs = ix.segments\n    for n, seg in enumerate(segs, start=1):\n        sid = seg[0]\n        spec = SPEC.get(sid)\n        where = f"segment {n} {sid}"\n        if spec is None:\n            problems.append(f"{where}: not a segment this validator knows")\n            continue\n        values = seg[1:]\n        if len(values) > len(spec):\n            problems.append(f"{where}: {len(values)} elements, at most {len(spec)}")\n        if sid != "ISA" and values and values[-1] == "":\n            problems.append(f"{where}: trailing empty element")\n        for i, el in enumerate(spec):\n            _check_element(sid, el, values[i] if i < len(values) else "", problems, where)\n        if sid == "ISA" and len(values) == 16 and values[15] != ix.component:\n            problems.append("ISA16 is not the component separator")\n    ids = [s[0] for s in segs]\n    if not ids or ids[0] != "ISA" or ids[-1] != "IEA":\n        problems.append("an interchange is ISA ... IEA")\n        return problems\n    isa, iea = segs[0], segs[-1]\n    groups = 0\n    i = 1\n    while i < len(segs) - 1:\n        if segs[i][0] != "GS":\n            problems.append(f"segment {i + 1}: expected GS, found {segs[i][0]}")\n            break\n        gs = segs[i]\n        groups += 1\n        j = i + 1\n        sets = 0\n        while j < len(segs) and segs[j][0] == "ST":\n            st = segs[j]\n            k = j\n            while k < len(segs) and segs[k][0] != "SE":\n                k += 1\n            if k >= len(segs):\n                problems.append("ST without SE")\n                return problems\n            se = segs[k]\n            sets += 1\n            count = k - j + 1\n            if se[1:2] != [str(count)]:\n                problems.append(f"SE01 is {se[1] if len(se) > 1 else \'?\'}; the transaction set has {count} segments")\n            if se[2:3] != st[2:3]:\n                problems.append(f"SE02 {se[2:3]} does not match ST02 {st[2:3]}")\n            ts = st[1]\n            grammar = GRAMMAR.get(ts)\n            order = " ".join(s[0] for s in segs[j:k + 1]) + " "\n            if grammar and not re.fullmatch(grammar, order):\n                problems.append(f"{ts} segment order not allowed: {order.strip()}")\n            if FUNCTIONAL_ID.get(ts) != gs[1]:\n                problems.append(f"GS01 {gs[1]} does not carry a {ts}")\n            body = segs[j:k + 1]\n            ctt = [s for s in body if s[0] == "CTT"]\n            if ctt:\n                expected = sum(1 for s in body if s[0] in ("IT1", "PO1")) if ts in ("810", "850") \\\n                    else sum(1 for s in body if s[0] == "HL")\n                if ctt[0][1] != str(expected):\n                    problems.append(f"CTT01 is {ctt[0][1]}; the set has {expected}")\n            j = k + 1\n        if j >= len(segs) or segs[j][0] != "GE":\n            problems.append("GS without GE")\n            return problems\n        ge = segs[j]\n        if ge[1:2] != [str(sets)]:\n            problems.append(f"GE01 is {ge[1]}; the group has {sets} transaction set(s)")\n        if ge[2:3] != gs[6:7]:\n            problems.append(f"GE02 {ge[2:3]} does not match GS06 {gs[6:7]}")\n        i = j + 1\n    if iea[1:2] != [str(groups)]:\n        problems.append(f"IEA01 is {iea[1]}; the interchange has {groups} group(s)")\n    if iea[2:3] != isa[13:14]:\n        problems.append(f"IEA02 {iea[2:3]} does not match ISA13 {isa[13:14]}")\n    return problems\n\n\n# ---------------------------------------------------------------------------\n# 997 functional acknowledgement\n# ---------------------------------------------------------------------------\n\n\n@dataclass(frozen=True)\nclass Ack997:\n    group_control: str\n    functional_id: str\n    transactions: tuple[tuple[str, str, str], ...]   # (set id, control number, AK501)\n    group_status: str                                  # AK901\n    included: int\n    received: int\n    accepted: int\n\n    @property\n    def accepted_all(self) -> bool:\n        return self.group_status == "A" and all(t[2] == "A" for t in self.transactions)\n\n    def as_json(self) -> dict:\n        return {"group_control": self.group_control, "functional_id": self.functional_id,\n                "transactions": [list(t) for t in self.transactions], "group_status": self.group_status,\n                "included": self.included, "received": self.received, "accepted": self.accepted}\n\n\ndef parse_997(data: bytes | str) -> Ack997:\n    problems = validate(data)\n    if problems:\n        raise X12Error("not a valid 997: " + "; ".join(problems[:5]))\n    ix = parse(data)\n    sts = [s for s in ix.segments if s[0] == "ST"]\n    if not sts or sts[0][1] != "997":\n        raise X12Error("not a 997")\n    ak1 = next(s for s in ix.segments if s[0] == "AK1")\n    ak9 = next(s for s in ix.segments if s[0] == "AK9")\n    txs = []\n    current: Optional[list[str]] = None\n    for s in ix.segments:\n        if s[0] == "AK2":\n            current = s\n        elif s[0] == "AK5" and current is not None:\n            txs.append((current[1], current[2], s[1]))\n            current = None\n    return Ack997(ak1[2], ak1[1], tuple(txs), ak9[1], int(ak9[2]), int(ak9[3]), int(ak9[4]))\n\n\ndef build_997(interchange: bytes | str, *, status: str = "A", control: int = 1, at: Optional[datetime] = None,\n              sender: str = "PARTNER", receiver: str = "FLOWPILOT") -> bytes:\n    """A 997 answering an interchange (used by the mock partner in the gates and by a person\'s manual ack)."""\n    ix = parse(interchange)\n    gs = next(s for s in ix.segments if s[0] == "GS")\n    sts = [s for s in ix.segments if s[0] == "ST"]\n    at = at or datetime(2026, 1, 1, 12, 0)\n    env = Envelope(sender_id=sender, receiver_id=receiver)\n    body = [["ST", "997", "0001"], ["AK1", gs[1], gs[6]]]\n    for st in sts:\n        body += [["AK2", st[1], st[2]], ["AK5", status]]\n    accepted = len(sts) if status in ("A", "E") else 0\n    body.append(["AK9", status if status != "E" else "E", str(len(sts)), str(len(sts)), str(accepted)])\n    body.append(["SE", str(len(body) + 1), "0001"])\n    return _envelope(body, "997", env, ControlNumbers(control, control), at)\n\n\ndef correlate(ack: Ack997, control_numbers: Mapping[str, Any], object_kind: str) -> tuple[str, str]:\n    """(outcome, message): does this 997 acknowledge THIS posting, and how?"""\n    ts = TRANSACTION[object_kind]\n    if ack.group_control != str(control_numbers.get("gs06")) or ack.functional_id != FUNCTIONAL_ID[ts]:\n        return v.OUTCOME_PENDING, "a 997 for another group"\n    ours = [t for t in ack.transactions if t[0] == ts and t[1] == control_numbers.get("st02")]\n    if ack.group_status in ("R",) or any(t[2] in ("R", "M", "W", "X") for t in ours):\n        return v.OUTCOME_REJECTED, f"the partner rejected the {ts} (AK9 {ack.group_status}, AK5 {[t[2] for t in ours]})"\n    if not ours and ack.transactions:\n        return v.OUTCOME_MISMATCH, f"the 997 names group {ack.group_control} but not transaction set {ts} " \\\n                                   f"{control_numbers.get(\'st02\')}"\n    if ack.group_status in ("E", "P") or any(t[2] == "E" for t in ours):\n        return v.OUTCOME_MISMATCH, f"accepted with errors (AK9 {ack.group_status}): check what the partner kept"\n    if ack.accepted_all and ack.accepted >= 1:\n        return v.OUTCOME_ACCEPTED, f"997 accepted (group {ack.group_control})"\n    return v.OUTCOME_MISMATCH, f"a 997 that does not accept the set (AK9 {ack.group_status})"\n\n\n__all__ = ["Ack997", "CONTRACTS", "ControlNumbers", "Envelope", "GRAMMAR", "MEDIA_TYPE", "SPEC", "SUPPORTED",\n           "TRANSACTION", "X12Error", "build_997", "correlate", "parse", "parse_997", "render", "validate"]\n'),
    Op(path='backend/app/services/erp/formats/xmlsafe.py', kind='new', final_sha='99e0c1c42708c3aeb20e31f1e7d9b3597e27b7d0d0b36f7d762f1bb287e49feb', encoding='utf-8', executable=False,
       variants=(), content='"""ARCH47-S1:xmlsafe — the ONE module of the ERP code that imports lxml.\n\nARCH-16 confines XML parsing (`scripts/verify_arch16.py` S1): an XML parser\nleft at its defaults can be made to read local files or the network through an\nexternal entity (XXE) or to exhaust memory through nested entities ("billion\nlaughs"). ERP postings read XML that comes from outside — Tally\'s import\nRESPONSE, `.ack` files, a response file a person pastes — so every parse goes\nthrough here:\n\n  parse(data)             untrusted input. A document that declares a DOCTYPE\n                          or an ENTITY is refused before lxml sees it; the parser\n                          itself resolves no entities, loads no DTD, touches no\n                          network and refuses huge trees. Raises XMLRefused.\n  parse_vendored(...)     a schema file under app/services/erp/schemas/ (the\n                          OASIS / W3C / ECMA-376 files, some of which carry an\n                          internal DTD subset); refused for any other path.\n                          Entities are still not resolved and nothing is fetched:\n                          imports resolve only inside the vendored directory\n                          (xsd._resolver).\n  compile_schema(doc)     an XMLSchema from a vendored document.\n\nBuilding documents (Element, SubElement, tostring) is not parsing and is\nre-exported for the writers (ubl.py, tally.py).\n"""\n\nfrom __future__ import annotations\n\nimport re\nfrom pathlib import Path\nfrom typing import Any, Optional\n\nfrom lxml import etree\n\nSCHEMAS = (Path(__file__).resolve().parent.parent / "schemas").resolve()\n#: no DOCTYPE / ENTITY declaration anywhere (case-insensitive, whitespace-tolerant, UTF-16 decoded first)\n_DECLARATION = re.compile(rb"<!\\s*(DOCTYPE|ENTITY)", re.I)\nMAX_BYTES = 20 * 1024 * 1024\n\nElement = etree.Element\nSubElement = etree.SubElement\ntostring = etree.tostring\nResolver = etree.Resolver\nXMLSyntaxError = etree.XMLSyntaxError\n\n\nclass XMLRefused(ValueError):\n    """Untrusted XML that is not well-formed, too large, or declares a DOCTYPE / ENTITY."""\n\n\ndef _hardened(*, allow_dtd_subset: bool = False) -> Any:\n    # allow_dtd_subset only records the caller\'s intent: the parser settings are identical (a vendored\n    # schema\'s internal subset is read, never loaded as a DTD, and its entities are never resolved).\n    return etree.XMLParser(resolve_entities=False, no_network=True, load_dtd=False, dtd_validation=False,\n                           huge_tree=False, recover=False)\n\n\ndef _as_bytes(data: Any) -> bytes:\n    if isinstance(data, str):\n        return data.encode("utf-8")\n    if isinstance(data, (bytes, bytearray, memoryview)):\n        return bytes(data)\n    raise XMLRefused(f"XML must be bytes or text, not {type(data).__name__}")\n\n\ndef _declares(raw: bytes) -> bool:\n    if _DECLARATION.search(raw):\n        return True\n    if raw[:2] in (b"\\xff\\xfe", b"\\xfe\\xff") or b"\\x00<" in raw[:64] or b"<\\x00" in raw[:64]:\n        for codec in ("utf-16", "utf-16-le", "utf-16-be"):\n            try:\n                if _DECLARATION.search(raw.decode(codec, errors="ignore").encode("utf-8")):\n                    return True\n            except LookupError:  # pragma: no cover\n                continue\n    return False\n\n\ndef parse(data: Any) -> Any:\n    """The root element of UNTRUSTED XML, or XMLRefused."""\n    raw = _as_bytes(data)\n    if len(raw) > MAX_BYTES:\n        raise XMLRefused(f"XML larger than {MAX_BYTES} bytes")\n    if _declares(raw):\n        raise XMLRefused("XML declaring a DOCTYPE or an ENTITY is refused (external and nested entities)")\n    try:\n        root = etree.fromstring(raw, _hardened())\n    except etree.XMLSyntaxError as exc:\n        raise XMLRefused(f"not well-formed XML: {exc}") from exc\n    if root is None:\n        raise XMLRefused("empty XML document")\n    return root\n\n\ndef parse_vendored(data: bytes, *, path: Path, resolver: Optional[Any] = None) -> Any:\n    """A vendored schema document (trusted: it ships in the repository); any other path is refused."""\n    resolved = Path(path).resolve()\n    if SCHEMAS not in resolved.parents:\n        raise XMLRefused(f"not a vendored schema: {path}")\n    parser = _hardened(allow_dtd_subset=True)\n    if resolver is not None:\n        parser.resolvers.add(resolver)\n    return etree.fromstring(data, parser, base_url=resolved.as_uri())\n\n\ndef compile_schema(doc: Any) -> Any:\n    return etree.XMLSchema(etree.ElementTree(doc))\n\n\n__all__ = ["Element", "MAX_BYTES", "Resolver", "SCHEMAS", "SubElement", "XMLRefused", "XMLSyntaxError",\n           "compile_schema", "parse", "parse_vendored", "tostring"]\n'),
