    Op(path='backend/app/services/erp/transport/http.py', kind='new', final_sha='508ddd33b1988708035e67406b2b17b01c30e881024ef07a7bf2d52a80ecbcc2', encoding='utf-8', executable=False,
       variants=(('eb5c8cfa1833186bafe15186f818bc29fb2d1b1ac663d1b3f923b99442b9daf3', (('        return v.OUTCOME_UNCERTAIN, text\n    return v.OUTCOME_UNCERTAIN, f"{type(exc).__name__}: {text}"\n', '        return v.OUTCOME_UNCERTAIN, text\n    if isinstance(exc, ConnectionRefusedError):\n        # ARCH47-S1:refused-transient. A connection the server refused carried no request (the SSRF-safe client\n        # reports these as ConnectError; this is the belt for any raw one): retry, no probe needed.\n        return v.OUTCOME_TRANSIENT, f"{type(exc).__name__}: {text}"\n    return v.OUTCOME_UNCERTAIN, f"{type(exc).__name__}: {text}"\n'), ('        return (v.OUTCOME_TRANSIENT, text) if text.startswith("Connection to") else (v.OUTCOME_UNCERTAIN, text)\n', '        sent = getattr(exc, "request_sent", False) or not text.startswith("Connection to")\n        return (v.OUTCOME_UNCERTAIN, text) if sent else (v.OUTCOME_TRANSIENT, text)\n'))),), content='"""ARCH47-S1:http — REST / OData delivery through the SSRF-safe client.\n\nEGRESS. Every request goes through app.core.ssrf_client.SSRFSafeHTTPClient,\nwhich resolves the host AT CONNECT TIME, refuses private, loopback,\nlink-local, CGNAT, multicast, reserved and cloud-metadata addresses, pins the\nconnection to the address it validated (no DNS rebinding between the check and\nthe connect), speaks HTTPS only, and caps time and response size. The target\'s\nURL was also checked when it was saved (webhook_service\'s preflight); the\nconnect-time check is the one that cannot be raced. Nothing is fetched at import.\n\nWHEN A FAILURE HAPPENED decides what is safe:\n\n  TRANSIENT   nothing reached the target (no connection, a refused TLS\n              handshake, DNS), or the target said "try later" (408, 425, 429,\n              500, 502, 503, 504): retry with backoff and jitter\n  PERMANENT   the target refused the request (other 4xx), or the URL is not\n              allowed: a person must change something\n  UNCERTAIN   the request may have been processed (the connection broke, or\n              the response timed out, AFTER the request was written): never\n              re-sent blind -- the ledger probes the target first\n\nCredentials never appear in a log, an exception message, or an attempt row:\nresponses are recorded truncated and with any bearer / token / secret value\nmasked (`scrub`).\n"""\n\nfrom __future__ import annotations\n\nimport base64\nimport json\nimport re\nimport time\nfrom dataclasses import dataclass, field\nfrom typing import Any, Callable, Mapping, Optional\nfrom urllib.parse import urlencode, urlsplit\n\nfrom app.services.erp import vocabulary as v\n\nTRANSIENT_STATUSES = frozenset({408, 425, 429, 500, 502, 503, 504})\nMAX_BODY_RECORDED = 2000\n_SECRETS = re.compile(r\'("?(?:access_token|refresh_token|client_secret|password|token|secret|authorization|apikey|\'\n                      r\'api_key)"?\\s*[:=]\\s*"?)([^",&\\s]+)\', re.I)\n\n\ndef scrub(text: str) -> str:\n    return _SECRETS.sub(lambda m: m.group(1) + "***", text or "")[:MAX_BODY_RECORDED]\n\n\n@dataclass\nclass Response:\n    kind: str                         # OK TRANSIENT PERMANENT UNCERTAIN\n    status: Optional[int] = None\n    headers: dict[str, str] = field(default_factory=dict)\n    body: bytes = b""\n    message: str = ""\n    retry_after: Optional[int] = None\n\n    def json(self) -> Any:\n        from app.services.erp.formats.jsonapi import loads\n\n        try:\n            return loads(self.body) if self.body else None\n        except (ValueError, UnicodeDecodeError):\n            return None\n\n    def recorded(self) -> dict:\n        return {"status": self.status, "body": scrub(self.body.decode("utf-8", "replace")),\n                "location": self.headers.get("location")}\n\n\nclass HttpError(RuntimeError):\n    def __init__(self, kind: str, message: str) -> None:\n        super().__init__(message)\n        self.kind = kind\n\n\n#: Replaced by the gates with a client that trusts the mock servers\' certificate (allow_private_ranges and a\n#: test SSL context are refused by the client itself in production).\ndef _default_client_factory(timeout: float) -> Any:\n    from app.core.ssrf_client import SSRFSafeHTTPClient\n\n    return SSRFSafeHTTPClient(connect_timeout=min(10.0, timeout), total_timeout=timeout)\n\n\nclient_factory: Callable[[float], Any] = _default_client_factory\n\n\ndef _classify(exc: Exception) -> tuple[str, str]:\n    from app.core import ssrf_client as S\n\n    text = str(exc)\n    if isinstance(exc, (S.ForbiddenAddressError, S.InvalidURLError)):\n        return v.OUTCOME_PERMANENT, f"refused by the egress guard: {text}"\n    if isinstance(exc, S.DNSResolutionError):\n        return v.OUTCOME_TRANSIENT, text\n    if isinstance(exc, S.TLSError):\n        return v.OUTCOME_TRANSIENT, text\n    if isinstance(exc, S.ConnectError):\n        # "Connection to ... failed": the socket never opened -- nothing was sent.\n        # "Communication with ... failed": the request was (being) written.\n        sent = getattr(exc, "request_sent", False) or not text.startswith("Connection to")\n        return (v.OUTCOME_UNCERTAIN, text) if sent else (v.OUTCOME_TRANSIENT, text)\n    if isinstance(exc, S.TimeoutExceededError):\n        return (v.OUTCOME_TRANSIENT, text) if "before DNS" in text else (v.OUTCOME_UNCERTAIN, text)\n    if isinstance(exc, S.ResponseTooLargeError):\n        return v.OUTCOME_UNCERTAIN, text\n    if isinstance(exc, ConnectionRefusedError):\n        # ARCH47-S1:refused-transient. A connection the server refused carried no request (the SSRF-safe client\n        # reports these as ConnectError; this is the belt for any raw one): retry, no probe needed.\n        return v.OUTCOME_TRANSIENT, f"{type(exc).__name__}: {text}"\n    return v.OUTCOME_UNCERTAIN, f"{type(exc).__name__}: {text}"\n\n\ndef base_url(config: Mapping[str, Any]) -> str:\n    url = str(((config.get("http") or {}).get("base_url") or "")).rstrip("/")\n    parts = urlsplit(url)\n    if parts.scheme != "https" or not parts.hostname:\n        raise HttpError(v.OUTCOME_PERMANENT, "the target needs http.base_url, an https:// URL")\n    if parts.username or parts.password:\n        raise HttpError(v.OUTCOME_PERMANENT, "credentials go in the target\'s credential, never in the URL")\n    return url\n\n\nclass Session:\n    """One delivery\'s conversation with a target: auth, CSRF, the request, probes, reads."""\n\n    def __init__(self, *, auth_mode: str, credential: Optional[dict], config: Mapping[str, Any],\n                 timeout: Optional[float] = None) -> None:\n        self.auth_mode = auth_mode\n        self.credential = dict(credential or {})\n        self.config = config\n        self.timeout = float(timeout or (config.get("http") or {}).get("timeout_seconds") or 30.0)\n        self.timeout = max(5.0, min(self.timeout, 120.0))\n        self.client = client_factory(self.timeout)\n        self.credential_changed = False\n        self.csrf: Optional[tuple[str, str]] = None\n        self.log: list[dict] = []\n\n    # -- auth ------------------------------------------------------------------------\n    def _token_request(self, form: dict[str, str]) -> dict:\n        oauth = dict(self.config.get("oauth") or {})\n        url = str(oauth.get("token_url") or "")\n        parts = urlsplit(url)\n        if parts.scheme != "https" or not parts.hostname:\n            raise HttpError(v.OUTCOME_PERMANENT, "the target needs oauth.token_url, an https:// URL")\n        cid, secret = self.credential.get("client_id", ""), self.credential.get("client_secret", "")\n        headers = {"Content-Type": "application/x-www-form-urlencoded", "Accept": "application/json"}\n        if oauth.get("client_auth", "basic") == "basic":\n            headers["Authorization"] = "Basic " + base64.b64encode(f"{cid}:{secret}".encode()).decode()\n        else:\n            form = {**form, "client_id": cid, "client_secret": secret}\n        if oauth.get("scope"):\n            form = {**form, "scope": str(oauth["scope"])}\n        try:\n            r = self.client.request("POST", url, headers=headers, body=urlencode(form).encode())\n        except Exception as exc:  # noqa: BLE001\n            kind, message = _classify(exc)\n            raise HttpError(v.OUTCOME_TRANSIENT if kind == v.OUTCOME_UNCERTAIN else kind,\n                            f"token endpoint: {message}") from exc\n        if r.status_code in TRANSIENT_STATUSES:\n            raise HttpError(v.OUTCOME_TRANSIENT, f"token endpoint answered {r.status_code}")\n        if r.status_code != 200:\n            raise HttpError(v.OUTCOME_PERMANENT, f"token endpoint refused the credential ({r.status_code}): "\n                                                 f"{scrub(r.body.decode(\'utf-8\', \'replace\'))[:200]}")\n        try:\n            return json.loads(r.body)\n        except ValueError as exc:\n            raise HttpError(v.OUTCOME_PERMANENT, "token endpoint answered something that is not JSON") from exc\n\n    def _access_token(self) -> str:\n        now = time.time()\n        token = self.credential.get("access_token")\n        if token and float(self.credential.get("expires_at") or 0) > now + 60:\n            return str(token)\n        if self.auth_mode == v.AUTH_OAUTH2_REFRESH:\n            if not self.credential.get("refresh_token"):\n                raise HttpError(v.OUTCOME_PERMANENT, "the credential has no refresh_token")\n            got = self._token_request({"grant_type": "refresh_token",\n                                       "refresh_token": str(self.credential["refresh_token"])})\n        else:\n            got = self._token_request({"grant_type": "client_credentials"})\n        if not got.get("access_token"):\n            raise HttpError(v.OUTCOME_PERMANENT, "the token endpoint returned no access_token")\n        self.credential["access_token"] = got["access_token"]\n        self.credential["expires_at"] = now + float(got.get("expires_in") or 3600)\n        if got.get("refresh_token"):\n            self.credential["refresh_token"] = got["refresh_token"]   # rotated refresh tokens are kept\n        self.credential_changed = True\n        return str(got["access_token"])\n\n    def auth_headers(self) -> dict[str, str]:\n        mode = self.auth_mode\n        if mode == v.AUTH_BEARER:\n            if not self.credential.get("token"):\n                raise HttpError(v.OUTCOME_PERMANENT, "the credential has no token")\n            return {"Authorization": f"Bearer {self.credential[\'token\']}"}\n        if mode == v.AUTH_BASIC:\n            raw = f"{self.credential.get(\'username\', \'\')}:{self.credential.get(\'password\', \'\')}".encode()\n            return {"Authorization": "Basic " + base64.b64encode(raw).decode()}\n        if mode == v.AUTH_API_KEY:\n            header = str(self.credential.get("header") or "X-API-Key")\n            if not re.fullmatch(r"[A-Za-z0-9-]{1,64}", header):\n                raise HttpError(v.OUTCOME_PERMANENT, "the API key header name is not a header name")\n            return {header: str(self.credential.get("value") or "")}\n        if mode in (v.AUTH_OAUTH2_REFRESH, v.AUTH_OAUTH2_CLIENT):\n            return {"Authorization": f"Bearer {self._access_token()}"}\n        raise HttpError(v.OUTCOME_PERMANENT, f"{mode} is not an HTTP authentication")\n\n    # -- requests ------------------------------------------------------------------------\n    def request(self, method: str, path_or_url: str, *, body: bytes = b"", headers: Optional[dict] = None,\n                write: bool = False) -> Response:\n        url = path_or_url if path_or_url.startswith("https://") else base_url(self.config) + path_or_url\n        if path_or_url.startswith("https://") and urlsplit(url).hostname != urlsplit(base_url(self.config)).hostname:\n            return Response(v.OUTCOME_PERMANENT, message="a response pointed at another host; not followed")\n        try:\n            all_headers = {"User-Agent": "FlowPilot-ERP/1", **(headers or {}), **self.auth_headers()}\n        except HttpError as exc:\n            return Response(exc.kind, message=str(exc))\n        if write and self.csrf:\n            all_headers["x-csrf-token"], all_headers["Cookie"] = self.csrf\n        if body:\n            all_headers.setdefault("Content-Type", "application/json")\n        started = time.monotonic()\n        try:\n            r = self.client.request(method, url, headers=all_headers, body=body)\n        except Exception as exc:  # noqa: BLE001\n            kind, message = _classify(exc)\n            if not write and kind == v.OUTCOME_UNCERTAIN:\n                kind = v.OUTCOME_TRANSIENT   # a read has no effect to be uncertain about\n            self.log.append({"method": method, "path": urlsplit(url).path, "error": message[:300]})\n            return Response(kind, message=message)\n        status = r.status_code\n        headers_out = {k.lower(): val for k, val in (r.headers or {}).items()}\n        self.log.append({"method": method, "path": urlsplit(url).path, "status": status,\n                         "ms": int((time.monotonic() - started) * 1000)})\n        if 200 <= status < 300:\n            return Response(v.OUTCOME_OK, status, headers_out, r.body)\n        retry_after = None\n        if headers_out.get("retry-after", "").isdigit():\n            retry_after = min(int(headers_out["retry-after"]), v.RETRY_CEILING_SECONDS)\n        kind = v.OUTCOME_TRANSIENT if status in TRANSIENT_STATUSES else v.OUTCOME_PERMANENT\n        return Response(kind, status, headers_out, r.body, f"the target answered {status}", retry_after)\n\n    def fetch_csrf(self, service_path: str) -> Optional[Response]:\n        """S/4HANA OData V2: GET the service root with x-csrf-token: Fetch; keep the token and session cookie."""\n        path = service_path.split("?")[0].rsplit("/", 1)[0] + "/"\n        r = self.request("GET", path, headers={"x-csrf-token": "Fetch", "Accept": "application/json"})\n        if r.kind != v.OUTCOME_OK:\n            return r\n        token = r.headers.get("x-csrf-token")\n        cookie = "; ".join(part.split(";")[0] for part in re.split(r",(?=\\s*[A-Za-z0-9_-]+=)",\n                                                                    r.headers.get("set-cookie", "")) if part.strip())\n        if not token:\n            return Response(v.OUTCOME_PERMANENT, r.status, r.headers, r.body, "the service returned no x-csrf-token")\n        self.csrf = (token, cookie)\n        return None\n\n\n__all__ = ["HttpError", "Response", "Session", "TRANSIENT_STATUSES", "base_url", "client_factory", "scrub"]\n'),
    Op(path='backend/app/services/erp/transport/sftp.py', kind='new', final_sha='db3e53e31e2ecc88bf2a8233a46a89e4c833468251201a2cbf4491ab2583f9ff', encoding='utf-8', executable=False,
       variants=(), content='"""ARCH47-S1:sftp — SFTP delivery (paramiko), with the same egress rules as HTTP.\n\n  * The host is resolved and every address checked (app.core.ssrf_client:\n    no private, loopback, link-local, CGNAT or metadata address); the TCP\n    connection is opened to the validated address and handed to paramiko.\n  * The server\'s host key must match the pinned SHA-256 fingerprint saved with\n    the target (sftp.host_key_sha256, "SHA256:<base64>" as ssh-keygen -l prints\n    it). There is no trust-on-first-use: an unknown or changed key refuses the\n    connection (PERMANENT: a person must confirm the new key).\n  * Upload is atomic: the file is written as ".<name>.part" in the target\n    directory and then RENAMED to its final name. Importers must ignore dot-files\n    and ".part" files (the target\'s documentation says so). The rename is the\n    only commit point:\n      - a failure before it           TRANSIENT (nothing visible to the ERP)\n      - a failure during it           UNCERTAIN: the ledger PROBES (the final file\n                                      with our size and sha256, or its ack) and\n                                      only then decides\n  * The final name is deterministic per posting, so a probe knows what to look for.\n\nAcknowledgements are files the ERP (or its EDI partner) writes: a 997 in the\nack directory (X12), "<name>.ack" (ACCEPTED / REJECTED: reason, or Tally\'s import\nRESPONSE XML), or -- DELIVERY mode -- the delivered file itself.\n"""\n\nfrom __future__ import annotations\n\nimport base64\nimport hashlib\nimport io\nimport posixpath\nimport re\nimport socket\nimport stat\nfrom dataclasses import dataclass, field\nfrom typing import Any, Callable, Mapping, Optional\n\nfrom app.services.erp import vocabulary as v\n\nMAX_ACK_FILES = 200\nMAX_ACK_BYTES = 1024 * 1024\n\n\nclass SftpError(RuntimeError):\n    def __init__(self, kind: str, message: str) -> None:\n        super().__init__(message)\n        self.kind = kind\n\n\n#: The gates allow the loopback mock server (never in production: see `_resolve`).\nallow_private_for_tests = False\n\n\ndef fingerprint(key: Any) -> str:\n    """ssh-keygen style SHA256 fingerprint of a paramiko key."""\n    digest = hashlib.sha256(key.asbytes()).digest()\n    return "SHA256:" + base64.b64encode(digest).decode().rstrip("=")\n\n\ndef settings(config: Mapping[str, Any]) -> dict:\n    s = dict(config.get("sftp") or {})\n    host = str(s.get("host") or "").strip()\n    if not host or not re.fullmatch(r"[A-Za-z0-9.-]{1,253}", host):\n        raise SftpError(v.OUTCOME_PERMANENT, "the target needs sftp.host, a host name")\n    port = int(s.get("port") or 22)\n    if not 1 <= port <= 65535:\n        raise SftpError(v.OUTCOME_PERMANENT, "sftp.port is 1 to 65535")\n    pin = str(s.get("host_key_sha256") or "").strip()\n    if not re.fullmatch(r"SHA256:[A-Za-z0-9+/]{43}", pin):\n        raise SftpError(v.OUTCOME_PERMANENT, "sftp.host_key_sha256 must be the server\'s pinned key fingerprint "\n                                             "(SHA256:<43 base64 characters>, as ssh-keygen -l prints it)")\n    directory = str(s.get("directory") or "/").strip() or "/"\n    ack_dir = str(s.get("ack_directory") or directory).strip() or directory\n    for name, value in (("directory", directory), ("ack_directory", ack_dir)):\n        if not value.startswith("/") or ".." in value.split("/") or "\\x00" in value:\n            raise SftpError(v.OUTCOME_PERMANENT, f"sftp.{name} is an absolute path without \'..\'")\n    return {"host": host, "port": port, "pin": pin, "directory": directory.rstrip("/") or "/",\n            "ack_directory": ack_dir.rstrip("/") or "/", "timeout": float(s.get("timeout_seconds") or 30)}\n\n\ndef _resolve(host: str, port: int) -> list[str]:\n    from app.core import ssrf_client as S\n\n    if allow_private_for_tests:\n        from app.core.config import settings as app_settings\n\n        if getattr(app_settings, "ENVIRONMENT", "development") == "production":\n            raise SftpError(v.OUTCOME_PERMANENT, "private addresses are never allowed in production")\n        return [info[4][0] for info in socket.getaddrinfo(host, port, proto=socket.IPPROTO_TCP)]\n    try:\n        return S.resolve_and_validate(host, port, timeout=5.0)\n    except S.ForbiddenAddressError as exc:\n        raise SftpError(v.OUTCOME_PERMANENT, f"refused by the egress guard: {exc}") from exc\n    except (S.DNSResolutionError, S.TimeoutExceededError) as exc:\n        raise SftpError(v.OUTCOME_TRANSIENT, str(exc)) from exc\n\n\ndef load_private_key(text: str, passphrase: Optional[str]) -> Any:\n    import paramiko\n\n    last: Optional[Exception] = None\n    for cls in (paramiko.Ed25519Key, paramiko.ECDSAKey, paramiko.RSAKey):\n        try:\n            return cls.from_private_key(io.StringIO(text), password=passphrase or None)\n        except Exception as exc:  # noqa: BLE001\n            last = exc\n    raise SftpError(v.OUTCOME_PERMANENT, f"the private key could not be read ({type(last).__name__})")\n\n\n@dataclass\nclass Delivery:\n    kind: str\n    remote_path: Optional[str] = None\n    size: Optional[int] = None\n    message: str = ""\n    log: list[dict] = field(default_factory=list)\n\n\nclass Connection:\n    def __init__(self, *, config: Mapping[str, Any], auth_mode: str, credential: Optional[dict]) -> None:\n        self.cfg = settings(config)\n        self.auth_mode = auth_mode\n        self.credential = dict(credential or {})\n        self.transport: Any = None\n        self.sftp: Any = None\n\n    def __enter__(self) -> "Connection":\n        import paramiko\n\n        cfg = self.cfg\n        last: Optional[Exception] = None\n        sock = None\n        for ip in _resolve(cfg["host"], cfg["port"]):\n            try:\n                sock = socket.create_connection((ip, cfg["port"]), timeout=cfg["timeout"])\n                break\n            except OSError as exc:\n                last = exc\n        if sock is None:\n            raise SftpError(v.OUTCOME_TRANSIENT, f"could not connect: {last}")\n        try:\n            transport = paramiko.Transport(sock)\n            transport.banner_timeout = cfg["timeout"]\n            transport.start_client(timeout=cfg["timeout"])\n            key = transport.get_remote_server_key()\n            seen = fingerprint(key)\n            if seen != cfg["pin"]:\n                transport.close()\n                raise SftpError(v.OUTCOME_PERMANENT, f"the server\'s host key {seen} is not the pinned "\n                                                     f"{cfg[\'pin\']}: refused (confirm the new key before posting)")\n            username = str(self.credential.get("username") or "")\n            if self.auth_mode == v.AUTH_SSH_PASSWORD:\n                transport.auth_password(username, str(self.credential.get("password") or ""))\n            elif self.auth_mode == v.AUTH_SSH_KEY:\n                transport.auth_publickey(username, load_private_key(str(self.credential.get("private_key") or ""),\n                                                                    self.credential.get("passphrase")))\n            else:\n                raise SftpError(v.OUTCOME_PERMANENT, f"{self.auth_mode} is not an SSH authentication")\n            if not transport.is_authenticated():\n                raise SftpError(v.OUTCOME_PERMANENT, "the server did not accept the credential")\n            self.transport = transport\n            self.sftp = paramiko.SFTPClient.from_transport(transport)\n            self.sftp.get_channel().settimeout(cfg["timeout"])\n        except SftpError:\n            sock.close()\n            raise\n        except paramiko.AuthenticationException as exc:\n            sock.close()\n            raise SftpError(v.OUTCOME_PERMANENT, f"authentication failed: {exc}") from exc\n        except (paramiko.SSHException, OSError, EOFError) as exc:\n            sock.close()\n            raise SftpError(v.OUTCOME_TRANSIENT, f"SSH negotiation failed: {exc}") from exc\n        return self\n\n    def __exit__(self, *exc: Any) -> None:\n        for thing in (self.sftp, self.transport):\n            try:\n                if thing is not None:\n                    thing.close()\n            except Exception:  # noqa: BLE001\n                pass\n\n    def _stat(self, path: str) -> Optional[Any]:\n        try:\n            return self.sftp.stat(path)\n        except IOError:\n            return None\n\n    def remote_sha(self, path: str, limit: int = v.MAX_RENDERED_BYTES) -> Optional[str]:\n        st = self._stat(path)\n        if st is None or st.st_size > limit:\n            return None\n        with self.sftp.open(path, "rb") as fh:\n            return hashlib.sha256(fh.read()).hexdigest()\n\n    def upload(self, filename: str, data: bytes, sha256: str) -> Delivery:\n        cfg = self.cfg\n        if "/" in filename or filename.startswith("."):\n            return Delivery(v.OUTCOME_PERMANENT, message="unsafe file name")\n        final = posixpath.join(cfg["directory"], filename)\n        temp = posixpath.join(cfg["directory"], f".{filename}.part")\n        existing = self._stat(final)\n        if existing is not None:\n            same = self.remote_sha(final) == sha256\n            return Delivery(v.OUTCOME_FOUND if same else v.OUTCOME_PERMANENT, final, existing.st_size,\n                            "already on the server" if same else "a DIFFERENT file already has this name")\n        try:\n            self.sftp.putfo(io.BytesIO(data), temp, file_size=len(data), confirm=True)\n        except Exception as exc:  # noqa: BLE001 - the ERP never sees a .part file\n            return Delivery(v.OUTCOME_TRANSIENT, message=f"upload failed before commit: {exc}")\n        try:\n            try:\n                self.sftp.posix_rename(temp, final)\n            except IOError:\n                self.sftp.rename(temp, final)\n        except Exception as exc:  # noqa: BLE001 - the rename may or may not have happened\n            return Delivery(v.OUTCOME_UNCERTAIN, final, message=f"the rename to the final name failed: {exc}")\n        st = self._stat(final)\n        if st is None or st.st_size != len(data):\n            return Delivery(v.OUTCOME_UNCERTAIN, final, message="the file is not on the server with its size after "\n                                                               "the rename (an importer may already have taken it)")\n        return Delivery(v.OUTCOME_OK, final, st.st_size, f"uploaded to {final}")\n\n    def probe(self, final: str, sha256: str) -> str:\n        """FOUND (our bytes are there), ABSENT (nothing by that name), or MISMATCH (another file)."""\n        st = self._stat(final)\n        if st is None:\n            return v.OUTCOME_ABSENT\n        return v.OUTCOME_FOUND if self.remote_sha(final) == sha256 else v.OUTCOME_MISMATCH\n\n    def ack_files(self, *, name: Optional[str] = None) -> list[tuple[str, bytes]]:\n        """(name, content) of candidate acknowledgement files: "<name>.ack" when a name is given, else the ack\n        directory\'s newest regular files (997s), bounded."""\n        cfg = self.cfg\n        if name is not None:\n            path = posixpath.join(cfg["ack_directory"], f"{name}.ack")\n            st = self._stat(path)\n            if st is None or st.st_size > MAX_ACK_BYTES:\n                return []\n            with self.sftp.open(path, "rb") as fh:\n                return [(f"{name}.ack", fh.read())]\n        try:\n            entries = self.sftp.listdir_attr(cfg["ack_directory"])\n        except IOError:\n            return []\n        files = [e for e in entries if stat.S_ISREG(e.st_mode or 0) and not e.filename.startswith(".")\n                 and (e.st_size or 0) <= MAX_ACK_BYTES]\n        files.sort(key=lambda e: e.st_mtime or 0, reverse=True)\n        out = []\n        for e in files[:MAX_ACK_FILES]:\n            with self.sftp.open(posixpath.join(cfg["ack_directory"], e.filename), "rb") as fh:\n                out.append((e.filename, fh.read()))\n        return out\n\n\ndef parse_ack_file(content: bytes) -> tuple[str, str, Optional[str]]:\n    """(outcome, message, external id) from a "<name>.ack" file: a Tally RESPONSE, a JSON {status, id, message},\n    or text beginning ACCEPTED / REJECTED."""\n    text = content.decode("utf-8", "replace").strip()\n    if text.startswith("<"):\n        from app.services.erp.formats import tally\n\n        try:\n            return tally.correlate(tally.parse_response(content))\n        except tally.TallyError as exc:\n            return v.OUTCOME_MISMATCH, f"an acknowledgement that could not be read: {exc}", None\n    if text.startswith("{"):\n        import json\n\n        try:\n            doc = json.loads(text)\n        except ValueError:\n            return v.OUTCOME_MISMATCH, "an acknowledgement that is not valid JSON", None\n        status = str(doc.get("status", "")).upper()\n        ident = doc.get("id") or doc.get("external_id")\n        if status in ("ACCEPTED", "OK", "POSTED", "DONE"):\n            return v.OUTCOME_ACCEPTED, str(doc.get("message") or "accepted"), None if ident is None else str(ident)\n        if status in ("REJECTED", "ERROR", "FAILED"):\n            return v.OUTCOME_REJECTED, str(doc.get("message") or "rejected"), None\n        return v.OUTCOME_MISMATCH, f"an acknowledgement with status {status!r}", None\n    head, _, rest = text.partition(":")\n    word = head.strip().upper()\n    if word.startswith("ACCEPTED"):\n        return v.OUTCOME_ACCEPTED, "accepted", (rest.strip() or None)\n    if word.startswith("REJECTED"):\n        return v.OUTCOME_REJECTED, rest.strip() or "rejected", None\n    return v.OUTCOME_MISMATCH, f"an acknowledgement that says {text[:80]!r}", None\n\n\n__all__ = ["Connection", "Delivery", "SftpError", "fingerprint", "load_private_key", "parse_ack_file", "settings"]\n'),
    Op(path='backend/app/services/erp/vocabulary.py', kind='new', final_sha='7c11ffe3bba349506d893ec7e6bd7eadb46f6b9592024d1f769be0032a0f04f5', encoding='utf-8', executable=False,
       variants=(), content='"""ARCH47-S1:vocabulary — every constant the posting engine, its migration and its gates share.\n\nalembic/versions/arch47_step1_erp_posting.py mirrors the tuples below in its\nCHECK constraints; verify_arch47 T2 compares the two.\n"""\n\nfrom __future__ import annotations\n\nfrom typing import Final\n\n#: Bumped whenever the canonical object or a renderer can produce different bytes for the same input.\nENGINE_VERSION: Final = "erp-1"\n\n# -- what is posted ---------------------------------------------------------------\nOBJECT_VENDOR_BILL: Final = "VENDOR_BILL"\nOBJECT_PURCHASE_ORDER: Final = "PURCHASE_ORDER"\nOBJECT_GOODS_RECEIPT: Final = "GOODS_RECEIPT"\nOBJECT_JOURNAL_ENTRY: Final = "JOURNAL_ENTRY"\nOBJECT_PAYMENT_REFERENCE: Final = "PAYMENT_REFERENCE"\nOBJECT_KINDS: Final = (OBJECT_VENDOR_BILL, OBJECT_PURCHASE_ORDER, OBJECT_GOODS_RECEIPT, OBJECT_JOURNAL_ENTRY,\n                       OBJECT_PAYMENT_REFERENCE)\nOBJECT_LABELS: Final = {\n    OBJECT_VENDOR_BILL: "Vendor bill", OBJECT_PURCHASE_ORDER: "Purchase order", OBJECT_GOODS_RECEIPT: "Goods receipt",\n    OBJECT_JOURNAL_ENTRY: "Journal entry", OBJECT_PAYMENT_REFERENCE: "Payment reference",\n}\n\n# -- the approved outcome it is built from ------------------------------------------\nSOURCE_PROCUREMENT_CASE: Final = "PROCUREMENT_CASE"   # an ARCH-31 three-way match, APPROVED (a reconciled invoice)\nSOURCE_TABLE: Final = "TABLE"                         # an ARCH-44 table a person ACCEPTED (status REVIEWED)\nSOURCE_CASE: Final = "CASE"                           # an ARCH-43 case that reached COMPLETE\nSOURCE_KINDS: Final = (SOURCE_PROCUREMENT_CASE, SOURCE_TABLE, SOURCE_CASE)\nSOURCE_LABELS: Final = {SOURCE_PROCUREMENT_CASE: "Reconciled invoice", SOURCE_TABLE: "Confirmed table",\n                        SOURCE_CASE: "Completed case"}\n#: Which objects each kind of outcome can yield (a builder may still find it lacks what one needs).\nSOURCE_OBJECTS: Final = {\n    SOURCE_PROCUREMENT_CASE: (OBJECT_VENDOR_BILL, OBJECT_PURCHASE_ORDER, OBJECT_GOODS_RECEIPT, OBJECT_JOURNAL_ENTRY,\n                              OBJECT_PAYMENT_REFERENCE),\n    SOURCE_TABLE: (OBJECT_JOURNAL_ENTRY, OBJECT_VENDOR_BILL),\n    SOURCE_CASE: (OBJECT_VENDOR_BILL, OBJECT_PURCHASE_ORDER, OBJECT_GOODS_RECEIPT, OBJECT_JOURNAL_ENTRY,\n                  OBJECT_PAYMENT_REFERENCE),\n}\n\n# -- where it goes ------------------------------------------------------------------\nFORMAT_CSV: Final = "CSV"\nFORMAT_XLSX: Final = "XLSX"\nFORMAT_X12: Final = "X12"\nFORMAT_UBL: Final = "UBL"\nFORMAT_TALLY: Final = "TALLY"\nFORMAT_JSON: Final = "JSON"\nFORMATS: Final = (FORMAT_CSV, FORMAT_XLSX, FORMAT_X12, FORMAT_UBL, FORMAT_TALLY, FORMAT_JSON)\nFORMAT_LABELS: Final = {FORMAT_CSV: "CSV (RFC 4180)", FORMAT_XLSX: "Excel workbook (.xlsx)",\n                        FORMAT_X12: "EDI X12 004010 (810 / 850 / 856)", FORMAT_UBL: "UBL 2.1 XML",\n                        FORMAT_TALLY: "Tally Prime XML", FORMAT_JSON: "REST / OData JSON"}\n\nTRANSPORT_DOWNLOAD: Final = "DOWNLOAD"   # the file is kept here; a person imports it and confirms\nTRANSPORT_SFTP: Final = "SFTP"           # uploaded to the target\'s SFTP server (host key pinned)\nTRANSPORT_HTTP: Final = "HTTP"           # sent to the target\'s REST / OData API over HTTPS\nTRANSPORTS: Final = (TRANSPORT_DOWNLOAD, TRANSPORT_SFTP, TRANSPORT_HTTP)\n\nPRESET_NONE: Final = "NONE"\nPRESET_QBO: Final = "QUICKBOOKS_ONLINE"\nPRESET_ZOHO: Final = "ZOHO_BOOKS"\nPRESET_BC: Final = "BUSINESS_CENTRAL"\nPRESET_S4: Final = "S4HANA_ODATA"\nPRESET_NETSUITE: Final = "NETSUITE_REST"\nPRESET_GENERIC_REST: Final = "GENERIC_REST"\nPRESET_GENERIC_ODATA: Final = "GENERIC_ODATA"\nPRESETS: Final = (PRESET_NONE, PRESET_QBO, PRESET_ZOHO, PRESET_BC, PRESET_S4, PRESET_NETSUITE, PRESET_GENERIC_REST,\n                  PRESET_GENERIC_ODATA)\nJSON_PRESETS: Final = PRESETS[1:]\nPRESET_LABELS: Final = {PRESET_NONE: "None", PRESET_QBO: "QuickBooks Online", PRESET_ZOHO: "Zoho Books",\n                        PRESET_BC: "Dynamics 365 Business Central", PRESET_S4: "SAP S/4HANA (OData V2)",\n                        PRESET_NETSUITE: "Oracle NetSuite (REST)", PRESET_GENERIC_REST: "Generic REST",\n                        PRESET_GENERIC_ODATA: "Generic OData V4"}\n\n#: How the target says a posting is done. A posting is DONE only when the target says so.\nACK_SYNC: Final = "SYNC"            # HTTP: the response (created object, its id and echoed figures)\nACK_X12_997: Final = "X12_997"      # SFTP: a 997 functional acknowledgement naming our control numbers\nACK_FILE: Final = "ACK_FILE"        # SFTP: <file>.ack (ACCEPTED / REJECTED, or Tally\'s import response)\nACK_DELIVERY: Final = "DELIVERY"    # SFTP: the renamed file is on the server with our size and sha256 (delivery only)\nACK_MANUAL: Final = "MANUAL"        # DOWNLOAD: a person confirms the import (or uploads the ERP\'s response file)\nACK_MODES: Final = (ACK_SYNC, ACK_X12_997, ACK_FILE, ACK_DELIVERY, ACK_MANUAL)\nACK_BY_TRANSPORT: Final = {TRANSPORT_HTTP: (ACK_SYNC,), TRANSPORT_SFTP: (ACK_X12_997, ACK_FILE, ACK_DELIVERY),\n                           TRANSPORT_DOWNLOAD: (ACK_MANUAL,)}\n\nAUTH_NONE: Final = "NONE"\nAUTH_BEARER: Final = "BEARER"\nAUTH_BASIC: Final = "BASIC"\nAUTH_API_KEY: Final = "API_KEY_HEADER"\nAUTH_OAUTH2_REFRESH: Final = "OAUTH2_REFRESH_TOKEN"\nAUTH_OAUTH2_CLIENT: Final = "OAUTH2_CLIENT_CREDENTIALS"\nAUTH_SSH_PASSWORD: Final = "SSH_PASSWORD"\nAUTH_SSH_KEY: Final = "SSH_KEY"\nAUTH_MODES: Final = (AUTH_NONE, AUTH_BEARER, AUTH_BASIC, AUTH_API_KEY, AUTH_OAUTH2_REFRESH, AUTH_OAUTH2_CLIENT,\n                     AUTH_SSH_PASSWORD, AUTH_SSH_KEY)\nAUTH_BY_TRANSPORT: Final = {TRANSPORT_HTTP: (AUTH_BEARER, AUTH_BASIC, AUTH_API_KEY, AUTH_OAUTH2_REFRESH,\n                                             AUTH_OAUTH2_CLIENT),\n                            TRANSPORT_SFTP: (AUTH_SSH_PASSWORD, AUTH_SSH_KEY), TRANSPORT_DOWNLOAD: (AUTH_NONE,)}\n\nTARGET_ACTIVE: Final = "ACTIVE"\nTARGET_DISABLED: Final = "DISABLED"\nTARGET_STATUSES: Final = (TARGET_ACTIVE, TARGET_DISABLED)\n\nMAPPING_ACTIVE: Final = "ACTIVE"\nMAPPING_RETIRED: Final = "RETIRED"\nMAPPING_STATUSES: Final = (MAPPING_ACTIVE, MAPPING_RETIRED)\n\n# -- the ledger -----------------------------------------------------------------------\nSTATE_PENDING: Final = "PENDING"          # planned, rendered, not yet sent\nSTATE_SENDING: Final = "SENDING"          # one worker holds the lease and is talking to the target\nSTATE_RETRYING: Final = "RETRYING"        # a transient failure; sent again at next_attempt_at\nSTATE_DELIVERED: Final = "DELIVERED"      # the target has it; waiting for its acknowledgement\nSTATE_DONE: Final = "DONE"                # the target said it is posted\nSTATE_FAILED: Final = "FAILED"            # could not be sent (retries exhausted, or it could not be rendered)\nSTATE_REJECTED: Final = "REJECTED"        # the target refused it\nSTATE_MISMATCH: Final = "MISMATCH"        # the target acknowledged something other than what was sent\nSTATE_UNCERTAIN: Final = "UNCERTAIN"      # the outcome of a send is unknown and cannot be probed: a person decides\nSTATE_CANCELLED: Final = "CANCELLED"      # a person decided it will not be posted\nSTATES: Final = (STATE_PENDING, STATE_SENDING, STATE_RETRYING, STATE_DELIVERED, STATE_DONE, STATE_FAILED,\n                 STATE_REJECTED, STATE_MISMATCH, STATE_UNCERTAIN, STATE_CANCELLED)\nSENDABLE_STATES: Final = (STATE_PENDING, STATE_RETRYING)\n#: A person must act: the review hub (POSTING) and the posting.failed trigger.\nEXCEPTION_STATES: Final = (STATE_FAILED, STATE_REJECTED, STATE_MISMATCH, STATE_UNCERTAIN)\nFINAL_STATES: Final = (STATE_DONE, STATE_CANCELLED)\nOPEN_STATES: Final = (STATE_PENDING, STATE_SENDING, STATE_RETRYING, STATE_DELIVERED)\nSTATE_LABELS: Final = {STATE_PENDING: "Queued", STATE_SENDING: "Sending", STATE_RETRYING: "Retrying",\n                       STATE_DELIVERED: "Awaiting acknowledgement", STATE_DONE: "Posted", STATE_FAILED: "Failed",\n                       STATE_REJECTED: "Rejected", STATE_MISMATCH: "Acknowledgement mismatch",\n                       STATE_UNCERTAIN: "Outcome unknown", STATE_CANCELLED: "Cancelled"}\n\nORIGIN_MANUAL: Final = "MANUAL"      # a person pressed "Post"\nORIGIN_AUTO: Final = "AUTO"          # the target\'s auto-post rule (the sweep)\nORIGIN_FLOW: Final = "FLOW"          # the erp.post Flow Builder action\nORIGINS: Final = (ORIGIN_MANUAL, ORIGIN_AUTO, ORIGIN_FLOW)\n\n# -- attempts (every step the ledger took) ---------------------------------------------\nATTEMPT_RENDER: Final = "RENDER"\nATTEMPT_SEND: Final = "SEND"\nATTEMPT_PROBE: Final = "PROBE"\nATTEMPT_ACK: Final = "ACK"\nATTEMPT_REVIEW: Final = "REVIEW"\nATTEMPT_KINDS: Final = (ATTEMPT_RENDER, ATTEMPT_SEND, ATTEMPT_PROBE, ATTEMPT_ACK, ATTEMPT_REVIEW)\n\nOUTCOME_OK: Final = "OK"\nOUTCOME_TRANSIENT: Final = "TRANSIENT"      # retry later\nOUTCOME_PERMANENT: Final = "PERMANENT"      # will not work by trying again (refused, invalid)\nOUTCOME_UNCERTAIN: Final = "UNCERTAIN"      # the request may or may not have taken effect\nOUTCOME_FOUND: Final = "FOUND"              # a probe found the object at the target\nOUTCOME_ABSENT: Final = "ABSENT"            # a probe proved it is not there\nOUTCOME_PENDING: Final = "PENDING"          # no acknowledgement yet\nOUTCOME_ACCEPTED: Final = "ACCEPTED"\nOUTCOME_REJECTED: Final = "REJECTED"\nOUTCOME_MISMATCH: Final = "MISMATCH"\nATTEMPT_OUTCOMES: Final = (OUTCOME_OK, OUTCOME_TRANSIENT, OUTCOME_PERMANENT, OUTCOME_UNCERTAIN, OUTCOME_FOUND,\n                           OUTCOME_ABSENT, OUTCOME_PENDING, OUTCOME_ACCEPTED, OUTCOME_REJECTED, OUTCOME_MISMATCH)\n\n# -- the review hub ------------------------------------------------------------------\nREVIEW_KIND: Final = "POSTING"\nREVIEW_REASON: Final = "POSTING_EXCEPTION"\nVERDICT_RETRY: Final = "RETRY"       # send again (for UNCERTAIN: a person checked the target does not have it)\nVERDICT_ACCEPT: Final = "ACCEPT"     # the target has it: mark it posted (with the target\'s reference)\nVERDICT_CANCEL: Final = "CANCEL"     # it will not be posted\nVERDICTS: Final = (VERDICT_RETRY, VERDICT_ACCEPT, VERDICT_CANCEL)\n\n# -- Flow Builder --------------------------------------------------------------------\nEVENT_POSTING_FAILED: Final = "trigger.posting.failed"\nACTION_TYPE: Final = "erp.post"\n#: The triggers whose event names an approved outcome erp.post can post (event payload key -> source kind).\nACTION_TRIGGER_SOURCES: Final = {"procurement.approved": ("case_id", SOURCE_PROCUREMENT_CASE),\n                                 "case.completed": ("case_id", SOURCE_CASE)}\n\n# -- jobs -------------------------------------------------------------------------------\nJOB_DELIVER: Final = "erp.deliver_posting"\n\n# -- limits and timing ---------------------------------------------------------------------\nMAX_TARGETS_PER_WORKSPACE: Final = 50\nMAX_LOOKUP_TABLES: Final = 100\nMAX_LOOKUP_ENTRIES: Final = 5000\nMAX_MAPPING_BYTES: Final = 65536\nMAX_MAPPING_FIELDS: Final = 200\nMAX_EXPRESSION_DEPTH: Final = 6\nMAX_TRANSFORMS: Final = 12\nMAX_LINES: Final = 2000\nMAX_RENDERED_BYTES: Final = 5 * 1024 * 1024\nDEFAULT_MAX_ATTEMPTS: Final = 6\nMAX_MAX_ATTEMPTS: Final = 10\n#: Retry delay: min(CEILING, BASE * 2**(n-1)), then full jitter in [delay/2, delay].\nRETRY_BASE_SECONDS: Final = 30\nRETRY_CEILING_SECONDS: Final = 3600\nSEND_LEASE_SECONDS: Final = 300\nDEFAULT_ACK_TIMEOUT_HOURS: Final = 72\n#: A posting is DONE only if the target\'s figures match what was sent within this (per currency minor unit).\nACK_AMOUNT_TOLERANCE_MINOR: Final = 1\n\n#: ISO 4217 minor units for currencies that are not 2 (every other code is 2).\nCURRENCY_EXPONENTS: Final = {"JPY": 0, "KRW": 0, "VND": 0, "CLP": 0, "ISK": 0, "UGX": 0, "XAF": 0, "XOF": 0, "XPF": 0,\n                             "KWD": 3, "BHD": 3, "OMR": 3, "JOD": 3, "IQD": 3, "LYD": 3, "TND": 3}\n\n\ndef currency_exponent(code: str) -> int:\n    return CURRENCY_EXPONENTS.get((code or "").upper(), 2)\n\n\n__all__ = [name for name in dir() if name.isupper() or name == "currency_exponent"]\n'),
    Op(path='backend/app/services/review/resolution.py', kind='edit', final_sha='98556853422a8fbf2845fcc3a8df63e5f3ec19af938e0496cb95d6cb9f98cefc', encoding='utf-8', executable=False,
       variants=(('e2f187ca50721f3faad28663c680e7f94b101c735fddfc433fdbc58a368b2385', (('    vocab.KIND_OBLIGATION: _resolve_obligation,  # ARCH46-S1:resolve-obligation\n}\n', '    vocab.KIND_OBLIGATION: _resolve_obligation,  # ARCH46-S1:resolve-obligation\n    vocab.KIND_POSTING: _resolve_posting,  # ARCH47-S1:resolve-posting\n}\n'), ('\n_DISPATCH = {\n', '\ndef _resolve_posting(\n    db: Session, *, item: ReviewItem, actor_user_id: uuid.UUID, payload: ResolvePayload\n) -> str:\n    """ARCH47-S1:resolve-posting. A person settles an ERP posting in an exception state: RETRY sends it again\n    (a posting that never rendered is rendered again with today\'s mapping), ACCEPT records it as posted, CANCEL\n    closes it. The ledger keeps the posting either way (one posting per object and target)."""\n    from app.models.erp import ErpPosting\n    from app.services.erp import service as erp_service\n    from app.services.erp import vocabulary as ev\n\n    verdict = (payload.posting_verdict or "").strip().upper()\n    if verdict not in ev.VERDICTS:\n        raise ReviewResolutionError("A posting review needs posting_verdict: RETRY, ACCEPT or CANCEL.")\n    row = db.execute(\n        select(ErpPosting).where(ErpPosting.id == item.item_id, ErpPosting.workspace_id == item.workspace_id)\n    ).scalar_one_or_none()\n    if row is None:\n        raise ReviewResolutionError("This posting no longer exists.")\n    try:\n        erp_service.review(db, posting=row, verdict=verdict, actor_user_id=actor_user_id, note=payload.note,\n                           reference=payload.posting_reference)\n    except erp_service.ErpError as exc:\n        raise ReviewResolutionError(str(exc)) from exc\n    return verdict\n\n\n_DISPATCH = {\n'), ('    obligation_verdict: Optional[str] = None\n\n', '    obligation_verdict: Optional[str] = None\n    #: ARCH47-S1:posting-verdict. POSTING -- RETRY (send it again; for an\n    #: UNCERTAIN posting, a person checked the target does not have it), ACCEPT\n    #: (the target has it: posting_reference is its id there) or CANCEL.\n    posting_verdict: Optional[str] = None\n    posting_reference: Optional[str] = None\n\n'))),) + (), content=''),
    Op(path='backend/app/services/review/vocabulary.py', kind='edit', final_sha='835c65eb3b98cc167f8614f5ef573e1bc7324879824f42932d2a0c279c82882e', encoding='utf-8', executable=False,
       variants=(('db9ac29f6bbc3e1fac74493adc7fd886d352f77768b41450d4b9585bcff85126', (('    "KIND_OBLIGATION",\n    "MAX_BULK_IDS",\n', '    "KIND_OBLIGATION",\n    "KIND_POSTING",\n    "MAX_BULK_IDS",\n'), ('    REASON_OBLIGATION_UNCONFIRMED,\n)\n', '    REASON_OBLIGATION_UNCONFIRMED,\n    REASON_POSTING_EXCEPTION,\n)\n'), ('REASON_OBLIGATION_UNCONFIRMED: Final[str] = "OBLIGATION_UNCONFIRMED"\n\n', 'REASON_OBLIGATION_UNCONFIRMED: Final[str] = "OBLIGATION_UNCONFIRMED"\n#: ARCH47-S1:review-reason-posting. arch47_step1_erp_posting\'s view produces it.\nREASON_POSTING_EXCEPTION: Final[str] = "POSTING_EXCEPTION"\n\n'), ('KIND_OBLIGATION: Final[str] = REVIEW_KIND_OBLIGATION\n\n', 'KIND_OBLIGATION: Final[str] = REVIEW_KIND_OBLIGATION\n#: ARCH47-S1:review-kind-posting\nKIND_POSTING: Final[str] = REVIEW_KIND_POSTING\n\n'), ('    REVIEW_KIND_OBLIGATION,\n    REVIEW_KINDS,\n', '    REVIEW_KIND_OBLIGATION,\n    REVIEW_KIND_POSTING,\n    REVIEW_KINDS,\n'))),) + (), content=''),
    Op(path='backend/app/services/tools/flow_selectors.py', kind='edit', final_sha='e7bd5e323f3dbc7b563caabe1b2df239a362ce156c8eef0aa2c0d14f52d1c86b', encoding='utf-8', executable=False,
       variants=(('7ba756a153ece1a05c36009de94ff6ddad40a000fb5b5768ac633f0d5e0399a3', (('    "select_email_send",\n    "select_notify_role",\n', '    "select_email_send",\n    "select_erp_post",\n    "select_notify_role",\n'), ('\n__all__ = [\n', '\n@register_tool_selector("automation.flow.erp_post")\ndef select_erp_post(\n    *, node_config: ActionNodeConfig, facts: FactSet, tenant: TenantScope\n) -> ActionSpec:\n    # ARCH47-S1:selector-erp-post. The target and object kinds are the author\'s;\n    # the approved outcome comes from the trigger event, never from a document.\n    return _select("automation.flow.erp_post", node_config=node_config, facts=facts, tenant=tenant)\n\n\n__all__ = [\n'))),) + (), content=''),
    Op(path='backend/app/workers/handlers/__init__.py', kind='edit', final_sha='38e41ffe208a6c52cff7d8fbcc5164f4dd0f17ae60134f6e5ea5085c1214814d', encoding='utf-8', executable=False,
       variants=(('1eaafea5757505c1afe891b85933f2834d85ae0335547620f73222a1790360c4', (('    "obligations.extract_document": _obligations_extract_document,\n}\n', '    "obligations.extract_document": _obligations_extract_document,\n    # ARCH47-S1:erp-handler. On the LIGHT profile (app/workers/profiles.py).\n    "erp.deliver_posting": _erp_deliver_posting,\n}\n'), ('\ndef _obligations_extract_document(payload: dict[str, Any]) -> dict[str, Any]:\n', '\ndef _erp_deliver_posting(payload: dict[str, Any]) -> dict[str, Any]:\n    # ARCH47-S1:erp-handler-fn\n    from app.workers.handlers.erp import handle_deliver_posting\n    return handle_deliver_posting(payload)\n\n\ndef _obligations_extract_document(payload: dict[str, Any]) -> dict[str, Any]:\n'), ('    | ARCH46_JOB_TYPES\n    | HARDENING_JOB_TYPES\n', '    | ARCH46_JOB_TYPES\n    | ARCH47_JOB_TYPES\n    | HARDENING_JOB_TYPES\n'), ('ARCH46_JOB_TYPES: frozenset[str] = frozenset({"obligations.extract_document"})\n#: HARDENING-T1:D25. The stuck-document backstop (app/workers/dead_letter.py).\n', 'ARCH46_JOB_TYPES: frozenset[str] = frozenset({"obligations.extract_document"})\n# ARCH47-S1:erp-job-types. Delivering a posting is network and file work (HTTPS, SFTP): LIGHT profile.\nARCH47_JOB_TYPES: frozenset[str] = frozenset({"erp.deliver_posting"})\n#: HARDENING-T1:D25. The stuck-document backstop (app/workers/dead_letter.py).\n'))),) + (), content=''),
    Op(path='backend/app/workers/handlers/erp.py', kind='new', final_sha='0c1a074427f4aaa16a6797babddfa18cb5f35a23e0a5c8bc0018abcf7024cd1d', encoding='utf-8', executable=False,
       variants=(), content='"""ARCH47-S1:handler — the `erp.deliver_posting` job.\n\nEnqueued when a posting is planned (a person\'s "Post", a target\'s auto-post\nsweep, the erp.post Flow Builder action), when a retry falls due and when the\nsweep reclaims an expired lease. Delivery is network and file work (HTTPS\nthrough the SSRF-safe client, SFTP through paramiko) -- no model, OCR or PDF\nengine -- so the job runs on the LIGHT worker profile (app/workers/profiles.py).\n\nSafe to run twice or concurrently: the ledger claims the posting under a row\nlock and a lease (app/services/erp/service.deliver). An organization without\ncapability.erp_posting is skipped: nothing is sent.\n"""\n\nfrom __future__ import annotations\n\nimport logging\nimport uuid\nfrom typing import Any\n\nlogger = logging.getLogger("app.workers.handlers.erp")\n\nJOB_TYPE = "erp.deliver_posting"\n\n\ndef handle_deliver_posting(payload: dict[str, Any]) -> dict[str, Any]:\n    from app.db.session import SessionLocal\n    from app.models.erp import ErpPosting\n    from app.services.erp import gate, service\n\n    raw = payload.get("posting_id")\n    if not raw:\n        raise ValueError("erp.deliver_posting requires posting_id")\n    posting_id = uuid.UUID(str(raw))\n    with SessionLocal() as db:\n        posting = db.get(ErpPosting, posting_id)\n        if posting is None:\n            return {"delivered": False, "reason": "the posting no longer exists"}\n        if not gate.capability_held(db, posting.organization_id):\n            return {"delivered": False, "reason": "capability.erp_posting not held"}\n        db.commit()  # the claim below locks the row in its own transaction\n        result = service.deliver(db, posting_id)\n    logger.info("erp.delivery", extra={"posting_id": str(posting_id), **{k: str(val) for k, val in result.items()}})\n    return result\n\n\n__all__ = ["JOB_TYPE", "handle_deliver_posting"]\n'),
    Op(path='backend/app/workers/profiles.py', kind='edit', final_sha='4b02f33b01b31fbe1c0e7e6f4d8b46af4245ccd65263e7edb414a1cd5b8413db', encoding='utf-8', executable=False,
       variants=(('9362b9640482a35436650bc6b7402442dd5b9734e938c70d13b2808040a6a902', (('            "obligations.extract_document",\n        }\n', '            "obligations.extract_document",\n            # ARCH47-S1:erp-light-profile. Delivering an ERP posting is HTTPS\n            # through the SSRF-safe client and SFTP through paramiko: network\n            # and file work, no model, OCR or PDF engine. Not optional\n            # bookkeeping (see above).\n            "erp.deliver_posting",\n        }\n'),)),) + (), content=''),
